{"assumptions":[],"created_at":"2026-10-27T19:33:43.749510+00:00","domain":"probability theory","id":"claim_00134c863a800ef3f1cb361cb8d1eb07233b3f1d5e7423ef729ed0c4c187e4e8","kind":"lemma","schema_version":1,"statement":"[Lemma lem:fokker_superpo of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let $\nu\in\mathcal{P}(\mathbb{R}^d)$ and let ${\boldsymbol\mu}:[0,\infty)\to \mathcal{M}_{+}(\mathbb{R}^d)$ (with ${\boldsymbol\mu}_0 = \nu$) be such that
\begin{equation}
\big[(t,x)\mapsto {\bf b}(t,x,{\boldsymbol\mu}_t)\big],  \ \big[ (t,x)\mapsto {\boldsymbol\sigma} {\boldsymbol\sigma}^\top(t,x,{\boldsymbol\mu}_t)\big] \in L^{1}_{\text{loc}}([0,\infty) \times \mathbb{R}^d , \overline{\boldsymbol\mu}),
\end{equation}
with $\overline{\boldsymbol\mu}$ as in Notation (not:measure_dt_dx of the paper).

Then:

\begin{itemize}
\item[(i)] If $X$ is a solution to MKV$({\bf b},{\boldsymbol\sigma};\nu)$, with $[X_t]={\boldsymbol\mu}_t $ for $t\geq0$, then ${\boldsymbol\mu}$ is a weak solution to NL-FP$({\bf b},{\boldsymbol\sigma};\nu)$.
\item[(ii)] [Superposition] Under the additional assumption that 
\begin{equation}
\Big[ t \mapsto \int_{\mathbb{R}^d} \Big( |{\bf b}(t,x,{\boldsymbol\mu}_t)| + \| {\boldsymbol\sigma}{\boldsymbol\sigma}^\top(t,x,{\boldsymbol\mu}_t) \| \Big) {\boldsymbol\mu}_t (d x)\Big], \  \big[ t \mapsto {\boldsymbol\mu}_{t} (\mathbb{R}^d) \big]  \in L^{\infty}_{\text{loc}}([0,\infty) ,
\end{equation}

if ${\boldsymbol\mu}$ is a (weak) solution to NL-FP$({\bf b},{\boldsymbol\sigma};\nu)$, 
 then there exists a solution $X$ to MKV$({\bf b},{\boldsymbol\sigma};\nu)$ such that $ [X_t] = {\boldsymbol\mu}_t $.

\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:41:11.649058+00:00","domain":"probability theory","id":"claim_00152b42f7a290b779d3bd2c718792f3c4b04f8e34b6e3e40ed935b852c66f97","kind":"lemma","schema_version":1,"statement":"[Lem LastOne of arXiv:2411.13926, 'Random walks on random walks:\\ non-perturbative results in high dimensions'] Let $Y_k^{(1)} \in I^{(1)}$ be the random lift of $y_k \in I^{(k)}$. Then 
\begin{align}
\ensuremath{\mathbb{P}}(Y_k^{(1)}=x) = P^{RW}(X \in x \;|\;  D_k), \quad x \in  I^{(1)}.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:44:17.162672+00:00","domain":"probability theory","id":"claim_00338a3661f62d473270a2b3e03727db93be3f8107c82d4dd975922bfd05fde9","kind":"concept","schema_version":1,"statement":"[Theorem 14 (Theorem 2.3 of \cite{zhang2016central}) of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] Suppose $\{Z_{n}\}$ converges to the constant $\theta^{*}$ almost surely, and that Assumptions~\eqref{gen_assump_dist_1} and \eqref{gen_assump_dist_3} are satisfied. Suppose $\rho>1/2$, and that
\begin{equation}
\sum_{i=0}^{n-1}\delta_{i}=o\left(\sqrt{n}\right) \text{ almost surely}.
\end{equation}
Then 
\begin{equation}
\sqrt{n}\left(Z_{n}-\theta^{*}\right)\convd N(0,\Sigma),
\end{equation}
where, with $\Gamma$ is the matrix mentioned in Assumption~\eqref{gen_assump_dist_3}, we set
\begin{equation}
\Sigma=\int_{0}^{\infty}\exp\left\{\left(J_{G}(\theta^{*})+I_{d}/2\right)u\right\}\Gamma\left[\exp\left\{\left(J_{G}(\theta^{*})+I_{d}/2\right)u\right\}\right]^{t}du.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:51:15.030740+00:00","domain":"probability theory","id":"claim_00584744a55aaa43f7ba0aff456f824b5012486af4d00fd5faea87c3c9a6812d","kind":"concept","schema_version":1,"statement":"[Lemma proptfund1 of arXiv:2609.03909, 'Conic Pseudo-Finslerian Mechanical Systems'] Let  $\mathcal{U} \subset TM \setminus 0$ be an open subset invariant under positive scalar multiplication and let$ \mathcal L$ be a Lagrangian, of class $C^2$ on $\mathcal U$, which is positively $2$-homogeneous. Then its fundamental tensor satisfies the following properties:
\begin{enumerate}
    \item[(i)] $g_v$ is positively homogeneous of degree 0, that is, $g_{\lambda v}=g_{v}$ for any $\lambda >0;$
    \item[(ii)] $g_v(v,v)=2\mathcal L(v);$
    \item[(iii)] $g_v(v,w)=\ell_v(w)=d\mathcal L_v(w)$ for any $w\in T_{\pi(v)}M.$
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:13:18.536584+00:00","domain":"probability theory","id":"claim_0072906a73c197a3988979d34c8efcff0a7415d3b7692407f4d8af50aa1a90cf","kind":"concept","schema_version":1,"statement":"[Lemma 19 of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] \begin{equation*}{
