{"assumptions":[],"created_at":"2026-10-27T23:01:54.285905+00:00","domain":"probability theory","id":"claim_053c9fee547d867d3bb5bc128fa08731469738c9f42838ee275cf3b53a2205a1","kind":"concept","schema_version":1,"statement":"[Lem A1 of arXiv:2411.01847, 'Well-Posedness of Stochastic Chemotaxis System'] Let $\left(e^{-tA}\right)_{t\geq 0}$ be the Neumann heat semigroup in $\mathcal{O}$.

       Let $\nu_1$ denote the first nonzero eigenvalue of $A$ on $\mathcal{O}$ under Neumann boundary condition. Then, there exists a constant $C$, depending only on $\mathcal{O}$, such that:
      \begin{itemize}
  \item[(\romannumeral 1)] If $1\leq p\leq \infty$, for $t>0$
  \begin{align}
      \|(A+1)^\beta e^{-tA} \omega\|_{p}\leq Ct^{-\beta}e^{-\nu_1t}\|\omega\|_{p},\\
       \|\nabla e^{-tA} \omega\|_{p}\leq C(1+t^{-\frac{1}{2}})e^{-\nu_1t}\|\omega\|_{p},
  \end{align}
holds for all $\omega\in L^{p}(\mathcal{O})$.
  \item[(\romannumeral 2)] If $p\in [2,\infty)$, for $t>0$
  \begin{align}
       \|\nabla e^{-tA} \omega\|_{p}\leq Ce^{-\nu_1t}\|\omega\|_{W^{1,p}(\mathcal{O})},
  \end{align}
is valid for all $\omega\in W^{1,p}(\mathcal{O})$.

\item[(\romannumeral 3)]
If $\beta>0$, $p\in (1,\infty), t>0$, then the operators $(A+1)^\beta e^{-tA}\nabla\cdot$ and $e^{-tA}\nabla\cdot$ both possess extension to  operators from $L^{p}(\mathcal{O})$ into $L^{p}(\mathcal{O})$ which fulfill
  \begin{align}
      &\|(A+1)^\beta e^{-tA}\nabla\cdot w\|_{p}\leq C(\epsilon)t^{-\frac{1}{2}-\beta-\epsilon}e^{-\nu_1 t}\|w\|_{p}, \\
      &\| e^{-tA}\nabla\cdot w\|_{p}\leq Ct^{-\frac{1}{2}}e^{-\nu_1 t}\|w\|_{p},
  \end{align}
  for all $\omega\in (L^p(\mathcal{O}))^2$, any $\epsilon>0$.






	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:34:09.923946+00:00","domain":"probability theory","id":"claim_054244f78ba3681c340daf1e0d53633855991a8a7f5e1297f3726667bef430bb","kind":"concept","schema_version":1,"statement":"[Thm 1 of arXiv:2603.27433, 'The $k$-cycle shuffling with repeated cards'] Let $(n_N)_{N\ge 1},(k_N)_{N\ge 1}$, and $(t_N)_{N\ge 1}$ be sequences of positive integers, such that $\lim_{N\rightarrow\infty}n_N=\infty$. For all $N\ge 1$, let $t'_N:=t_N-\frac{n_N\log n_N}{k_N}$. Also, let $P_{n_N,k_N}^{*t_N}$ be defined as in \Cref{defi: Pnk and its convolution}, and $\nu_{n_N,k_N}^{t_N}$ be defined as in \Cref{defi: construction of nu}. 
\begin{enumerate}
\item Suppose that 
\begin{enumerate}
\item $k_N\ge 2$ for all $N\ge 1$, and $\lim_{N\rightarrow\infty}\frac{k_N\log n_N}{n_N}=0$.
\item $t_N'=cn_N/k_N$, where $c\in\R$ is an absolute constant.
\end{enumerate}
Then, we have
$$\lim_{N\rightarrow\infty}d_{TV}(P_{n_N,k_N}^{*t_N},\nu_{n_N,k_N}^{t_N})=0.$$ 

\item Suppose that 
\begin{enumerate}
\item $k_N\ge 2$ for all $N\ge 1$, and $\limsup_{N\rightarrow\infty}\log_{n_N}k_N\le c_0$, where $c_0\in[0,1)$ is an absolute constant.
\item $\lim_{N\rightarrow\infty}\log\log n_N-|2k_Nt_N'/n_N|=+\infty$.
\end{enumerate}
Then, we have
$$\limsup_{N\rightarrow\infty}\log_{n_N}d_{TV}(P_{n_N,k_N}^{*t_N},\nu_{n_N,k_N}^{t_N})\le c_0-1.$$

\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:36:31.233540+00:00","domain":"probability theory","id":"claim_05455424e5ee00864df6e5fb6a9969e8f0c38475347d81f78961ebf331a6429c","kind":"definition","schema_version":1,"statement":"[Definition 7 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Consider a pullback square of stacks
  \begin{equation*}
    \begin{tikzcd}
