{"assumptions":[],"created_at":"2026-10-26T19:44:17.162751+00:00","domain":"probability theory","id":"claim_0832681d7d1ab04827481e1039c713982d14df8c1753f8604dec78fc5458fa87","kind":"lemma","schema_version":1,"statement":"[Lemma 15 of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] When the function $g$, defined in \eqref{g_defn}, is \emph{H\"{o}lder continuous} with constant $L$ and exponent $\alpha$ for some $0<\alpha\leqslant 1$, i.e.\ 
\begin{equation}
\left|g(x_{1},y_{1})-g(x_{2},y_{2})\right|\leqslant L\left|\left|(x_{1},y_{1})-(x_{2},y_{2})\right|\right|_{2}^{\alpha} \quad \text{for all } (x_{1},y_{1}), (x_{2},y_{2})\in\mathcal{S},
\end{equation} 
we have, for $H_{n}$ as defined in \eqref{H_{n}_defn}, $E_{n}$ as defined in \eqref{E_{n}_defn} and $\mathcal{S}_{n}$ as defined in \eqref{S_{n}_defn}, for each $n\geqslant N$:
\begin{align}
{}&\sup\left\{\left|H_{n}(x,y)-g(x,y)\right|:(x,y)\in\mathcal{S}\right\}\leqslant 2^{-\alpha/2}L\E\left[K_{n}^{-\alpha/2}\right]}\\
{}&\sup\left\{\left|E_{n}\left(\frac{r_{1}}{n},\frac{r_{2}}{n}\right)-g\left(\frac{r_{1}}{n},\frac{r_{2}}{n}\right)\right|:\left(\frac{r_{1}}{n},\frac{r_{2}}{n}\right)\in \mathcal{S}_{n}\right\}\leqslant 2^{-\alpha/2}L\E\left[K_{n}^{-\alpha/2}\right]}
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:12:09.057554+00:00","domain":"probability theory","id":"claim_083b35d81681fe3c3c065bbc0976a37debbb1e72245b816d11e4be90b7d62864","kind":"theorem","schema_version":1,"statement":"[Proposition prop:diffusion-coldstart of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Fix $K>0$, $d\ge1$, and $\gamma>0$, and let $H\in\mathbb R^{d\times d}$ be
symmetric with smallest eigenvalue $K$.
\begin{enumerate}
\item[\rm(i)] The eigenvalues of $A$ are the roots of
$\mu^2+\gamma\mu+\lambda=0$ as $\lambda$ ranges over the eigenvalues
of $H$, and
$\alpha(\gamma,H)\ge-\sqrt K$, with equality if and only if
$\gamma=2\sqrt K$.
\item[\rm(ii)] The measure $\mu_H$ is the unique invariant law of
$(P_t)_{t\ge0}$. For every initial state $z\in\mathbb R^{2d}$,
\begin{equation}
 \limsup_{t\to\infty}
 \lVert \delta_zP_t-\mu_H\rVert_{\mathrm{TV}}^{1/t}
 \le e^{\alpha(\gamma,H)},
\end{equation}
and the limit exists and equals $e^{\alpha(\gamma,H)}$ for a
suitable $z$. Moreover, there are initial states
$y,\widetilde y\in\mathbb R^{2d}$ such that
\begin{equation}
 \lim_{t\to\infty}
 \norm{\delta_yP_t-\delta_{\widetilde y}P_t}_{\mathrm{TV}}^{1/t}
 =e^{\alpha(\gamma,H)}
 \ \ge\ e^{-\sqrt K}.
\end{equation}
\item[\rm(iii)] There are an initial state $z\in\mathbb R^{2d}$ and a
constant $c>0$ such that, for every $\varepsilon\in(0,c/4]$,
\begin{equation*}
 t_{\mathrm{mix}}\bigl(z,\varepsilon;(P_t)_{t\ge0},\mu_H\bigr)
 \ \ge\ \frac{1}{\sqrt K}\,\log\frac{c}{4\varepsilon},
\end{equation*}
where the mixing time is defined as in
Section~(sec:notation of the paper), with $t\in[0,\infty)$ in place of $n$.
\end{enumerate}","status":"unverified"}

