{"assumptions":[],"created_at":"2026-10-26T19:48:27.288883+00:00","domain":"probability theory","id":"claim_1069024104248e6f122ab04f572c7ac99f0c53d5e5534ef1a3a75448bb17948e","kind":"lemma","schema_version":1,"statement":"[Lem 12 of arXiv:2604.25725, 'What is The Probability That A Random Graph With A Given Degree Sequence is Connected?'] Fix $0<\eps<10^{-6}$. Let $\cD$ be such that $m$ is large enough and $n_1,n_2 \le 10^{-6}m$. Let $H$ be a possible subgraph of $G(\cD)$ and let $h$ be a half-edge out of $v\in V(H)$ and not matched in $E(H)$. Suppose $H$ is such that the following hold:
\begin{enumerate}
    \item $\sum_{w\in V(H)}d(w)\le \epsilon m$, and
    \item Either $D^*\leq\eps m$, or $d(w)<\sqrt{m}(\log{m})^{-2}$ for all $w \in V(H)$.
\end{enumerate}
Let $\cF$ denote the event that $h$ is matched onto $V(H)$ or onto a vertex of degree at most $2$. Let $\cA$ denote the event that no neighbour of $v$ outside of $V(H)$ has degree $10d(v)$ or more. Then $\Cprob{\cF\cap\cA}{H\subseteq G(\cD)}<0.001$. If $D^*\leq\eps m$, then $\Cprob{\cF}{H\subseteq G(\cD)}<0.001$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:01:54.285979+00:00","domain":"probability theory","id":"claim_1069389c0e4190138ffe6dfabd4da645f689d30b0daa978c53798a278f5a53c3","kind":"definition","schema_version":1,"statement":"[Defn mild solution of arXiv:2411.01847, 'Well-Posedness of Stochastic Chemotaxis System'] We say that $(u,v)$ is a mild solution of system ((main of the paper)) if $(u,v)$ is a progressively measurable stochastic process with values in $C(\bar{\mathcal{O}})\times W^{1,\infty}({\mathcal{O}})$ that satisfies:
	\begin{align*}
		&u(t) = e^{-tA}u_0 - \int_0^t e^{-(t-s)A}\left( \nabla \cdot \left( \chi u(s) \nabla v(s) \right) - g(u(s)) \right)\, ds + \sum_{i=1}^\infty\int_0^t e^{-(t-s)A} \sigma_i(u(s)) \,  \, dW_s^i, \\
        &v(t)=G*u(t),
	\end{align*}
for all $t\geq 0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:57:59.858011+00:00","domain":"probability theory","id":"claim_10a5d81861634706283d77e8de44525859b7891f4338d6100b8396a736cfc6ee","kind":"theorem","schema_version":1,"statement":"[Theorem lem:gen_ibp of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] For all $l \in H_0^1~\cap~H^2$ and $F \in C_b^1(L)$ the following two equations hold
    \begin{align}
        \langle \!\langle F(\beta), \bar{l}_a\delta_0(\beta_a)\rangle \!\rangle &= \int_{L} F \langle l,\ufd{\sigma^{(a)}}\rangle \,d\var{\sigma^{(a)}},\\
        \Big\langle \mspace{-7mu} \Big\langle F(\beta), \int_{[0,1]} \bar{l}_x\delta_0(\beta_x) dx \Big\rangle \mspace{-7mu} \Big\rangle &= \int_{L} F \langle l,n_{\nu}\rangle \,d\| \nu \|.
    \end{align}
	Here, the LHSs are interpreted as discussed in Theorem (thm:ibpf of the paper). Moreover, for all elements $l\in H_0^1~\cap~H^2$ and $G \in (C_b^1)_{H_0^1\cap H^2}$, the two equations
    \begin{align}
        \int_{L} D^*G \rho^a \, d\mu^{\beta} &= \int_{L} \langle G,\ufd{\sigma^{(a)}}\rangle \,d\var{\sigma^{(a)}},\\
        \int_{L} D^*G \rho \, d\mu^{\beta} &= \int_{L} \langle G,n_{\nu}\rangle \,d\| \nu \|
    \end{align}
    hold. Using these results, [RZZ12], Theorem 3.1(iii), directly implies that $\rho^a,\, \rho \in \mathrm{BV}(L, H_0^1)$, $V(\rho^a)=\var{\sigma^{(a)}}(L)$ and $V(\rho)=\| \nu \|(L)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:09.040120+00:00","domain":"probability theory","id":"claim_10a823ade8a28c59db2d133402cde3b91f98a0bb6a93b69242077133547a40d9","kind":"theorem","schema_version":1,"statement":"[Proposition 5 of arXiv:2606.26619, 'Ergodicity of stochastic reaction-diffusion equations on unbounded domains driven by space'] Assume that there exists a constant $\beta\in\mathbb{R}$ such that $\sigma(\beta) = 0$. 
\begin{itemize}
  \item [(i)] Suppose that (H4) holds. If $\alpha > 0$, then for any $\lambda>0$ satisfying $\frac{\lambda^2}{2}<\alpha$, there exists a unique invariant measure in $L^1_{\lambda}$. Moreover, the solution is exponentially mixing with respect to the Wasserstein metric $W_1$.
  \item [(ii)] Suppose that (H2) and (H4) hold. If $\alpha > \frac{L_{\sigma}^4}{8}$, then for any $\lambda>0$ satisfying $\frac{\lambda^2}{8}<\alpha - \frac{L_{\sigma}^4}{8}$ and $\frac{\lambda^2}{4}<\alpha$, there exists a unique invariant measure in $L^2_{\lambda}$. Moreover, the solution is exponentially mixing with respect to the Wasserstein metric  $W_2$.
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:11:09.317890+00:00","domain":"probability theory","id":"claim_10aa66fa8189a8d58ac9e8103ec53cf72e12d7973c4d7bf28229a91e68b54301","kind":"concept","schema_version":1,"statement":"[Theorem thm:mixture-of-vrjps of arXiv:2411.06195, 'Restrictions of some reinforced processes to subgraphs'] \mbox{}\\
  Assume that the graph $G$ is finite without self-loops and partition its vertex set $\Lambda=I\cup J$,
  $I\cap J=\emptyset$, with $|J|\ge 2$. 
  Consider the vrjp $(X,T)$ in exchangeable time scale on $\Lambda$
  starting at $\rho\in J$ with weights $W$. 
  The restrictions $(X^J,T^J)$ and $(X^{J\neq},T^{J\neq})$ to $J$ without or with
  self-loops removed are
  mixtures of vrjps in exchangeable time scale on $J$ with random weights
    \begin{align}

    W^J(\beta_I)=&(W^J_{ij}(\beta_I))_{i,j\in J}:=W_{JJ}+W_{JI}([H_\beta]_{II})^{-1}W_{IJ}
                    \text{ and }\\

    W^{J\neq}(\beta_I):=&\left(W^J_{ij}(\beta_I)1_{\{ i\neq j\}}\right)_{i,j\in J},
  \end{align}
  respectively. They depend on a random
  vector $\beta_I\in{\mathbb R}^I$, where $\beta_{I\cup\{\rho\}}\in{\mathbb R}^{I\cup\{\rho\}}$ is distributed
  according to $\nu_{I\cup\{\rho\}}^{\widehat W}$ with $\widehat W\in{\mathbb R}^{(I\cup\{\rho\})\times(I\cup\{\rho\})}$
  obtained by restricting the parameters $W$ to $I$ and wiring all points
  in $J$ at $\rho$:
  \begin{align}

    \widehat W_{ij}=\widehat W_{ji}=
    \begin{cases}
      W_{ij} &\text{ for }i,j\in I,\\
      \sum_{k\in J}W_{ik} &\text{ for }i\in I, j=\rho,\\
      0 &\text{ for }i=j=\rho.
    \end{cases}
  \end{align}
  In the case of $(X^{J\neq},T^{J\neq})$ this means the
  following for any event $A\subseteq J^{{\mathbb N}_0}\times{\mathbb R}_+^{{\mathbb N}_0}$. 
  \begin{align}
    P_\rho^{W,\Lambda}((X^{J\neq},T^{J\neq})\in A)
    =&\int_{{\mathbb R}^{I\cup\{\rho\}}}
       P_\rho^{W^{J\neq}(\beta_I),J}((X,T)\in A)\,\nu_{I\cup\{\rho\}}^{\widehat W}(d\beta_{I\cup\{\rho\}})\nonumber\\
    =&\int_{{\mathbb R}^\Lambda}
       P_\rho^{W^{J\neq}(\beta_I),J}((X,T)\in A)\,\nu_\Lambda^W(d\beta_\Lambda).

  \end{align}
  The analogous statement holds for $(X^J,T^J)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:58.363554+00:00","domain":"probability theory","id":"claim_10b1006478265b4a8f67232978fa07ecadbac2c613c89d0aabc4110837a5b735","kind":"theorem","schema_version":1,"statement":"[Theorem 3 of arXiv:2506.19273, 'A large deviation view of \emph{stationarized} fully lifted blirp interpolation'] Assume the setup of Theorem \ref{thm:thm3}. Let also
\begin{eqnarray}
 \phi_{k_1}^{(r)} & = &
-s(\m_{k_1-1}-\m_{k_1}) \omega(k_1;p) \nonumber \\
&  & \times
\mE_{G,{\mathcal U}_{r+1}} \langle (\p_{k_1-1}\|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 -(\x^{(p_1)})^T\x^{(i_1)})(\q_{k_1-1}\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 -(\y^{(p_2)})^T\y^{(i_2)})\rangle_{\gamma_{k_1}^{(r)}} \nonumber \\
 \phi_{22}^{(r)} & = &
-s\m_1 (1-p) \nonumber \\
&  & \times
\mE_{G,{\mathcal U}_{r+1}} \langle (\p_{1}\|\x^{(i_1)}\|_2\|\x^{(p_1)}\|_2 -(\x^{(p_1)})^T\x^{(i_1)})(\q_{1}\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2 -(\y^{(p_2)})^T\y^{(i_2)})\rangle_{\gamma_{22}^{(r)}} \nonumber \\
 \phi_{01}^{(r)} & = & (1-\p_0)(1-\q_0)\mE_{G,{\mathcal U}_{r+1}}\langle \|\x^{(i_1)}\|_2^2\|\y^{(i_2)}\|_2^2\rangle_{\gamma_{01}^{(r)}} \nonumber\\
\phi_{02}^{(r)} & = & (s-1)(1-\p_0)\mE_{G,{\mathcal U}_{r+1}}\left\langle \|\x^{(i_1)}\|_2^2 \lp\q_0\|\y^{(i_2)}\|_2\|\y^{(p_2)}\|_2-(\y^{(p_2)})^T\y^{(i_2)}\rp\right\rangle_{\gamma_{02}^{(r)}}, \end{eqnarray}
where
\begin{eqnarray}
\omega(x;p) \triangleq \begin{cases}
                         1, & \mbox{if } x=1 \\
                         p, & \mbox{otherwise}.
                       \end{cases},
\end{eqnarray}
Then
\begin{eqnarray}
\frac{d\psi(t)}{dt}  & = &       \frac{\mbox{sign}(s)\beta^2}{2\sqrt{n}} \lp  \lp\sum_{k_1=1}^{r+1} \phi_{k_1}^{(r)}\rp +\phi_{22}^{(r)}+\phi_{01}^{(r)}+\phi_{02}^{(r)}\rp.
 \end{eqnarray}
It particular, choosing $\p_0=\q_0=1$, one also has
\begin{eqnarray}
\frac{d\psi(t)}{dt}  & = &       \frac{\mbox{sign}(s)\beta^2}{2\sqrt{n}}  \lp \sum_{k_1=1}^{r+1} \phi_{k_1}^{(r)}  +\phi_{22}^{(r)}   \rp.
 \end{eqnarray}","status":"unverified"}

