{"assumptions":[],"created_at":"2026-10-27T12:52:05.661190+00:00","domain":"probability theory","id":"claim_1aa3f2217ac80d144539ae695182a79f51017003bf3801970ba059446346fb0b","kind":"concept","schema_version":1,"statement":"[Thm local of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $D\subset\mathbb C$ be a proper, simply connected domain. Let $(\phi, A, \phi^A, h_A)$ be a coupling of a GFF $\phi$ with zero boundary conditions in $D$ and a random closed set $A\subset \bar D$ connected to $\partial D$ such that, given $A$, $\phi^A$ is a GFF with zero boundary conditions in $D\setminus A$ and $h_A$ is a harmonic function in $D\setminus A$. Suppose that 
    \begin{enumerate}[label=(\roman*)]
        \item Given $A$, 
        \begin{equation}
            \restr{(\field{e^{i\alpha\phi}})}{D\setminus A} =\ \big(e^{i\alpha h_A}\restr{\field{e^{i\alpha\phi^A}}\big)}{D\setminus A}\quad  \text{a.s.}
        \end{equation}
        \item For every connected component $\mathcal O$ of $D\setminus A$ and any $f\in C^\infty_c(D)$, $$(\field{e^{i\alpha\phi}}, f\1_{[\partial\mathcal O]_n}) \longrightarrow 0$$ in probability as $n\to\infty$.
        \item  For any $N\in\mathbb N$, the random variables
        \begin{equation}
            \restr{\big(\field{e^{i\alpha\phi^A}}\big)}{\cup_{i=1}^N\mathcal O_i} \text{ and } \ \big(h_A, \restr{\big(\field{e^{i\alpha\phi}}\big)}{D\setminus\cup_{i=1}^N\mathcal O_i}\big) 
        \end{equation}
        are conditionally independent given $A$.
    \end{enumerate}
    Then, $(\phi,A)$ is a local set coupling. That is, when restricted to $D\backslash A$,
    \begin{equation}
        \phi=\phi^A + h_A + \frac{2\pi}{\alpha} k_{\mathcal O},
    \end{equation}
    where $\phi^A$ is conditionally independent of $h_A+(2k_{\mathcal O}/\alpha)\pi$ given $A$, and $k_{\mathcal O}$ is some integer that may depend on the connected component $\mathcal O$ of $D\setminus A$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:44:17.169836+00:00","domain":"probability theory","id":"claim_1abc1f21401a33b7cf18880fdec017fba0a689c0954fe4ef500f89d59aea1fc1","kind":"lemma","schema_version":1,"statement":"[Lemma 10 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let $f$ and $g$ be nonnegative real functions defined on $\T^d\times\R^d$ with $m_0(f)$, $m_1(f)$, $m_0(g)$ and $m_1(g)$ which are finite almost everywhere.
Let $k>1+\frac{d}{2}$ (\emph{i.e.} $k\geq 3$ since $k$ is an integer), then there exists a constant $C=C(k,d)>0$ such that
\begin{equation*}
\lVert m_{0}(f) -m_{0}(g) \rVert_{L^2_x} \leq C \lVert \langle v \rangle^k (f-g) \rVert_{L^2_{x,v}},
\end{equation*}
and
\begin{equation*}
\lVert m_{1}(f) - m_{1}(g)\rVert_{L^2_x} \leq C \lVert \langle v \rangle^k (f-g) \rVert_{L^2_{x,v}}.
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:38:08.431325+00:00","domain":"probability theory","id":"claim_1adf01b6b3202d79fb265c93edc669551cd71d17723b2941df4480ea7e94dc8e","kind":"concept","schema_version":1,"statement":"[Proposition prop: characterization of Killing field of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] [langer-singer_classification]. A vector field $J$ in $\R^3$ along a curve $\gamma \subset \R^3$ extends to a Killing vector field on $\R^3$ if and 
