{"assumptions":[],"created_at":"2026-10-28T00:04:30.580371+00:00","domain":"probability theory","id":"claim_1cf1934119c36621036eb9d34a591d20ebca30cfb58db55f1915e504e372c30b","kind":"definition","schema_version":1,"statement":"[Definition def:longEdges of arXiv:2411.10333, 'Subcritical annulus crossing in spatial random graphs'] We define for all \(r>0\) and \(c>0\) the \emph{presence of long edges} event as
		\begin{equation}
			\mathcal{L}(r,c):=\big\{\exists\ \boldsymbol{x}\sim \boldsymbol{y}\colon |x|<r, |x-y|>cr \big\}.
		\end{equation} 
		That is, we can find an edge of length at least \(cr\) in \(\mathscr{G}\) with one endpoint being located in \(B(r)\). We say that \(\mathscr{G}\) has 
		\begin{equation*}\tag{\(\mathscr{L}\)}
			\text{Property } \mathscr{L}_\lambda \quad \text{ if } \quad \limsup_{r\to\infty}\mathbb{P}_\lambda(\mathcal{L}(r,c))=0 \quad \text{ for all }c>0.  
		\end{equation*}
		If Property \(\mathscr{L}_{\lambda'}\) is \emph{uniformly} fulfilled for all \(\lambda'\leq \lambda\), we say that the graph has Property \(\overline{\mathscr{L}}_\lambda\). More precisely, \(\mathscr{G}\) has 
		\begin{equation*}\tag{\(\overline{\mathscr{L}}\)} 
			\text{Property } \overline{\mathscr{L}}_\lambda \quad \text{ if }\quad \limsup_{r\to\infty}\sup_{\lambda'\leq \lambda}\mathbb{P}_{\lambda'}(\mathcal{L}(r,c))=0 \quad \text{ for all }c>0.
		\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:44:17.161935+00:00","domain":"probability theory","id":"claim_1cfc76b2500b8597601f384073fa218ef4a5b34f8cdaab594a838b99247b1222","kind":"concept","schema_version":1,"statement":"[Theorem 7 of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] }
