{"assumptions":[],"created_at":"2026-10-27T21:01:39.420720+00:00","domain":"probability theory","id":"claim_239224745832883d32c34f586e134048d825b5384b4e6d9713c1a37b069c9643","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] Let $J$ be a set of indices and consider two families of formal variables $\mathbf{x}=(x_{j})_{j\in J}$ and $\mathbf{x^{*}}=(x_{j}^{*})_{j\in J}$.
	    \begin{enumerate}
	        \item A \emph{*-test graph} $T = (G, \gamma, \epsilon )$ in the variables $\mathbf{x}$ is a finite connected multi-digraph $G = (V , E, \mathrm{src}, \mathrm{tar})$ together with edge labels $\epsilon : E \rightarrow \{1,*\}$ and $\gamma : E \rightarrow J$. One can see the maps $\gamma$ and $\epsilon$ as indicating that an edge $e\in E$ is labeled $x_{\gamma(e)}^{\epsilon(e)}$. The maps $\mathrm{src}$, $\mathrm{tar} : E \rightarrow V$ specify the source, $\mathrm{src}(e)$ and target, $\mathrm{tar}(e)$ of each edge $e \in E$. 
            \item A \emph{*-graph monomial} $g=(T,v_{in},v_{out})$ is a *-test graph $T$ together with the data of two vertices  $v_{in}$ and $v_{out}$ in $V$. We refer to the roots $(v_{in}, v_{out}) \in V^{2}$ as the input and the output, respectively, though they need not be distinct. We denote by $\mathcal{G}\langle\mathbf{x},\mathbf{x^*}\rangle$ the set of all such *-graph monomials which can be extended to $\mathbb{C}\mathcal{G}\langle\mathbf{x},\mathbf{x^*}\rangle$ the space of finite linear complex combinations of *-graph monomials in variable $\mathbf{x}$ (graphs are considered up to isomorphisms of graphs preserving labeled and in/outputs).
	    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:12:09.056700+00:00","domain":"probability theory","id":"claim_23de912428df920acfab33c097e15c68e2f4299aa441dd2b7961e8d18fc074c1","kind":"theorem","schema_version":1,"statement":"[Proposition prop:HB-palindromic of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] The following identities hold.
\begin{enumerate}
\item[\rm(i)] \emph{ABOBA.} The force-evaluation points $Y_{m+1}=X_m+\frac h2V_m$, together with $Y_0:=X_0-\frac h2V_0$, satisfy $Y_{m+1}-Y_m=hV_m$ for $m\ge0$ and, for $m\ge1$,
\begin{equation}
 Y_{m+1}=Y_m+\beta(Y_m-Y_{m-1})-s\nabla U(Y_m)+h\varsigma\,\xi_m,
 \qquad s=\frac{h^2}{2}(1+\beta);
\end{equation}
the noise variables $h\varsigma\xi_m$ are independent with covariance $h^2(1-\beta^2)\mathrm{Id}_d$.
\item[\rm(ii)] \emph{AOBOA.} The force-evaluation points $Y_{m+1}=X_m+\frac h2V_m$, together with $Y_0:=X_0-\frac h2V_0$, satisfy $Y_{m+1}-Y_m=hV_m$ for $m\ge0$ and, for $m\ge1$,
\begin{equation}
 Y_{m+1}=Y_m+\beta(Y_m-Y_{m-1})-s\nabla U(Y_m)+h\sigma\bigl(r\xi_m^{(1)}+\xi_m^{(2)}\bigr),
 \qquad s=\sqrt\beta\,h^2;
\end{equation}
the noise variables are independent with covariance $h^2(1-\beta^2)\mathrm{Id}_d$.
\item[\rm(iii)] \emph{BOAOB.} Let $\xi_0^{(2)}\sim\mathcal N(0,\mathrm{Id}_d)$ be independent of the variables driving the chain, or alternatively let $\xi_0^{(2)}$ be the zero vector, and define the auxiliary variable $X_{-1}$ by
\begin{equation}
 V_0=\frac rh(X_0-X_{-1})+\sigma\xi_0^{(2)}-\frac h2\nabla U(X_0).
\end{equation}
Then, for $k\ge0$,
\begin{equation}
 X_{k+1}=X_k+\beta(X_k-X_{k-1})-s\nabla U(X_k)+h\sigma\bigl(r\xi_k^{(2)}+\xi_{k+1}^{(1)}\bigr),
 \qquad s=\sqrt\beta\,h^2;
\end{equation}
the noise variables are independent. If $\xi_0^{(2)}\sim\mathcal N(0,\mathrm{Id}_d)$, every noise variable has covariance $h^2(1-\beta^2)\mathrm{Id}_d$; if $\xi_0^{(2)}=0$, the first has the smaller covariance $h^2(1-\beta)\mathrm{Id}_d$, and each subsequent one has covariance $h^2(1-\beta^2)\mathrm{Id}_d$.
\item[\rm(iv)] \emph{OABAO.} Set $\chi_m=r\xi_{m-1}^{(2)}+\xi_m^{(1)}$ for $m\ge2$. The force-evaluation points $Y_m=X_{m-1}+\frac h2\bigl(rV_{m-1}+\sigma\xi_m^{(1)}\bigr)$ satisfy, for $m\ge2$,
\begin{equation}
 Y_{m+1}=Y_m+\beta(Y_m-Y_{m-1})-s\nabla U(Y_m)+\frac h2\sigma\bigl(\chi_m+\chi_{m+1}\bigr),
 \qquad s=\frac{h^2}{2}(1+\beta).
\end{equation}
The variables $\sigma\chi_m$, $m\ge2$, are independent $\mathcal N(0,(1-\beta^2)\mathrm{Id}_d)$, so the noise is a centered $1$-dependent Gaussian sequence with the covariances (equation eq:zetacov-baoab of the paper); in law it coincides with the BAOAB noise (equation eq:zeta-baoab of the paper).
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:46.778143+00:00","domain":"probability theory","id":"claim_23fcacc1b5273a3c35a9a779070b08ec9adff55a2d70f84e3a00bdfb03e5e125","kind":"lemma","schema_version":1,"statement":"[Lemma 2 of arXiv:2603.25615, 'Fourier dimension of Mandelbrot cascades on planar curves'] Suppose that $1\leq q<p < q_{\max}$. If $1 < p/q \leq 2$, for any $1 \leq j \leq n $ and  $I \in \Q_j$, we have

    \begin{equation}
    \E(Y_{j,n }(q,I)^{p/q}) \leq \frac{b^{-2\tau(\frac{p}{2})+\frac{p\tau(q)}{q}}}{1-b^{-\tau(p)+\frac{p\tau(q)}{q}}}\,.    
    \end{equation}
    If $2^k < p/q \leq 2^{k+1}$ for some $k \geq 1$, for any $1 \leq j \leq n$ and $I \in \Q_j$, then 
    \begin{equation}
    \E(Y_{j,n}(q,I)^{p/q}) \leq \left({1-b^{-\tau(2q)+2\tau(q)}} \right)^{-2^{k+1}}.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:51:00.246292+00:00","domain":"probability theory","id":"claim_2410db0e7de7833007757bc5d44dedc96312d1e0e7532d91185030e39d7d96e6","kind":"concept","schema_version":1,"statement":"[Proposition of arXiv:2604.23981, 'Accelerating sampling via asymptotic relaxation enhancing flows'] Suppose $v$ is relaxation enhancing in $\mathcal{Y}\subset L^2(\pi)$. Suppose that $q_0$ satisfies Assumption (ass:warmstart of the paper) with $q_0-1\in \mathcal{Y}$. Then, for any given $B>0$ and $t>0$, there is $A_0$, whenever $A>A_0$, one has
