{"assumptions":[],"created_at":"2026-10-27T07:14:37.649796+00:00","domain":"probability theory","id":"claim_2853ba656e6067ad5b81170d8ac1649d4502201b839523eed6ec575bad2563f3","kind":"theorem","schema_version":1,"statement":"[Theorem 6 of arXiv:2608.19560, '\textbf{Computing transient probabilities in Markovian queues with balking conditional on '] For a fixed $J \in \{1,2,\ldots\}$, $\widetilde{\bm{p}}^{(J)}(t)$ is given by

\begin{align}
\widetilde{\bm{p}}^{(J)}(0)
&=
\underbrace{
\left[
\begin{array}{cccc}
\bm{p}(0) & \bm{0} & \cdots & \bm{0}
\end{array}
\right]}_{\ds J+1},  

\\
\widetilde{\bm{p}}^{(J)}(t)
&=
\widetilde{\bm{p}}^{(J)}(T_{n-1})
\exp(\widetilde{\bm{Q}}_n^{(J)}(t-T_{n-1})),
\quad
T_{n-1} < t \leq T_n,\ n=1,2,\ldots,N,

\end{align}

where $\widetilde{\bm{Q}}_n^{(J)}$ is defined as

\begin{align}
\widetilde{\bm{Q}}_n^{(J)}
&=
\underbrace{
\left[
\begin{array}{ccccc}
\bm{Q}_n & \lambda_n\bm{B} & \bm{O} & \cdots & \bm{O}\\
\bm{O} & \bm{Q}_n & \lambda_n\bm{B} & \cdots & \bm{O}\\
\bm{O} & \bm{O} & \bm{Q}_n & \cdots & \bm{O}\\
\vdots & \vdots & \vdots & \ddots & \vdots\\
\bm{O} & \bm{O} & \bm{O} & \cdots & \bm{Q}_n
\end{array}
\right]
}_{\ds (J+1)\times(J+1)}.

\end{align}","status":"unverified"}

