{"assumptions":[],"created_at":"2026-10-27T13:12:09.044550+00:00","domain":"probability theory","id":"claim_2b1bbf5f81a1fa494db9fe0cd191449f94339073cc81dacaa0413dddd152ff0f","kind":"theorem","schema_version":1,"statement":"[Theorem thm:GTD of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Let $\kappa>1$, let $(s,\beta)\in(0,\infty)\times(0,1)$ satisfy the numerical stability condition (equation eq:HBstability of the paper), and fix an integer $m\ge3$. With the notation introduced above:
\begin{enumerate}
\item[\rm(i)] There exists a $C^1$ function $f:\mathbb R^2\to\mathbb R$ that is $1$-strongly convex and has $\kappa$-Lipschitz gradient such that
\begin{equation*}
 x_{t+1}^\circ=(1+\beta)x_t^\circ-\beta x_{t-1}^\circ-s\nabla f(x_t^\circ)
 \qquad\text{for every }t
\end{equation*}
if and only if $P_m(s,\beta;\kappa)\le0$. When this condition holds, the potential function $\psi$ defined in (equation eq:GTDpsi of the paper) is one such function and is piecewise quadratic.
\item[\rm(ii)] Suppose $P_m(s,\beta;\kappa)<0$, and let $\psi$ be the potential function in (equation eq:GTDpsi of the paper). Then there is a radius $r_{\max}=r_{\max}(m,s,\beta,\kappa)>0$, given explicitly in the proof, such that $\psi$ is quadratic with Hessian $\mathrm{Id}_2$ on each ball $B(x_t^\circ,r_{\max})$, that is,
\begin{equation}
 \nabla\psi(x_t^\circ+u)=\nabla\psi(x_t^\circ)+u,
 \qquad\lvert u\rvert\le r_{\max}.
\end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:48:25.144631+00:00","domain":"probability theory","id":"claim_2b47159f8177ed3fd6acb74d2d5e86cbc9b189157546abd4314ebb7033bbb74b","kind":"concept","schema_version":1,"statement":"[Thm navier-stokes of arXiv:2607.05097, 'Asymptotics of Lyapunov Exponents and Phase Transitions for Fluids with Degenerate Forcing'] Let $N \in \mathbb{N}$ and consider the following SDE:
    \begin{equation}
        dw_k = \Big[-\nu|k|^2w_k - \frac{1}{4\pi} \sum_{j+l=k}\ip{j^\perp,l}(|l|^{-2}-|j|^{-2})w_lw_j\Big]dt + 1_{|k| = 5}dW^k_t \,,
    \end{equation}
    where $w(t) \in H$, with $H$ being the real vector space defined by
    $$H \coloneqq \{w : \mathbb{Z}^2_{\star,N}\to\mathbb{C} \mid w_k = \overline w_{-k} \} \,,$$

    and $W^k_t$ are $\mathbb{C}$-valued Brownian motions which are independent except for the reality condition
   $W^k = \overline{W^{-k}}$. Let $H_I \coloneqq \{w \in H \mid  w_k = 0 \text{ for all } k \notin I\}$, where $I \coloneqq \{k \in \mathbb{Z}^2 \mid |k| = 5\}$. Then for all $N$ large enough there are $0 < \nu_* \le \nu^* < \infty$
    (possibly depending on $N$) such that:
    \begin{itemize}
        \item When $\nu < \nu_*$, (equation eq:stoch-navier-stokes of the paper) has multiple invariant measures, at least one of which gives $H_I$ measure $0$. Furthermore, for all $\delta > 0$ there is some $\eta > 0$ such that for all $w(0) \notin H_I$,
        \begin{equation}
            \limsup_{t \to \infty} \frac{1}{t}|\{s \leq t \mid d(w(s), H_I) < \eta \}| < \delta \quad a.s.\,,
        \end{equation}
        where $|\cdot|$ denotes Lebesgue measure on $[0,t]$ and $d(w,H_I) \coloneqq \inf_{z \in H_I} \|w - z\|$ is the distance from $w$ to $H_I$.
        \item When $\nu > \nu^*$, (equation eq:stoch-navier-stokes of the paper) has a unique invariant measure, and it is supported on $H_I$. Furthermore, almost surely
        $$\limsup_{t \to \infty} \frac{1}{t}\ln d(w(t),H_I) < 0 \,.$$
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:51:12.738734+00:00","domain":"probability theory","id":"claim_2b5e928065a1c0bc3cd5a38e9cc8a7b3e6695f79cbca3c036453f9931c73aad7","kind":"concept","schema_version":1,"statement":"[Lem 1 of arXiv:2605.02420, '\textbf{Large time behavior of critical marked Hawkes processes with heavy tailed marks an'] Under Assumption \ref{ass:nu_beta}, the function   $H$ given by \eqref{e:Hdef} 
is nondecreasing and for any $x\in[0,1]$ we have
\begin{equation}

 H(x)= Kx^{1+\beta}W(x),
\end{equation}
where $K=\frac{c_\nu}{\beta}\Gamma(1-\beta)$ and $W$ is a nonnegative bounded function satisfying
\begin{equation}
 \lim_{x\to 0+}W(x)=1.

\end{equation}
Moreover, there exists a constant $C>0$ such that for any $0\le x\le y$
\begin{equation}

 0\le H(y)-H(x)\le C(y-x)y^\beta.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.286861+00:00","domain":"probability theory","id":"claim_2b7a2ca88c3af46489d18456ae808b15eefe3fa465bbbaf6de495531beca8f29","kind":"lemma","schema_version":1,"statement":"[Lemma optnprefix of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $n\geq 2$ and let $(u_i)_{1\leq i\leq n}$ and $(q_i)_{1\leq i\leq n}$ be strictly increasing sequences of numbers in $(0,1)$. Let $\zeta\in \mathrm{Prefix}_{n+1}((u_i)_{1\leq i\leq n},(q_i)_{1\leq i\leq n})$ where $\mathrm{Prefix}_{n+1}$ is as in Definition (def:nprefix of the paper). Suppose that $\zeta$ satisfies the assumptions of Proposition (prop:annealed cond of the paper). Let $(X_t)_{t\in [0,1]}$ be the Auffinger--Chen process
		\begin{equation*}
			\begin{cases}
				\mathrm{d} X_t=\xi''(t)\zeta([0,t])\partial_x \Phi_\zeta(t,X_t)\mathrm{d} t+\sqrt{\xi''(t)} \mathrm{d} B_t\\
				X_0=0.
			\end{cases}
		\end{equation*}
		For every $s\in [0,1]$, set
		\begin{equation*}
			H_\zeta(s):=\frac{1}{2}\int_s^1 \xi''(r)\Bigl(\mathbb{E}[(\partial_x\Phi_\zeta(r,X_r))^2]-r\Bigr)\mathrm{d} r.
		\end{equation*}
		Then, the following hold:
		\begin{enumerate}
			\item For every $k\in [n-1]$,
			\begin{equation}
				-\mathbb{E}[\Phi_\zeta(q_k,X_{q_k})]+\frac{1}{2}\int_0^1 t\xi''(t)\zeta([0,t])\mathrm{d} t +\frac{1}{2}\int_0^{q_k}t\xi''(t) \zeta([0,t])\mathrm{d} t=-\mathcal{P}\mathrm{arisi}(\zeta),
			\end{equation}
			\item   \begin{equation}
				-\mathbb{E}[\Phi_\zeta(q_n,X_{q_n})]+\frac{1}{2}\int_0^1 t\xi''(t)\zeta([0,t])\mathrm{d} t +\frac{1}{2}\int_0^{q_n}t\xi''(t) \zeta([0,t])\mathrm{d} t=-f,
			\end{equation}
			\item For every $k\in [n]$,
			\begin{equation}
				\mathbb{E}[(\partial_x\Phi_\zeta(q_k,X_{q_k}))^2]=q_k,
			\end{equation}
			\item  \begin{equation}
				\mathrm{supp}(\zeta)\cap [q_n,1]\subset \underset{[q_n,1]}{\mathrm{arg\,min}}(H_\zeta).
			\end{equation}
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:41:19.335182+00:00","domain":"probability theory","id":"claim_2b849658cb704b18489db0ae676caad4452cce056f6044e5438ebfc29ac27909","kind":"lemma","schema_version":1,"statement":"[Lemma lem:good_convergence of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] Jointly with~(equation eq cv subsequence of the paper),~(equation eq cv Hausdorff balls of the paper) and~(equation eq cv subsequence boundary of the paper), for all $t \in \BQ_{\ge 0}$, $x \in \BD_\BQ$, $\alpha \in \SCS'$, along a subsequence again denoted by $(\kappa_n)_{n \ge 0}$, we have
	\begin{equation*}
		\left(
		\SCB^{\kappa_n, \partial}_{\ka_{\kappa_n} s}(\SCB_{\ka_{\kappa_n}t}^{\kappa_n} (\SCL^{\kappa_n}(x))), \SCB^{\kappa_n, \partial}_{\ka_{\kappa_n} s}(\SCB_{\ka_{\kappa_n}t}^{\kappa_n} (\alpha))
		\right)_{s \in \BQ_{\ge 0}}
		\mathop{\longrightarrow}\limits_{n\to \infty}^{(\mathrm{d})}
		\left( 
		\SCB^\partial_{ s}(\SCB_{t} (\SCL(x))), \SCB_{ s}^\partial(\SCB_{t} (\alpha))
		\right)_{s \in \BQ_{\ge 0}},
	\end{equation*}
	for the product topology where each component is equipped with the Hausdorff topology and $(\SCB^\partial_{ s}(\SCB_{t} (\alpha)))_{s\ge 0}$ (resp.~$(\SCB_{ s}^\partial(\SCB_{t} (\SCL(x))))_{s\ge 0}$) has the same law as a collection of independent uniform explorations of the $\CLE_4$, started from the whole boundary of each connected component of $\BD \setminus \SCB_{t}(\alpha)$ (resp.~$\BD \setminus\SCB_{t}(\SCL(x))$). Moreover, jointly with~(equation eq cv subsequence of the paper),~(equation eq cv Hausdorff balls of the paper),~(equation eq cv subsequence boundary of the paper), and the above convergence, for all $t \in \BQ_{\ge 0}$, $x,y \in \BD_\BQ$, $\alpha \in \SCS'$,
	\begin{equation}

		\left(K^{\kappa_n, \partial}_{\SCB_{\ka_{\kappa_n} t}^{\kappa_n} (\alpha), \SCL^{\kappa_n}(y)}, K^{\kappa_n, \partial}_{\SCB_{\ka_{\kappa_n} t}^{\kappa_n} (\SCL^{\kappa_n}(x)), \SCL^{\kappa_n}(y)} \right)
		\mathop{\longrightarrow}\limits_{n\to \infty}^{(\mathrm{d})}
		\left( K^\partial_{\SCB_t(\alpha), \SCL(y)}, K^\partial_{\SCB_t(\SCL(x)), \SCL(y)}
		\right),
	\end{equation}
	for the Hausdorff topology, where $K^\partial_{\SCB_t(\alpha), \SCL(y)}, K^\partial_{\SCB_t(\SCL(x)), \SCL(y)}$ are random compact subsets of $\overline{ \BD}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-09-07T12:18:08.279088+00:00","domain":"probability theory","id":"claim_2b8ca9da5796df078534339d8c0121dac0032ee4773170358c77cbbb674505de","kind":"lemma","schema_version":1,"statement":"[Lemma 7 of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] Let $\xi$ be a random variable such that for $r\ge r_{0}$
	\begin{align}
		\Vert \xi\Vert_{L_r}\le \sum_{k=1}^{m}C_{k}r^{\beta_{k}}+C_{m+1},\nonumber
	\end{align}
	where $C_{1},\cdots, C_{m+1}> 0$ and $\beta_{1},\cdots, \beta_{m}>0$. Then for $t>0$,
	\begin{align}
		\mathbb{P}\big\{ \vert \xi\vert>e(mt+C_{m+1}) \big\}\le e^{r_{0}}\exp\Big(-\min\big\{\big(\frac{t}{C_{1}}\big)^{1/\beta_{1}},\cdots, \big(\frac{t}{C_{m}}\big)^{1/\beta_{m}}\big\}\Big).\nonumber
	\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:27:14.875412+00:00","domain":"probability theory","id":"claim_2ba6c71d75e35d66f94333b79d1fb09e362f62e55e6cf2a6babca6e622d6bf02","kind":"lemma","schema_version":1,"statement":"[Lemma 15 of arXiv:2608.23462, '2608.23462'] Suppose that Assumption~\ref{assu:frozenLipschitz} holds, that $g$ and $\sigma_k$, $k=1,\dots,d_2$, are continuously differentiable in $x \in \R^{d_1}$ as well as in $y\in \R^{d_2}$, and that the mixed second-order derivatives $D^2_{y,x} g$ and $D^2_{y,x} \sigma_k$ exist. Assume moreover that $D_x g$, $D_x \sigma_k$, $D_y g$, $D_y \sigma_k$, $D^2_{y,x} g$, and $D^2_{y,x} \sigma_k$ are jointly continuous and uniformly bounded on $\R^{d_1+d_2}$.
    Then the mapping $(x,y) \mapsto \hat{Y}^{x,y}$ is differentiable in $x$ in the sense that there is a family of processes $D_x \hat Y^{x,y} v$ indexed with $x,v\in \R^{d_1}$, $y\in \R^{d_2}$ satisfying
    \begin{align} 
        \lim\limits_{h \to 0} &\hat{\E} \bigg[ \sup_{t \in [0,T]} \bigg| \frac{\hat{Y}^{x + hv,y}_t - \hat{Y}^{x,y}_t }{h} -D_x \hat{Y}^{x,y}_t v\bigg|^2 \bigg] = 0
    \end{align}
    for any finite $T >0$ where the first-order derivative flow $D_x \hat{Y}^{x,y} v$ is an instance of the general dynamics
    \begin{align} 
        \begin{cases}
        d \zeta^{x,y,z,v}_t = D_x g(x,\hat{Y}^{x,y}_t) v dt + D_y g(x,\hat{Y}^{x,y}_t) \zeta^{x,y,z,v}_t dt \\ \qquad \qquad \qquad + \sum_{k=1}^{d_2} \Big( D_x \sigma_k(x,\hat{Y}^{x,y}_t) v + D_y \sigma_k(x,\hat{Y}^{x,y}_t) \zeta^{x,y,z,v}_t \Big) d \hat{W}^k_t, \\
        \zeta^{x,y,z,v}_0 = z \in \R^{d_2}
        \end{cases}
    \end{align}
    for $z=0$, i.e. $D_x \hat{Y}^{x,y} v = \zeta^{x,y,0,v}$. Moreover for each $p \geq 2$ and finite time horizon $T > 0$, the process is uniformly bounded in $x,y$, i.e. there exists $C_{p,T}> 0$ with
    \begin{align*}
        \hat\E \Big[ \sup_{0\leq t \leq T}|\zeta^{x,y,z,v}_t|^p \Big] &\leq C_{p,T}( |v|^p + |z|^p )
    \end{align*}
    for $x,v \in \R^{d_1}$, $y,z \in \R^{d_2}$ and continuous in $x,y$ with respect to convergence in $L^p$, i.e.
    \begin{align*}
        \lim\limits_{(x',y') \to (x,y)} &\hat{\E} \Big[ \sup_{t \in [0,T]} | \zeta^{x',y',z,v}_t - \zeta^{x,y,z,v}_t|^p \Big] = 0.
    \end{align*}
    for $x,v \in \R^{d_1}$, $y,z \in \R^{d_2}$. Additionally, if $\hat Y^{x}$ is $p$-dissipative for $p \geq 2$ with constant $\beta > 0$, then there exists $ C_{\beta,p}^{(1)},C_{\beta,p}^{(2)} > 0$ with
    \begin{align*}
        \|\zeta^{x,y,z,v}_t\|_{L^p} \leq \{ e^{-(p\beta /2)t}|z|^p + C_{\beta,p}^{(1)}|v|^p \}^{1/p} \leq e^{-(\beta  /2)t} |z| + C_{\beta,p}^{(2)}|v|
