\end{equation}
where \(\Theta_\varepsilon=r_\varepsilon^{3-\delta}+\varepsilon^{2k-2}r_\varepsilon^{4-\delta-2k}\). Moreover,
\begin{equation}
  \Theta_\varepsilon\to0
  \qquad\text{and}\qquad
