{"assumptions":[],"created_at":"2026-10-27T11:36:12.180777+00:00","domain":"probability theory","id":"claim_460117774a36ecd9669498b55f33a01e78acaf7f4d1e1fb12a17f7339db02cff","kind":"theorem","schema_version":1,"statement":"[Proposition 113 of arXiv:2609.03875, 'Measure theory without infinities'] Let $\mf A$ be an HTM, $I$ and $J$ be sets, and $K = I\times  J$. Let one of the following conditions be satisfied:
  \begin{enumerate}
  \item [(a)] $I$ is finite and $\sm{\mf A}{j\in J}{f(i,j)}$ for every $i\in I$,
  \item [(b)] $J$ is finite and $\sm{\mf A}{i\in  I}{f(i,j)}$ for every $j\in J$.
  \end{enumerate}
  Then
  \begin{equation}

      \sum_{i\in I}\sum_{j\in J}f(i,j) = \sum_{k\in K} f(k) = \sum_{j\in J}\sum_{i\in I}f(i,j).
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:48:27.276812+00:00","domain":"probability theory","id":"claim_46067dcaf5d59dd88053adc976ae6fc59d088268fe398276c28ad0bd48e88c94","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2604.24664, 'Absolute continuity of Rosenblatt measures'] Let $(B_t)_{t \in [0, T]}$ be an $\FctT$-Wiener process. Let $\phi: [0, T] \times \Omega \to \Rbb$ be an $\FctT$-progressively measurable process such that $\phi \in L^2([0, T])$ almost surely and assume that the process $(Z_t)_{t\in [0,T]}$ defined by
	\begin{equation}

		Z_t = \exp\left( - \int_0^t \phi_s \d{B_s} - \frac12 \int_0^t \phi^2_s \d{s} \right), \quad t \in [0, T],
	\end{equation}
	is an $\FctT$-martingale. Let $\tilde{\Pbb}$ be the probability measure on $(\Omega, \Fcal)$ defined by $\d{\tilde{\Pbb}} = Z_T \d{\Pbb}$. Then the process $(\tilde{B}_t)_{t \in [0, T]}$ defined by
	\[
		\tilde{B}_t = B_t + \int_0^t \phi_s \d{s}, \quad t \in [0, T],
	\]
	is an $\FctT$-Wiener process with respect to $\tilde{\Pbb}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:07:35.030782+00:00","domain":"probability theory","id":"claim_4612e5eb142deaafcd77d2a370bee24e11688801514ffea76f5097b4f87829c6","kind":"concept","schema_version":1,"statement":"[Cor 32 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let $H$ be a Tonelli Hamiltonian on $\T^n$ and let $\phi$ be a viscosity solution of \eqref{eq:HJs}.
	Then the following statements are true:
	\begin{enumerate}
		\item If $\gamma: \mathbb{S}^1 \to \T^n$ is a periodic $(\phi,H)$-calibrated curve and $\gamma(t_0) \in \operatorname{Alex}(\phi)$ for some $t_0 \in \mathbb{S}^1$, then $\gamma(t) \in \operatorname{Alex}(\phi)$ for all $t \in \mathbb{S}^1$, and $Q(t)=D^2\phi(\gamma(t))$, $t \in \mathbb{S}^1$ is of class $C^1$ and satisfies the matrix Riccati equation \eqref{eq:Ricc}.
		\item  Suppose  $\cut(\phi)$ is closed. If $\gamma: (-\infty,0] \to \T^n$ is a $(\phi,H)$-calibrated curve and $\gamma(t_0) \in \operatorname{Alex}(\phi)$ for some $t_0\in(-\infty,0)$, then $\gamma(t) \in \operatorname{Alex}(\phi)$ for all $t \in (-\infty,0)$, and $Q(t)=D^2\phi(\gamma(t))$, $t \in (-\infty,0)$ is of class $C^1$ and satisfies the matrix Riccati equation \eqref{eq:Ricc}.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:41:19.331584+00:00","domain":"probability theory","id":"claim_4624a49b4e9c31de8fd9f978485bf4a729871bc69e5d192b6df61aa3dbcdfd13","kind":"concept","schema_version":1,"statement":"[Theorem thm:Ikeda-Watanabe of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $X=(X_t)_{t\geqslant 0}$ be a Feller process defined on a locally compact separable metric space $(M,d)$. Assume that there exists a positive kernel $\Pi(x,E)$, $x\in M$, $E\in\mathcal{B}(M)$ such that 
	\begin{enumerate}[leftmargin=*]
		\item  $\Pi(x,E)<\infty$ if $d(x,E)>0$, 
		\item  for any bounded $f\in C(M)$ and a bounded open set $D$ with $d(D,\operatorname{supp}(f))>0$, 
		\begin{align*}
			\frac{P_t f(x)}{t} \mbox{ is uniformly bounded in $x\in D$, $t>0$},
		\end{align*}
		and 
		$\lim_{t\downarrow 0}\frac{P_t f(x)}{t}=\int_M f(y)\Pi(x,dy)$ for every $x\in D$,
	\end{enumerate}
	then for any open set $\Omega\subset M$, $E\in\mathcal{B}(M)$ satisfying $d(E,\Omega)>0$, and $\lambda>0$,
	\begin{align}
		\mathbb{E}_x\left[e^{-\lambda \tau_\Omega}, X_{\tau_\Omega}\in E\right]=\int_\Omega G^\lambda_\Omega(x, dy)\Pi(y,E),
	\end{align}
	where $G^\lambda_\Omega(x,E)=\int_0^\infty e^{-\lambda s} p_\Omega(s,x,E)ds$. Therefore, the joint distribution of $(\tau_\Omega, X_{\tau_\Omega})$ on the event $\{X_{\tau_\Omega}\neq X_{\tau_\Omega -}\}$ is given by 
	\begin{align*}
		\mathbb{P}_x\left(\tau_\Omega\in ds, X_{\tau_\Omega}\in dz\right)=\int_\Omega p_\Omega(s,x,dy)\Pi(y, dz).
	\end{align*} 
	Moreover, (equation eq:Laplace_transform of the paper) holds for $\lambda=0$ if $\mathbb{E}_x[\tau_D]<\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:59:53.381168+00:00","domain":"probability theory","id":"claim_462cb1d6775ce7f4ad852a8c51f62d6d90d9b2a83232fa60b049dd68a9f85337","kind":"lemma","schema_version":1,"statement":"[Lemma lem:quadratic-martingale-proof of arXiv:2608.18320, 'Asymptotics for Beta-Splitting Trees via Homogeneous Fragmentations and Meromorphic Potent'] For every $\beta>-2$,
