{"assumptions":[],"created_at":"2026-10-26T19:32:58.363760+00:00","domain":"probability theory","id":"claim_463a4393ed8b1e6b2306feb6fc0f39eb4d4c0046f0ed8538e6a69a0551da9fb6","kind":"theorem","schema_version":1,"statement":"[Corollary 5 of arXiv:2506.19273, 'A large deviation view of \emph{stationarized} fully lifted blirp interpolation'] Assume the setup of Theorem \ref{thm:thm5} with  sets ${\mathcal X}$ and ${\mathcal Y}$ being such that $\|\x\|_2=\|\y\|_2=1$. Then
 \begin{eqnarray}
\lim_{n\rightarrow\infty}\psi_1(\bar{\p}(t),\bar{\q}(t),\bar{\m}(t),t)
 =
\lim_{n\rightarrow\infty}\psi_1(\bar{\p}(0),\bar{\q}(0),\bar{\m}(0),0)  =  \lim_{n\rightarrow\infty} \psi_1(\bar{\p}(1),\bar{\q}(1),\bar{\m}(1),1),
\end{eqnarray}
 and
\begin{eqnarray}
\psi_1(\bar{\p}(0),\bar{\q}(0),\bar{\m}(0),0) & = & -\frac{\mbox{sign}(s) s \beta^2}{2\sqrt{n}} \sum_{k=1}^{r+1}\Bigg(\Bigg. \bar{\p}_{k-1}(0)\bar{\q}_{k-1}(0)  -\bar{\p}_{k}(0)\bar{\q}_{k}(0)   \Bigg.\Bigg)
\bar{\m}_k(0) \omega(k;p) \nonumber \\
& &  +\psi(\bar{\p}(0),\bar{\q}(0),\bar{\m}(0),0) \nonumber \\
\psi_1(\bar{\p}(1),\bar{\q}(1),\bar{\m}(1),1) & = & -\frac{\mbox{sign}(s) s \beta}{2\sqrt{n}} \sum_{k=1}^{r+1}\Bigg(\Bigg. \bar{\p}_{k-1}(1)\bar{\q}_{k-1}(1)  -\bar{\p}_{k}(1)\bar{\q}_{k}(1)   \Bigg.\Bigg)
\bar{\m}_k(1)  \omega(k;p) \nonumber \\
& &  +\psi(\bar{\p}(1),\bar{\q}(1),\bar{\m}(1),1).
 \end{eqnarray}
 Moreover, let
 \begin{equation}
\psi_S(\p,\q,\m,t)  =  \mE_{G,{\mathcal U}_{r+1}} \frac{1}{p|s|\sqrt{n}\m_r} \log
\lp \mE_{{\mathcal U}_{r}} \lp \dots \lp \mE_{{\mathcal U}_2}\lp\lp
\lp \sum_{i_3=1}^{l} \mE_{{\mathcal U}_1}  Z_{i_3,S}^{\m_1}\rp^p \rp^{\frac{\m_2}{\m_1}}\rp\rp^{\frac{\m_3}{\m_2}} \dots \rp^{\frac{\m_{r}}{\m_{r-1}}}\rp,
\end{equation}
where,  analogously to (\ref{eq:thm3eq1}) and (\ref{eq:thm3eq2}),
\begin{equation}
Z_{i_3,S}  \triangleq  \sum_{i_1=1}^{l}\lp\sum_{i_2=1}^{l}e^{\beta D_{0,S}^{(i_1,i_2,i_3)}} \rp^{s}, \nonumber \\
\end{equation}
with
\begin{eqnarray}
 D_{0,S}^{(i_1,i_2,i_3)}
 & \triangleq &
 \sqrt{t}(\y^{(i_2)})^T
 G\x^{(i_1)}+\sqrt{1-t}\|\x^{(i_2)}\|_2 (\y^{(i_2)})^T\lp\sum_{k=1}^{r+1}b_k\u^{(2,k)}\rp  \nonumber \\
& &
 +\sqrt{1-t}\|\y^{(i_2)}\|_2\lp\sum_{k=1}^{r+1}c_k\h^{(k)}\rp^T\x^{(i)}
 + f_{\bar{\x}^{(i_3)} } (\x^{(i_1)}).
 \end{eqnarray}
Then
\begin{eqnarray}
\lim_{n\rightarrow\infty} \psi_S(\bar{\p}(1),\bar{\q}(1),\bar{\m}(1),1) & = &
 -\lim_{n\rightarrow\infty}\frac{\mbox{sign}(s) s \beta^2}{2\sqrt{n}} \sum_{k=1}^{r+1}\Bigg(\Bigg. \bar{\p}_{k-1}(0)\bar{\q}_{k-1}(0)  -\bar{\p}_{k}(0)\bar{\q}_{k}(0)   \Bigg.\Bigg)
\bar{\m}_k(t) \omega(k;p)
 \nonumber \\
& &  +\lim_{n\rightarrow\infty} \psi_S(\bar{\p}(0),\bar{\q}(0),\bar{\m}(0),0). \nonumber \\
 \end{eqnarray}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:51:15.031215+00:00","domain":"probability theory","id":"claim_46428cb666071aba0a2add32f2fb1937fb7f997b8e565759d69188dc61941356","kind":"concept","schema_version":1,"statement":"[Lemma Randersimmersion of arXiv:2609.03909, 'Conic Pseudo-Finslerian Mechanical Systems'] Let $R$ be a Randers-Minkowski metric on $\mathbb R^n$ with navigation data $(h, W)$. If $V$ is a subspace, then the induced metric on $V$ is the Randers-Minkowski metric with navigation data $(\tilde h, W^{\top})$ given by
\begin{subequations}
\begin{equation*}
\tilde h := \lambda \, h\vert_{V \times V} \, ,
\end{equation*}
\begin{equation*}
W^{\top} := W - W^{\perp} \, ,
\end{equation*}
\end{subequations}
where $\lambda := \frac{1}{1 - h(W^{\perp}, W^{\perp})}$ and $W^{\perp}$ is the component of $W$ $h$-orthogonal to $V$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:06:42.721090+00:00","domain":"probability theory","id":"claim_46742da3e147e1bba4bd94d1539e7327fabf19271b0fd1ec3b217af1a89f057d","kind":"definition","schema_version":1,"statement":"[Defi finite action of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] Let $(\rho,j)\in \mathcal{M}((0,T)\times \mathbb{R}^n;[0,\infty)\times \mathbb{R}^n)$ be a finite Radon measure. We say that $(\rho,j)$ is a \emph{finite action curve} if
    \begin{enumerate}
    \item $(\rho,j)$ solve the continuity equation 
    \begin{align*}
\partial_t\rho+\dive j=0 \text{ in }\mathcal D'((0,T)\times \mathbb{R}^n).
\end{align*}
        \item $j\ll \rho$ and 
        \begin{align*}
            \int_{(0,T)\times \mathbb{R}^n}\left|\frac{dj}{d\rho}\right|^2\, d\rho<\infty;
        \end{align*}
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:27:56.784228+00:00","domain":"probability theory","id":"claim_46b5cccc9b1169b586a4118117cfebaafcd0b05d436bc4838ff88b3db48c7283","kind":"lemma","schema_version":1,"statement":"[Lemma 30 (Consequences of the dominant energy condition) of arXiv:2608.31171, '\bf Finite-energy spacetimes with torus symmetry. \\ \Large Cauchy stability of Einstein--'] Given a Navier--Stokes potential~$\chi$ as in \autoref{def-pot-hyperbolic}, one has the following inequalities between components in the orthonormal coframe $e^m$: for $m,n=0,1,2,3$,
\bel{Tchi-DEC}
|T_\chi^{mn}| \leq T_\chi^{00} , \qquad
-4 T_\chi^{00} \leq \eta_{mn} T_\chi^{mn} \leq 2 T_\chi^{00} .
\ee
The Euler stress-tensor with pressure law satisfying~\eqref{hyperbolic-eos-zero} admits the stronger trace bound
\bel{TrTE-lower}
- T_{\rm E}^{00} \leq \eta_{mn} T_{\rm E}^{mn} \leq 2 T_{\rm E}^{00} .
\ee","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:10:05.675633+00:00","domain":"probability theory","id":"claim_46c17d5be73a42edd37aa1a7cd1ec5e8050b35037f30c9dce82fd03ac7a04f46","kind":"theorem","schema_version":1,"statement":"[Theorem 4 (Sparre Andersen's formula: Probabilistic version) of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] Let $n\geq1$. Let $\xi_1,\dots,\xi_n$ be real-valued,
possibly dependent random variables with partial sums $S_k:= \xi_1+\dots+\xi_k$, $1\leq k\leq n$, and suppose that the following conditions are satisfied:
\begin{itemize}
\item [(i)]  \emph{Symmetric exchangeability:} For every permutation $\sigma$ of the set $\{1,\dots,n\}$ and every choice of signs $\eps_1,\dots,\eps_n\in \{-1,+1\}$, the following equality in distribution holds:
    $$
    (\xi_1,\dots,\xi_n) \stackrel{d}{=}(\eps_1 \xi_{\sigma(1)}, \dots, \eps_n \xi_{\sigma(n)}).
    $$
\item[(ii)] \emph{No partial-sum atoms at $0$:}
For every $1\leq i \leq n$, we have $\pr[S_i = 0] = 0$.
\end{itemize}
Then
    \begin{align*}
        \pr(S_1 > 0, S_2 > 0, \dots, S_n > 0) = \frac{1}{2^{2n}}
        \binom{2n}{n}.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:52:57.735763+00:00","domain":"probability theory","id":"claim_470f10dfe954300fb92ca4525c81f5924efdd107183211e641bdd64682427ea8","kind":"lemma","schema_version":1,"statement":"[Lemma 28 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Let $0 < \gamma < |\fs|$, let $N \geq 0$ be an integer, and let $G$ be a kernel on $\mbR \times \mbR$, smooth away from the origin, satisfying for all multi-indices $|k|_\fs \leq N + 1$
	\begin{equ}
		|D^k G(z)| \lesssim |z|_\fs^{-\gamma - |k|_\fs}\;.
	\end{equ}
	Let $(\varrho_\eps)_{\eps \in (0,1]}$ be a family of functions such that $\|\varrho_\eps\|_{L^1} \lesssim 1$.
	Then the following assertions hold:
	\begin{enumerate}
		\item  If $\|\varrho_\eps\|_{L^\infty} \lesssim \eps^{-|\fs|}$, then for all $z \in \mbR \times \mbR$,
		\begin{equ}
			|G \ast \varrho_\eps(z)| \lesssim \eps^{-\gamma}\;.
		\end{equ}
		\item  If $\varrho_\eps$ is supported in $\{|z|_\fs \leq \eps\}$ and satisfies
		\begin{equ}
			\int_{\mbR \times \mbR} z^k\, \varrho_\eps(z)\, dz = 0 \quad \text{for all } |k|_\fs < N\;,
		\end{equ}
		then for $|z|_\fs > 2\eps$
		\begin{equ}
			|G \ast \varrho_\eps(z)| \lesssim \eps^{N} |z|_\fs^{-\gamma - N}\;. 
		\end{equ}
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:09:49.800116+00:00","domain":"probability theory","id":"claim_471858ffe5521162490831ce7637816a28104b920e204248b2e6022a80a501c4","kind":"concept","schema_version":1,"statement":"[Lemma 6 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] Let $H\subset G\subset F$ be a chain of order dense sublattices and let $B\subset G$ be solid. The following sets are equal:
\item[(i)] The set of all $f\in F$ such that there is $Q\subset B_{+}$ with $Q\uparrow\left|f\right|$;
\item[(i')] The set of all $f\in F$ such that there is $Q\subset B_{+}\cap H$ with $Q\uparrow\left|f\right|$;
\item[(ii)] The order adherence of $B$ in $F$;
\item[(ii')] The order adherence of $B\cap H$ in $F$;
\item[(iii)] Order adherence of $\Sol B$ in $F$;
\item[(iii')] Order adherence of $\Sol\left(B\cap H\right)$ in $F$;
\item[(iv)] Sets similar to (ii)-(iii') with uo adherence replacing order adherence.\medskip

This set is solid and its intersection with $G$ and $H$ is the common order and uo adherence of $B$ in $G$ and of $B\cap H$ in $H$, respectively. The order and uo closures of $B$ and $B\cap H$ also coincide, and are a solid set. Both the adherence and the closure are convex, whenever $B$ is. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.285242+00:00","domain":"probability theory","id":"claim_4737cc1f2bcf901fe3ec3b5ea982c57d298c29a19b123e501655cb3164d7ca1e","kind":"definition","schema_version":1,"statement":"[Definition def:nprefix of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Fix $n\geq 1$ and set $q_0=0$. Given a strictly increasing sequence
		$(q_i)_{1\leq i\leq n}$ in $(0,1)$ and a strictly increasing sequence of
		weights $(u_i)_{1\leq i\leq n}$ in $(0,1)$, we write
		$\mathrm{Prefix}_{n+1}\!\bigl((u_i)_{1\leq i\leq n},(q_i)_{1\leq i\leq n}\bigr)$
		for the collection of probability measures $\zeta$ on $[0,1]$ satisfying
		\begin{equation*}
			\mathrm{supp}(\zeta)\cap[0,q_n]=\{q_0,q_1,\ldots,q_n\}
			\qquad\text{and}\qquad
			\zeta([0,q_{i-1}])=u_i \;\text{ for all }\; i\in\{1,\ldots,n\}.
		\end{equation*}
		We say that such $\zeta$ has an \emph{$(n+1)$-atom prefix} $\{0,q_1,\ldots,q_n\}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:31:49.843479+00:00","domain":"probability theory","id":"claim_4741f3ede027761c8fed8f65d5c3c924abbfd0fcf796c50c4100df7e6ed559ba","kind":"concept","schema_version":1,"statement":"[Theorem thm:main of arXiv:2608.23742, 'Second-order fusion asymptotics for $\Sine_\beta$ correlation functions'] Let $\beta>0$, $m\ge2$, and suppose $m\beta>1$. For pairwise distinct $a_1,\ldots,a_m\in\mathbb R$, as $\varepsilon\to0$,
\begin{align}
\rho^{(m)}_\beta(\varepsilon a_1,\ldots,\varepsilon a_m)
&=C^{(m)}_\beta|\varepsilon|^{\beta\binom m2}\prod_{i<j}|a_i-a_j|^\beta\notag\\
&\quad\times\left[1-\frac{\beta^2}{8(m\beta-1)(2m+1)}V(a)\varepsilon^2+o(\varepsilon^2)\right].
\end{align}
The remainder is locally uniform when $a$ ranges over compact subsets of the set of pairwise distinct configurations. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:06:06.292078+00:00","domain":"probability theory","id":"claim_4749c23221875db32a5a531f311058e44a2c0c9334c71bffe571f7d4275d7840","kind":"concept","schema_version":1,"statement":"[Lemma lem:UV_int of arXiv:2605.21265, 'The non-Hermitian minor process'] Let the test functions $f_1,f_2$ satisfy the assumptions of Theorem~(theo:main of the paper) and let $K$ be defined as in (equation eq:def_K of the paper). For any $x_1,x_2\in (0,1]$ with $x_1<x_2$ it holds that
\begin{equation}
I_1= -8\int_{\mathbf{D}_{x_1}}\mathrm{d}^2 z_1\int_{\mathbf{D}_{x_2}}\mathrm{d}^2 z_2\overline{\partial_{z_1}f_1(z_1)}\partial_{z_2}f_2(z_2)\partial_{z_1}\partial_{\overline{z}_2}\log K +4x_1\!\!\int_{\partial\mathbf{D}_{x_1}\times \partial \mathbf{D}_{x_2}} \frac{\overline{f_1(z_1)}f_2(z_2)}{(x_1-z_1\overline{z}_2)^2}\mathrm{d} z_1\wedge \mathrm{d}\overline{z}_2,
