\begin{equation}
I_2=\frac{8}{x_1x_2}\left(\frac{1}{x_1}\int_{\mathbf{D}_{x_1}}\overline{f_1(z)}\mathrm{d}^2 z-\frac{1}{2}\int_0^{2\pi}\overline{f_1(\sqrt{x_1}\mathrm{e}^{\mathrm{i}\theta})}\mathrm{d}\theta\right)\!\!\left(\frac{1}{x_2}\int_{\mathbf{D}_{x_2}}f_2(z)\mathrm{d}^2 z-\frac{1}{2}\int_0^{2\pi}f_2(\sqrt{x_2}\mathrm{e}^{\mathrm{i}\theta})\mathrm{d}\theta\right)\!.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:41:54.376332+00:00","domain":"probability theory","id":"claim_478b9367b2ed0fa866d85e3dc94cace4158efbd1a44ecde35f58518b44064a24","kind":"lemma","schema_version":1,"statement":"[Lemma lem:e1 of arXiv:2412.01995, 'Exciting games and Monge-Amp\`{e}re equations'] For any $N \in \mathbb N$, we have that
\begin{align}
\lVert g^n \rVert_{C^1(\bar \Omega_N)} \leq K(N) \quad \text{for all $n \geq N+10$},
