{"assumptions":[],"created_at":"2026-10-27T20:04:59.427195+00:00","domain":"probability theory","id":"claim_49aeb2c4af757fc555c70b7871bdbd9eba0b081e3ad81a687ab4b2b0ecb029e9","kind":"concept","schema_version":1,"statement":"[Prop lerw-utc of arXiv:2605.19419, 'Tail exponents of the three-dimensional uniform spanning tree and Abelian sandpile'] {LS19}}]
