{"assumptions":[],"created_at":"2026-10-26T19:44:17.169050+00:00","domain":"probability theory","id":"claim_4e667a1f5e5ec34d67c7b96bd76c05b3c959ce8a8f0555857f479508050d48bf","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let Assumptions~\ref{assump-PDE}~and~\ref{assump-particles} hold, and in particular let $p\in (d,+\infty)$, $\gamma \in (\tfrac{d}{p},1)$ and an integer $k \geq 3$ for which these assumptions hold. Assume further that the cut-off parameter satisfies
${A\geq \| u\|_{L^{\infty}_{t,x}}}$, and if $d=3$, that $\frac{\gamma}{2} + \frac{3}{2}(\frac{1}{2}-\frac{1}{p}) <1$. Then the following holds:
\begin{itemize}
\item If $\sigma>0$, then for any $q\in [1,+\infty)$, there exists $C = C(q,d,\gamma,p,A,\sigma)>0$ such that for any $N\in \N^*$,
\begin{align*}
\Big(\E &\sup_{t\in[0,T]} \big\| u^{N}_t- u_t \big\|_{ \gamma,p}^{2q}\Big)^{\frac{1}{q}}
+  \Big(\E \sup_{t\in[0,T]} \big\| \langle v \rangle^{k}(F_{t}^{N}-F_{t}) \big\|_{L^{2}_{x,v}}^{2q} \Big)^{\frac{1}{q}} \\
& \leq C \bigg( \big(\E \big\| u^{\circ,N}-u^\circ \big\|_{\gamma, p}^{2q}\big)^{\frac{1}{q}} +   \big(\E \big\| \langle v \rangle^{k} (F_{0}^{N}-\vartheta^N\ast F^\circ) \big\|_{L^{2}_{x,v}}^{2q}\big)^{\frac{1}{q}}\\
&\quad + N^{-2(\alpha-\beta)} +N^{-2\beta(\gamma-\frac{d}{p})} + N^{-(\frac{1}{2} - d\beta -(d+1)\alpha)} + \ratetilde^2 \bigg) + 2 \rate^2 ,
\end{align*}
where
\begin{equation}

\rate^2 = \sup_{t\in[0,T]} \big\| u_t^{(N)} - u_t \big\|_{ \gamma,p}^2 +  \sup_{t\in[0,T]} \big\| \langle v \rangle^{k} (F^{(N)}_{t}\ast \vartheta^{N} - F_{t}) \big\|_{L^{2}_{x,v}}^2
\end{equation}
and
\begin{equation}
\ratetilde^2 = \sup_{t\in[0,T]} \big\| \langle v \rangle^{k} (F^{(N)}_{t}\ast \vartheta^{N} - F^{(N)}_{t}) \big\|_{L^{2}_{x,v}}^2
\end{equation}

\item If $\sigma=0$, then for any $q\in [1,+\infty)$ and any $\varepsilon>0$, there exists $C = C(q,d,\gamma,p,A,\varepsilon)>0$ such that for any $N\in \N^*$,
\begin{align*}
\Big(\E &\sup_{t\in[0,T]} \big\| u^{N}_t- u_t \big\|_{ \gamma,p}^{2q}\Big)^{\frac{1}{q}}
+  \Big(\E \sup_{t\in[0,T]} \big\| \langle v \rangle^{k}(F_{t}^{N}-F_{t}) \big\|_{L^{2}_{x,v}}^{2q} \Big)^{\frac{1}{q}} \\
& \leq C \bigg( \big(\E \big\| u^{\circ,N}-u^\circ \big\|_{\gamma, p}^{2q}\big)^{\frac{1}{q}} +   \big(\E \big\| \langle v \rangle^{k} (F_{0}^{N}-\vartheta^N\ast F^\circ) \big\|_{L^{2}_{x,v}}^{2q}\big)^{\frac{1}{q}} +\ratetilde^2 \\
&\quad + N^{-2(\alpha-\beta)} + N^{-2\beta(\gamma-\frac{d}{p})+\varepsilon} + N^{-(\frac{1}{2} - d\beta -(d+1)\alpha)}
\bigg) \, \frac{1}{1-\tilde\gamma} e^{CT\big(1+\sigma_{N}^{-2} + \sigma_{N}^{-\frac{1}{1-\tilde\gamma}}\big)}
 + 2 \rate^2,
\end{align*}
where
\begin{equation}
\tilde{\gamma} = \frac{1}{2} \Big(\gamma + d\big(\frac{1}{2}-\frac{1}{p}\big)\Big) \vee \frac{\gamma+1}{2} \in (0,1) .
\end{equation}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:54:57.593747+00:00","domain":"probability theory","id":"claim_4e9a7aa530cbd80bb3e9b11a4ca3c928d7704c5e742bb1fe356b7899ec14dcf2","kind":"concept","schema_version":1,"statement":"[Lem Lemma_A.2 of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] Let $(x(t),t\geq 0)$ be a TASEP with step initial condition and let $\alpha \in (0,1)$. Then, it holds
	\begin{equation}
	\lim_{T \to \infty} \mathbb{P}( x_{\alpha T}(T) \geq (1-2 \sqrt{\alpha})T - s c_1(\alpha) T^{1/3}) = F_{\textup{GUE}}(s), 
	\end{equation} where $c_1(\alpha) = \tfrac{(1-\sqrt{\alpha})^{2/3}}{\alpha^{1/6}}$.

	In addition, we have the following estimates on the lower and the upper tail:
	uniformly for all large times $T$ and for $\alpha$ in a closed subset of $(0,1)$, there exist constants $C,c > 0$ such that
	\begin{equation}
	\mathbb{P}( x_{\alpha T}(T) \leq (1-2\sqrt{\alpha})T - s c_1(\alpha) T^{1/3}) \leq C e^{-c s} \ \ \textrm{for} \ s > 0 
	\end{equation}
	and
	\begin{equation}
	\mathbb{P}(x_{\alpha T}(T) \geq (1-2 \sqrt{\alpha})T + s c_1(\alpha) T^{1/3}) \leq C e^{-c s^{3/2}} \ \ \textrm{for} \ 0 < s = o(T^{2/3}). 
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:47.662489+00:00","domain":"probability theory","id":"claim_4ea43c391a7a1ee6ee203d1ef297bfcf594d5c63b1841df80f1db7b806d6feba","kind":"lemma","schema_version":1,"statement":"[Lemma 13 of arXiv:2605.09372, 'Sharp weighted norm estimates for martingale square functions'] Let $1<p<\infty$. Given a matrix weight $W\in A_p$, we have
\begin{equation}
		\int_{\Omega}\sup_n \left[ \mathbb E_{n}\left(\big\|W^{\frac{1}{p}} \widehat{W}_{n}\big\|g\right)\right]^{p'}d\mathbb P\lesssim_{p,d}[W]_{A_p}^{p'}\|g\|_{L_{p'}}^{p'},\quad \forall\, 0\leq g\in L_{p'}.
	\end{equation}","status":"unverified"}

{"assumptions":["$F:\mathbb{R}^{+}\to\mathbb{R}^{+}$ convex and nondecreasing","$A=(a_{ij})$ diagonal-free","$\xi_1,\dots,\xi_n$ independent, $(\tilde\xi_i)$ an independent copy of $(\xi_i)$"],"created_at":"2026-10-12T16:00:40+00:00","domain":"probability theory","id":"claim_4ed298efb7395ec4f31e577779851f026061749c9cf1f772e5afc0a879ba1bbb","kind":"concept","schema_version":1,"statement":"[Lemma 11 (Theorem 3.1.1 in \cite{de_la_Pena_Book}) of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] Let $F: \mathbb{R}^{+}\to \mathbb{R}^{+}$ be a convex nondecreasing function and $A=(a_{ij})_{n\times n}$ be a diagonal-free matrix. If $\{\xi_{i}, i\le n\}$ is a sequence of independent random variables and $\tilde{\xi}_{i}$ is an independent copy of $\xi_{i}$, then there exists a universal constant $C$ such that
	\begin{align}
		\mathbb{E}F\Big(\big\vert\sum_{i,j}a_{ij}\xi_{i}\xi_{j}\big\vert   \Big)\le \mathbb{E}F\Big(C\big\vert\sum_{i,j}a_{ij}\xi_{i}\tilde{\xi}_{j}   \big\vert\Big).
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:34:09.924490+00:00","domain":"probability theory","id":"claim_4f10d153d233cc96cfcefbfd4e0266a744c79fc9a7af15ca85c19d467066b428","kind":"theorem","schema_version":1,"statement":"[Prop 7 of arXiv:2603.27433, 'The $k$-cycle shuffling with repeated cards'] Let $r:=n-\l_1$. Suppose that one of the following holds:
\begin{enumerate}
\item $r\in[\log n,n^{5/6}]$, and $2\le k\le o(n/\log n)$. 
\item $r\in[n^{5/6},0.499 n]$, and $6\log n\le k\le o(n/\log n)$. 
\end{enumerate}
Moreover, suppose that $t':=t-\frac{n\log n}{k}$ satisfies $|t'|\le \frac{n(\log\log n-\omega(1))}{2k}$. Then, we have 
$$|s_\l(k)|^{2t}\le \exp\left(-2r\log n+r\log r-\omega(r)\right).$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:34:09.925591+00:00","domain":"probability theory","id":"claim_4f67599d13f49804a8315d8187c35911ffa3f3c31aec411958ac81a06b269072","kind":"concept","schema_version":1,"statement":"[Thm 21 (\Cref{thm: restate of pnkt and nu} in the text) of arXiv:2603.27433, 'The $k$-cycle shuffling with repeated cards'] For $n=\omega(1)$ and $k\ge 2$, the following holds. Let $t':=t-\frac{n\log n}{k}$. Let $P_{n,k}^{*t}$ be defined as in \Cref{defi: Pnk and its convolution}, and $\nu_{n,k}^t$ be defined as in \Cref{defi: construction of nu}. 
\begin{enumerate}
\item Suppose that $2\le k\le o(n/\log n)$, and $t'=cn/k$, where $c\in\R$ is an absolute constant. Then, we have $$d_{TV}(P_{n,k}^{*t},\nu_{n,k}^t)=o(1).$$ 
\item Suppose that $2\le k\le n^{c_0+o(1)}$, where $c_0\in[0,1)$ is an absolute constant, and $|t'|\le \frac{n(\log\log n-\omega(1))}{2k}$.
Then, we have $$d_{TV}(P_{n,k}^{*t},\nu_{n,k}^t)\le n^{c_0-1+o(1)}.$$ 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:41:54.341913+00:00","domain":"probability theory","id":"claim_4f7ba4912304c4c641f22557773fc96ba595bc452ac3bb8f1b1f208c14127a25","kind":"lemma","schema_version":1,"statement":"[Lemma lem:KPS of arXiv:2412.01381, 'Ergodicity and mixing for locally monotone stochastic evolution equations'] Assume that $(P_t)_{t\ge 0}$ has the $e$-property and that there exists $z\in H$ such that for every bounded set $J$ and every $\delta>0$, we have
\begin{equation}
\inf_{x\in J}\liminf_{T\to\infty} Q_T(x,B(z,\delta))>0.
\end{equation}
Suppose further that for every $\varepsilon>0$ and every $x\in H$, there exists a bounded Borel set $K\subset H$ such that
\begin{equation}
\liminf_{T\to\infty} Q_T(x,K)>1-\varepsilon.
\end{equation}
Then there exists a unique invariant probability measure $\mu_\ast$ for $(P_t)_{t\ge 0}$ such that the semigroup $(P_t)_{t\ge 0}$ is weak$^\ast$-mean ergodic and the weak law of large numbers holds.","status":"unverified"}

