{"assumptions":[],"created_at":"2026-10-28T01:41:54.376738+00:00","domain":"probability theory","id":"claim_4fb346e7f10bd3e02451186b8fad87aae3743e8a33c581ac794fdc8bebcdb6ab","kind":"concept","schema_version":1,"statement":"[Proposition prop:secondorder of arXiv:2412.01995, 'Exciting games and Monge-Amp\`{e}re equations'] Fix $x^0 \in \partial \Delta$ with $x^0_1=\dotso=x^0_k=0$,  $x^0_{k+1},\dotso,x^0_d > 0$, and $\sum_{j=k+1}^d x_j^0<1$. Taking $r= (1-\sum_{i=k+1}^d x^0_i)/{(2d)}$,  there exist two positive constants $c_1(x^0)$, $c_2(x^0)$ such that for any $x_1,\dotso, x_k \in (0,r)$,
    \begin{align*}
    c_1(x^0) Diag(1/x^2_1,\dotso,1/x^2_k, 1,\dotso, 1) 
  &\leq \nabla^2 g(x_1,\dotso, x_k, x^0_{k+1},\dotso,x^0_d) \\
  &\leq  c_2(x^0)Diag(1/x^2_1,\dotso,1/x^2_k, 1,\dotso ,1),
  \end{align*}
    where $Diag(1/x^2_1,\dotso,1/x^2_k, 1,\dotso, 1)$ denotes a diagonal matrix with the $(i,i)$-th entry being $1/x^2_i$ for $1\leq i \leq k$ and $1$ for $k+1 \leq i \leq d$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:07:17.292275+00:00","domain":"probability theory","id":"claim_500589a78fe32244fea1d9298905fb899018376f032cd2901107ed0615260b4e","kind":"theorem","schema_version":1,"statement":"[Theorem thm:rlpts of arXiv:2603.22652, 'A cohesive account on the ergodic behaviours and scaling limits of Random Walks in Cooling'] Assume $\mu = \alpha^{{\mathbb {Z}}}$ satisfies (equation eq:mu_iid of the paper), with $\alpha$ a uniformly elliptic probability measure on $(0,1)$, (equation eq:ue of the paper), non-lattice, (equation non-lattice of the paper), and fluctuation parameter $s \in [0,1) \cup (2,\infty)$. Assume that $(X^{(k)}, k \in {\mathbb {N}})$ are independent and that $ X^{(k)}= (X^{(k)}_n, n \in {\mathbb {Z}}_+)$ is distributed according to(equation eq:annealed_rwre of the paper), $ X^{(k)}$ is RWRE under the annealed law $\mu$ fixed above. Let $\tau$ be a resampling map, as in  (equation cooling-general-tau of the paper) and let $ \mathfrak{X}=\prt{\mathfrak{X}_n, n\in{\mathbb {Z}}_+}$ be the sequence with $\mathfrak{X}_n$ as defined in (equation fluctuation-basic-decomposition of the paper) when $a_n$ is given by (equation alpha-a-var-scaling of the paper). Then the sequence $\mathfrak{X}$ is tight in the weak topology and its limit points are characterised as follows. Let $\lambda_{\tau,n} = (\lambda_{\tau,n}(k), k \in {\mathbb {N}})$ with $\lambda_{\tau,n}(k)$ as defined in (equation variance-lambda-scaling of the paper). If $(n_i)_{i\in{\mathbb {N}}_0}$ is such that
\begin{equation}
\lim_{i\to\infty} \lambda^{\downarrow}_{\tau,n_i}(k) =: \lambda_*(k) \qquad \forall\,k \in {\mathbb {N}}_0,
\end{equation}
then $\lambda_* = (\lambda_*(k), k \in {\mathbb {N}}) \in \ell_2({\mathbb {N}})$ and

\begin{equation}
\mathfrak{X}_{n_i}
\overset{L^2}{\longrightarrow}
W_s^{\otimes \lambda_*}
+ a(\lambda_*)\,\Phi \qquad \forall\,p>0,
\end{equation}

where $a(\lambda_*) := (1 - \|\lambda_*\|_2^2)^{\tfrac12}$, $\Phi$ is a standard normal random variable, and $W_s^{\otimes \lambda_*} $ is as in (equation e:Smix of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:23:03.034664+00:00","domain":"probability theory","id":"claim_500d0e1350affd92c4ee497ca250b211f6d83a9fc2c46a756a6dc7f1068b69ca","kind":"lemma","schema_version":1,"statement":"[Lemma 21 of arXiv:2605.03057, 'Uniform-in-time quantitative fluctuations of large scale interacting particle systems'] Assume Assumption~\ref{ass:second-malliavin-uniform}. Let $\hat{\omega}$ be the constant defined via \eqref{eq:def-omega-second-malliavin}. Fix
$ 0 \le r \le s \le u $, $ i,j,k \in \left\{ 1,\dots,N \right\} $, and
$ \alpha,\beta \in \left\{ 1,\dots,m \right\} $. Define, for every $\rho \in [s,u]$,
\begin{equation*}
Y_\rho^{q,j,k,\alpha,\beta}
=
D_r^{k,\beta} D_s^{j,\alpha} X_\rho^{q,N}\quad\mbox{and}\quad
\bar v(\rho)
=
\frac1N \sum_{q=1}^N
\E\left(
\norm{Y_\rho^{q,j,k,\alpha,\beta}}^4
\right)^{1/4}.
\end{equation*}
Then, there exists a constant $ C > 0 $, depending only on the constants in
Assumption~\ref{ass:second-malliavin-uniform}, such that the following bounds hold.

\begin{enumerate}
\item[(i)] The initial condition in Lemma~\ref{lem:secondSDE} satisfies
\begin{align}

&\E\left(\norm{
\mathcal I_{r,s}^{i,j,k,\alpha,\beta}
}^4
\right)^{1/4}
\le
C e^{-\hat{\omega} (s-r)}
\left(
\mathbf{1}_{\left\{ i=j=k \right\}}
+
\frac1N
\left(
\mathbf{1}_{\left\{ i=j \right\}}
+
\mathbf{1}_{\left\{ i=k \right\}}
\right)
+
\frac1{N^2}
\right).
\end{align}

\item[(ii)] For every $ \rho \in [s,u] $,
\begin{equation}

\E\left(
\abs{G_{r,s}^{i,j,k,\alpha,\beta}(\rho)}^4
+
\norm{H_{r,s}^{i,j,k,\alpha,\beta}(\rho)}^4
\right)^{1/4}
\le
2^{1/4}\gamma \bar v(\rho).
\end{equation}

\item[(iii)] For every $ \rho \in [s,u] $,
\begin{align}

&\E\left(
\norm{R_{r,s}^{i,j,k,\alpha,\beta}(\rho)}^4
+
\norm{S_{r,s}^{i,j,k,\alpha,\beta}(\rho)}^4
  \right)^{1/4}\nonumber \\
  &\qquad\qquad\qquad\qquad
\le
C e^{-\hat{\omega} (\rho-r)}
\left(
\mathbf{1}_{\left\{ i=j=k \right\}}
+
\frac1N
\left(
\mathbf{1}_{\left\{ i=j \right\}}
+
\mathbf{1}_{\left\{ i=k \right\}}
+
\mathbf{1}_{\left\{ j=k \right\}}
\right)
+
\frac1{N^2}
\right).
\end{align}
\end{enumerate}","status":"unverified"}

