{"assumptions":[],"created_at":"2026-10-27T18:51:26.589433+00:00","domain":"probability theory","id":"claim_5559d0df0617430f7b393923e1af78f7d7ce0602b7aa0e12bc282e461e655f17","kind":"theorem","schema_version":1,"statement":"[Theorem thm:SaS-integral of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] Let $M_\alpha$ be a S$\alpha$S random measure with control measure $m$
and $\alpha \in (1,2]$.
\begin{enumerate}[label=(\roman*)]
\item \textbf{Existence and characteristic function.}
  $\int_E f\,dM_\alpha$ is a well-defined S$\alpha$S random variable
  if and only if $f \in L^\alpha(E,m)$, with
  \begin{equation}

  \mathbb{E}\!\left[e^{i\theta\int_E f\,dM_\alpha}\right]
  = \exp\!\left(-|\theta|^\alpha \int_E |f|^\alpha\,dm\right),
  \quad \theta \in \mathbb{R},
  \end{equation}
  and scale $\bigl\|\int_E f\,dM_\alpha\bigr\|_\alpha
  = \|f\|_{L^\alpha(E,m)}$.
\item \textbf{Linearity.}
  For $f, g \in L^\alpha(E,m)$ and $a, b \in \mathbb{R}$:
  \[
  \int_E (af+bg)\,dM_\alpha
  = a\int_E f\,dM_\alpha + b\int_E g\,dM_\alpha
  \quad \text{a.s.}
  \]
\item \textbf{Finite-dimensional distributions.}
  For $f_1,\ldots,f_m \in L^\alpha(E,m)$:
  \begin{equation}

  \mathbb{E}\!\left[\exp\!\Bigl(i\sum_{j=1}^m \theta_j
    \int_E f_j\,dM_\alpha\Bigr)\right]
  = \exp\!\left(-\int_E\Bigl|\sum_{j=1}^m \theta_j f_j\Bigr|^\alpha
    \,dm\right).
  \end{equation}
\item \textbf{$L^\alpha$ continuity.}
  If $\|f_k - f\|_{L^\alpha(E,m)} \to 0$, then
  $\int_E f_k\,dM_\alpha \to \int_E f\,dM_\alpha$ in probability.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:32:28.996815+00:00","domain":"probability theory","id":"claim_5561f35bdb5ffc03f852a64be6f96b1bcc00cb7c09e0cd0473625e276332c603","kind":"concept","schema_version":1,"statement":"[Lem Dir int of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] Fix $n \in \mathbb{N}$
