{"assumptions":[],"created_at":"2026-10-27T20:48:25.144830+00:00","domain":"probability theory","id":"claim_5aadd0b3cef18ead423be391098b1d4824ad53bb3ca933e92dda74116622a9fc","kind":"concept","schema_version":1,"statement":"[Thm lorenz96 of arXiv:2607.05097, 'Asymptotics of Lyapunov Exponents and Phase Transitions for Fluids with Degenerate Forcing'] For each $z \in \mathbb{R}^K$, let $A(z): \mathbb{R}^{2K} \to \mathbb{R}^{2K}$ be given by
\begin{equation}
    \begin{aligned}
        (A(z)x)_{2k} &= (x_{2k+1} - x_{2k-1})z_k \\
        (A(z)x)_{2k+1} &= (z_{k+1}-z_k)x_{2k}
    \end{aligned}
\end{equation}
(the indices for $x$ are taken modulo $2K$ and those for $z$ are taken modulo $K$) 
and define $\lambda(z)$ to be the largest real part of the eigenvalues of $A(z)$. Then
    \begin{equation}
        \lim_{\epsilon \downarrow 0} \lambda_\epsilon^\perp = \mathbb{E}[\lambda(Z)] > 0 \,,
    \end{equation}
    where $Z$ is an $\mathbb{R}^K$-valued Gaussian random variable with mean $0$ and covariance matrix $\frac{1}{2}I$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:17:42.312101+00:00","domain":"probability theory","id":"claim_5ad4b3a85e357ce9ca530a9874fac7756a97663d29ee3909acf5fe4e2bd519eb","kind":"concept","schema_version":1,"statement":"[Proposition 18 of arXiv:2608.05931, 'Effective Lagrangian regularity and the uniqueness threshold for random H\"older velocity '] Fix $\alpha\in(0,1)$, $\lambda>0$, and $p\geq 1$, and let, for all $j\geq 0$, $u^j$ be defined by~\eqref{eq:autonomous poisson}. Suppose there exists $M\geq 1$ such that for all $j\geq 0$, $n\in\{0,1,2\}$, and $y\in\T^d,$
\[\|\nabla^n f^j_y\|_{L^p_\omega C^0_x}\leq M 2^{(n-\alpha-d/p)j}.\]
Then 
\begin{enumerate}
    \item the $u^j$ are mutually independent with $\E u^j =0$,
\item for each $j\geq 1$, $u^j$ has a finite spatial range of dependence $2^{-j}$,
\item and there exists a constant $C(d)>0$ such that for all $j\geq 0$ and $n\in\{0,1,2\}$,
\[\|\nabla^n u^j\|_{L^p_\omega C^0_x}\leq CM(\lambda+p)2^{(n-\alpha)j}.\]
\end{enumerate}
Letting $U:=\sum_{j= 0}^\infty u^j$, we further have that
\begin{enumerate}
    \item[(i)] if for all $j\geq 0$ and $y\in\T^d$, $\nabla\cdot f^j_y=0$, then $\nabla\cdot U=0$,
    \item[(ii)] if there exists $r\in(0,1)$ and $C>0$ such that for all $j\geq 0$
    \begin{equation}
    \sup_{\substack{x,y\in\T^d\\d_{\T^d}(x,y)\leq 2^{-(j+2)}}}\bigg\|\frac{d\mu^j_{y,x}(z)}{dz}\bigg\|_{L^\infty(\R^d)}\leq Cr^j e^{\lambda j},
    \end{equation}
    then it almost surely holds that for all $\alpha'<\alpha$
    \[\lim_{\eps\rightarrow 0} \eps^{-\alpha'd}|Z_\eps|=0,\]
    where $Z_\eps$ is defined as in~\eqref{eq:zero sets}.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

