{"assumptions":[],"created_at":"2026-10-27T19:55:37.882623+00:00","domain":"probability theory","id":"claim_5ea9e90948cd49ef6befe10643ffeaa7206bcb5c83606c5daaf45d0ecf362247","kind":"theorem","schema_version":1,"statement":"[Thm t:InfMA of arXiv:2605.08983, 'A functional limit theorem for self-normalized linear processes with random coefficients a'] Let $(X_{i})$ be a linear process defined by
$$ X_{i} = \sum_{j=0}^{\infty}C_{j}Z_{i-j}, \qquad i \in \mathbb{Z},$$
where $(Z_{i})_{i \in \mathbb{Z}}$ is an i.i.d.~sequence of regularly varying random variables satisfying $((e:regvar of the paper))$ and $((eq:pq of the paper))$ with $\alpha \in (0,2)$. Assume conditions $((e:oceknula of the paper))$ and $((e:sim of the paper))$ hold. Let $(C_{i})_{i \geq 0}$ be a sequence of random variables, independent of $(Z_{i})$, satisfying conditions $((eq:InfiniteMAcond of the paper))$, $((e:momcond2 of the paper))$,
\begin{equation}
\sum_{j=0}^{\infty} (\mathrm{E}|C_{j}|^{2r})^{1/2} < \infty \qquad \textrm{for some}  \ r \in (\alpha/2, 1 \wedge \alpha),
\end{equation}
and
\begin{equation}
         \sum_{i=0}^{\infty}\mathrm{E}(|C_{i}|^{\gamma} + |C_{i}|^{2 \gamma}) < \infty
\end{equation}
for some $\gamma \in (\alpha, 1)$ if $\alpha \in (0,1)$ and $\gamma \in (\alpha/2, 1)$ if $\alpha \in [1,2)$.

If $\alpha \in [1,2)$ suppose further

\begin{equation}
\sum_{j=0}^{\infty} \mathrm{E}|C_{j}| < \infty.
\end{equation}

Then, as $n \to \infty$,
\begin{equation}
L_{n}(\,\cdot\,) \xrightarrow{d}  (C^{(1)}V(\,\cdot\,), C^{(2)}W(\,\cdot\,))
\end{equation}
 in $D^{2}$ with the weak $M_{2}$ topology,
 where $V$ is an $\alpha$--stable L\'{e}vy process with characteristic triple $(0, \mu, b)$, with $\mu$ as in $((eq:mu of the paper))$,
$$ b = \left\{ \begin{array}{cc}
                                   0, & \quad \alpha = 1,\\[0.4em]
                                   (p-r)\frac{\alpha}{1-\alpha}, & \quad \alpha \in (0,1) \cup (1,2),
                                 \end{array}\right.$$
with $p$ and $r$ defined in $((eq:pq of the paper))$, $W$ is an $\alpha/2$--stable L\'{e}vy process with characteristic triple $(0, \widetilde{\mu}, \alpha/(2-\alpha))$ with $\widetilde{\mu}(\mathrm{d} x) = (\alpha /2) x^{-\alpha/2-1} 1_{(0,\infty)}(x)\,\mathrm{d} x$,
and $(C^{(1)}, C^{(2)})$ is a random vector, independent of $(V, W)$, such that
$(C^{(1)}, C^{(2)}) \stackrel{d}{=} (C, C^{S})$, where $C=\sum_{i=0}^{\infty}C_{i}$ and $C^{S}=\sum_{i=0}^{\infty}C_{i}^{2}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:30.012744+00:00","domain":"probability theory","id":"claim_5ec495f92e0c9c6b5d6ec69e076e9a55b8943640afa981b70d6e1c722d6bc85d","kind":"definition","schema_version":1,"statement":"[Definition 16 of arXiv:2605.04359, 'Well-posedness of reflected BSDEs with default time and irregular barrier: An application '] Let $Y \in \mathcal{S}^2_{\beta}$.
	\begin{itemize}
		\item  The process $Y$ is said to be a strong $\mathcal{E}^f$-supermartingale (resp. $\mathcal{E}^f$-submartingale), if $\mathcal{E}^f_{\sigma,\eta}(Y_{\eta}) \leq Y_\sigma$ (resp. $\mathcal{E}^f_{\sigma,\eta}(Y_{\eta}) \geq Y_\sigma$) a.s. on $\sigma \leq \eta$, for all $\sigma,\eta \in \mathcal{T}_{[0,T]}$.
		\item The process $Y$ is said to be a strong $\mathcal{E}^f$-martingale, if it is both a strong $\mathcal{E}^f$-supermartingale and a strong $\mathcal{E}^f$-submartingale.
	\end{itemize}
	Let $\sigma,\eta \in \mathcal{T}_{[0,T]}$.
	\begin{itemize}
		\item The process $Y$ is said to be a strong $\mathcal{E}^f$-supermartingale (resp. $\mathcal{E}^f$-submartingale) on $[\sigma,\eta]$, if for all $\sigma^{\star}, \eta^{\star} \in \mathcal{T}_{[0,T]}$ such that $\sigma \leq \sigma^{\star} \leq \eta^{\star} \leq \eta$ a.s., we have $\mathcal{E}^f_{\sigma^{\ast},\eta^{\ast}}(Y_{\eta^{\ast}}) \leq Y_{\sigma^{\ast}}$ (resp. $\mathcal{E}^f_{\sigma^{\ast},\eta^{\ast}}(Y_{\eta^{\ast}}) \geq Y_{\sigma^{\ast}}$) a.s. Finally, the notion of $\mathcal{E}^f$-martingale on $[\sigma,\eta]$ is defined similarly.
	\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:41:54.369874+00:00","domain":"probability theory","id":"claim_5ed0f652454c329032ac5dc5549e7b4727d7b72748302d50a5f73e18c8d67204","kind":"concept","schema_version":1,"statement":"[Propo oo of arXiv:2412.01673, 'Spatial SIR epidemic model with varying infectivity without movement of individuals'] The system of equations (equation sy of the paper) admits a unique solution  $\left\{\left(\overline{\mu}^S_t,\overline{\mu}_t^{\mathfrak{F}},\overline{\mu}_t^{I},\overline{\mu}_t^{R}\right),\ t\ge0\right\}$   which is absolutely continuous with respect to the Lebesgue measure, with the densities\\ $\left\{\left(\overline{\mu}^S(t,.), \overline{\mu}^{\mathfrak{F}}(t,.), \overline{\mu}^{I}(t,.) ,\overline{\mu}^{R}(t,.)\right),\ t\ge0\right\}$ satisfying for all $(t,x)\in \mathbb{R}_+\times D$
	\begin{equation}

	\left\lbrace
