	\mathbb{P}(h^\alpha(t, x; \delta_y) \ge t/2 + \epsilon t) &\le 2\exp\left(-c\epsilon^{3}t^2\right), \qquad \epsilon \in (0, 1),\qquad \text{ and} \\
    \mathbb{P}(h^\alpha(t, x; \delta_y) \le t/2 - \epsilon t) &\le 2\exp\left(-c\epsilon^{3/2}t\right), \qquad \epsilon \in (0, t^{-1/3}).
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:14:37.644195+00:00","domain":"probability theory","id":"claim_62b3c0aab17d1ce9544e03ac32f776ffd9474e3bcd605fc92ea8767e06d9db80","kind":"concept","schema_version":1,"statement":"[Lemma 12 of arXiv:2608.19179, 'A random walk on $p$-groups with a symmetric perfect pairing'] $M_{n,n}$ determines the following data, when $M_{n-1,n-1}$ is non-singular.
