{"assumptions":[],"created_at":"2026-10-27T21:54:18.299498+00:00","domain":"probability theory","id":"claim_636ee5a3ffdf32cdd4a74943237b6421dbed8a59ab976ec78b058fe08f329212","kind":"theorem","schema_version":1,"statement":"[Prop 7463 of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $ ( X, U ) $ be a $ ( c, q ) $-regular innovation
on a measurable set $ \mathcal V $ and let $ ( \theta_n ) $ be an \RMSprop\ algorithm
with arbitrary parameter tuple $ ( \beta, \varepsilon, (\gamma_n), \theta_0 ) $ as in the introduction.
Let $ n_0 \in {\mathbb N}_0 $ and let $ \tau $ be the stopping time given by
\bas{ 
 \tau=\inf\{n\ge n_0: \theta_n\not\in \mathcal V\}.}

One has for every $n\in{\mathbb N}_0\cap [n_0,\infty)$, $i\in\{1,\dots,d\} $, $ \lambda\in[0,\infty)$ that
\bas{
-\ln {\mathbb E}\bigl[e^{-\lambda (v_n^{(i)}+\1_{\{ n\le \tau\}^c}\infty)}|\mathcal F_{n_0}\bigr]\ge\sum_{k=n_0+1}^n \left( c \frac{1-\beta}{1-\beta^n} \beta^{n-k} \lambda \right) \wedge q +\frac{1-\beta^{n_0}}{1-\beta^n} \beta^{n-n_0} \lambda  v_{n_0}^{(i)} .
}
In the case $n=n_0=0$, the last term on the right-hand side is understood as zero.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.369548+00:00","domain":"probability theory","id":"claim_638360efca500ad6bc275589ea3a0f0f6e33d9859fbe72090e59402338d09e84","kind":"theorem","schema_version":1,"statement":"[Theorem eq:ap1:linGrowthCondition of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Fix $T \in (0, \infty)$. Suppose $f:[0, T] \times \mathbb{R}^m \rightarrow \mathbb{R}^m$ is a measurable function that satisfies the linear growth condition \begin{equation}
    \sup_{t \leq T}|f_t(x)| \leq C_f(1 + |x|), \quad \text{a.e. }x \in \ensuremath{\mathbb{R}}^d,

\end{equation}
for some $C_f \in (0, \infty)$. Suppose $\mu_0 \in \mathcal{P}(\ensuremath{\mathbb{R}}^m)$ satisfies has finite entropy and second moment. Then the following properties hold.
\begin{enumerate}
    \item The Fokker-Planck equation  (equation eq:ap1:formalPDE of the paper) has a unique weak solution $\{\mu_t\}_{t \in [0, T]}$ such that $\mu_t \in \mathcal{P}(\ensuremath{\mathbb{R}}^m)$ is a probability measure for all $t \in [0, T]$. Moreover, $\mu_t$ has a finite second moment, that is,
\begin{equation}

    \sup_{t \in [0, T]} \int_{\ensuremath{\mathbb{R}}^m} |x|^2 \mu_t(x)dx < \infty.
\end{equation}    
    \item There exists a positive locally H\"older continuous function $\mu:[0, T] \times \ensuremath{\mathbb{R}}^{m} \rightarrow (0, \infty)$ such that $\mu_t(dx) = \mu_t(x) dx$.  The H\"older coefficient and exponent of $\mu$ depends only on $(m,T)$, the linear growth condition of $f$, and the initial condition $\mu_0$. Moreover, $\mu_t \in W^{1, p}_{loc}(\ensuremath{\mathbb{R}}^m)$ for almost every $t \in [0, T]$ and $\mu \in H^{1, p}_{loc}(\ensuremath{\mathbb{R}}^m_T)$ for all $p \geq 1$.
    \item  For every $t \in [0, T]$, we have
\begin{equation}

    \int_0^t \int_{\ensuremath{\mathbb{R}}^{m}} \frac{|\nabla \mu_s(x)|^2}{\mu_s(x)} dx ds < \infty.
\end{equation}
Moreover, we have $\mu \in H^{1, 1}(\ensuremath{\mathbb{R}}^m_T)$ and $\mu_t \in W^{1, 1}(\ensuremath{\mathbb{R}}^m)$ for almost every $t \in (0, T)$.  
\item We have for all $t \in [0, T]$ that
\begin{equation}
    \int_{\ensuremath{\mathbb{R}}^m} \mu_t(x) |\log \mu_t(x)| dx < \infty

\end{equation}
and
\begin{equation}
        \int_0^T \int_{\ensuremath{\mathbb{R}}^m} \mu_t(x) |\log \mu_t(x)| dx < \infty.

\end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:28:49.116007+00:00","domain":"probability theory","id":"claim_639468c3a81c9c6d4a259d0c3a1c1531c37f560be2ebbe408a0a50f8223d5e7b","kind":"definition","schema_version":1,"statement":"[Dfn of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] On ${\mathbb{R}}^d$ ($d\ge 3$),  we say a function $h: {\mathbb{R}}^d\rightarrow {\mathbb{R}}$ is in Kato class $\mathbf{K}_{d,k}$ (for $k=1,2$) if
