\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:52:05.645664+00:00","domain":"probability theory","id":"claim_6398878165237e528dcf40028a14bf94867441b1fabf439c768f910b1273c0c1","kind":"definition","schema_version":1,"statement":"[Defn Two-valued sets of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $a,b\in \mathbb R$ and let $u$ be a harmonic function in $D$. Let $\phi$ be a GFF with boundary condition $u$ in $D$.  We say that a random closed set $\mathds A_{-a,b}^u$ is a two-valued set with boundary condition $u$ if
\begin{itemize}
    \item $(\phi,\mathds A_{-a,b}^u)$ is a local set,
    \item there exists a random function $h_{\mathds A_{-a,b}^u}$ such that 
    \[
        (\phi_{\mathds A_{-a,b}^u},f)=\int_{D\backslash \mathds A_{-a,b}^u} h_{\mathds A_{-a,b}^u}(z) f(z)dz
        \quad \text{a.s.}
    \]
    for all $f \in C_c^\infty(D)$,
    \item the function $h_{\mathds A_{-a,b}^u}-u$ takes values in the set $\{-a,b\}$.
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:09:23.956746+00:00","domain":"probability theory","id":"claim_63d6a42ab1db564ce30403415f0cdd8a5a22d8ef57dbabcc4850f52fcba3b5e9","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2607.21931, 'Lorenz and convex ordering of parasite burden distributions with density-dependent deaths'] The {\em Lorenz curve} $L: [0,1] \to [0,1] $ for the distribution $F$ on $[0,\infty)$ with finite mean $ \mu$ is given by
    \begin{equation*}
        L(u) = \frac{\int_{0}^{u} F^{-1}(y)\, dy}{\mu}, 
    \end{equation*}
    where $ F^{-1}$ is the quantile function
    \begin{equation*}
        F^{-1}(y) = \inf \{ x : F(x) \geq y \} \quad \text{for } y \in (0,1).
    \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:09:59.308232+00:00","domain":"probability theory","id":"claim_63d8d358ccc965cffea74c8e42cc6cac8e289023695486bb3f560e3508c5f583","kind":"lemma","schema_version":1,"statement":"[Lemma Lemma_phi_martingale_on_stochastic_interval of arXiv:2608.08299, 'Non-linear optimal stopping with Bermudan strategies: the infinite horizon case'] Let $\rho$ satisfy the consistency property (v).
    Let $\phi=(\phi(\nu))$ be a given non-negative admissible family.
    Let $S$ $\in$ $\Theta$ and $\tau$ $\in$ $\Theta$ be such that $S \leq \tau$ a.s. 
    We assume that for any  $\sigma$ $\in$ $\Theta$ such that $S \leq \sigma \leq \tau$ a.s., it holds 
    \begin{equation}
        \rho_{\sigma,\tau}[\phi(\tau)] = \phi(\sigma) \,\,\,\, a.s.
    \end{equation}
    Then, $\phi$ is a \emph{$(\Theta, \rho)$}-martingale on the stochastic interval $[S,\tau]$, that is, for any  $\nu_1$ $\in$ $\Theta$, and $\nu_2$ $\in$ $\Theta$, such that $S \leq \nu_1 \leq \nu_2 \leq \tau$ a.s.,
    \begin{equation}
          \rho_{\nu_1,\nu_2}[\phi(\nu_2)] = \phi(\nu_1) \,\,\,\, a.s.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:48:27.276894+00:00","domain":"probability theory","id":"claim_643094e6fa1d01383a7be3ebdedb9b72c0d9e29bb845125cfa9fb1f151ec1e4a","kind":"definition","schema_version":1,"statement":"[Definition 2 of arXiv:2604.24664, 'Absolute continuity of Rosenblatt measures'] Let $\alpha > 0$ and $f \in L^1([0, T])$. The \emph{left} and \emph{right  Riemann--Liouville fractional integrals of $f$ of order $\alpha$} are defined by
	\begin{align*}
		(I^\alpha_{0+} f)(x) &= \frac{1}{\Gamma(\alpha)} \int_0^x (x-y)^{\alpha-1} f(y) \d{y},
		\\
		(I^\alpha_{T-} f)(x') &= \frac{1}{\Gamma(\alpha)} \int_{x'}^{T} (y-x')^{\alpha-1} f(y) \d{y},
	\end{align*}
	respectively, for almost all $x,x' \in [0, T]$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:57:59.844092+00:00","domain":"probability theory","id":"claim_644d38dd756f7808a2903c4744ba05502904081a7d0076aa8e176f73817e8610","kind":"concept","schema_version":1,"statement":"[Theorem key:theorem of arXiv:2606.09488, 'The temporal stochastic block model'] Let $\boldsymbol{F}=(F_t)_{t\geq 1}$ be a block-regular sequence with respect to $(V_1,\ldots,V_k)$, of rate $n_* = (1-o(1))n$, associated to $(G^*,\pi^*)$ and $v$. If ${\cal{I}}^{\boldsymbol{F}}$ is a tree, then, whp
