{"assumptions":[],"created_at":"2026-10-27T22:57:49.859503+00:00","domain":"probability theory","id":"claim_68d1ba97fc56fcaffb98032ec09334cc6fb3e9065ac4e9ad7ce268ad6bfc38aa","kind":"concept","schema_version":1,"statement":"[Lem kolmogorov of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] {durrett}}] 
