{"assumptions":[],"created_at":"2026-10-26T20:52:45.028878+00:00","domain":"probability theory","id":"claim_6d965a5024517a12a352da2e81ccf3481a7cad536a743e9da9194c266feb06e4","kind":"concept","schema_version":1,"statement":"[Theorem 3 of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] Let $W^H$ be an fBm of parameter $H\in (0,+\infty)\setminus\N$, $\kappa>0$ and let $u\in L^\infty([0,1];C^\alpha(\T^d))$ with\footnote{Condition $\alpha\geq 0$ in~\eqref{eq:condition_fBm_SWP} is not even needed in~\cite{GalGer2025}, which is set on $\R^d$; we only enforce it in order to avoid technicalities concerning the interpretation one must give to the integral in~\eqref{eq:SDE_fBm:SWP} and the identification of elements of $C^{-\theta}(\T^d)$ with suitable elements of $C^{-\theta}(\R^d)$.}
    \begin{equation}
        \alpha\geq 0, \quad \alpha>1-\frac{1}{2H}.
    \end{equation}
    Then, for any $x\in\T^d$, there exists a strong, pathwise unique solution to the SDE
    \begin{equation}
        X^\kappa_t = x + \int_0^t u(r,X^\kappa_r) \dd r + \kappa W^H_t.
    \end{equation}
    Moreover, the SDE admits a stochastic flow of diffeomorphisms $\{X^\kappa_{s,t}(x,\omega)\}$ on $\T^d$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:07:35.023310+00:00","domain":"probability theory","id":"claim_6dc2469340e67e3cf883102daa801c4f7b12fe5015f4ae2aa9c86f9de627df56","kind":"concept","schema_version":1,"statement":"[Pro 5 (\protect{\cite[Propositions B.3 and B.8) of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] {Cannarsa_Cheng3}}]
	Let $H:\T^n\times\R^n\to\R$ be a Tonelli Hamiltonian and let $A_t(x,y)$ be the associated fundamental solution. Then the following statements hold.
	\begin{enumerate}[\rm (1)]
		\item For every $R>0$ there exist $t_R>0$ and $K_R>0$, depending on $R$ and on the local $C^2$ modulus and the Tonelli modulus of $H$, such that, for every $0<t\leqslant t_R$ and $y\in\T^n$, the function $x\mapsto A_t(x,y)$ is semiconcave with constant $K_R/t$ on $B(y,Rt)$, understood in local flat coordinates. The threshold $t_R$ is chosen small enough that these balls lie within the injectivity radius.
		\item For every $R>0$ there exist $\tau_0(R)\in(0,1]$ and $K(R)>0$, depending on $R$ and on the local $C^2$ modulus and the Tonelli modulus of $H$, such that for every $t\in(0,\tau_0(R)]$ and $y\in\T^n$ the function $x\mapsto A_t(x,y)$ is of class $C^2$ on the ball $B(y,Rt)$ and satisfies
		\begin{equation}
			D_{xx}A_t(x,y)\geqslant\frac{K(R)}{t}\,I,\qquad\forall x\in B(y,Rt).
		\end{equation}
	\end{enumerate}
	The result for the initial endpoint follows from the corresponding result for the terminal endpoint by using the reversed Lagrangian $\widehat L(x,v)=L(x,-v)$, whose action satisfies $\widehat A_t(y,x)=A_t(x,y)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

