{"assumptions":[],"created_at":"2026-10-27T18:51:26.590107+00:00","domain":"probability theory","id":"claim_7ad8e91af9eab17f5c892a1fce1e42be3e1e219519916bf16c895b4ea04a4e11","kind":"lemma","schema_version":1,"statement":"[Lemma lem:kernel-asymp of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] Under Assumption~(ass:params of the paper), with $\gamma(t) = H(t)-1/\alpha$:

\begin{enumerate}[label=(\roman*)]

\item \textbf{Vanishing for $u > t$.}
  For all $u > \max\{0,t\}$: $f_n(t,u;H,\alpha) = 0$.

\item \textbf{Near-diagonal behaviour.}
  For $u \in (t-\delta, t)$ with $\delta \in (0,t)$ sufficiently
  small (so that $u > 0$):
  \begin{equation}

  f_n(t,u;H,\alpha)
  = \frac{(t-u)^{\gamma(t)}}{\Gamma(\gamma(t)+1)} + R_1(t,u),
  \end{equation}
  where $|R_1(t,u)| \leq C_1\,(t-u)^{\gamma(t)+1}$ for a constant
  $C_1 > 0$ uniform in $t$ on compact intervals.

\item \textbf{Tail behaviour.}
  For $u < \min\{0, t-1\}$ (so that $|u|$ is large and $|t/u| < 1$):
  \begin{equation}

  f_n(t,u;H,\alpha)
  = C_n(t)\,|u|^{\gamma(t)-n} + R_2(t,u),
  \end{equation}
  where $|R_2(t,u)| \leq C_2\,|u|^{\gamma(t)-n-1}$, and the leading
  coefficient is
  \begin{equation}

  C_n(t)
  = \frac{(-t)^n}{\Gamma(\gamma(t)+1)}\binom{\gamma(t)}{n},
  \quad
  \binom{\gamma}{n} := \frac{\gamma(\gamma-1)\cdots(\gamma-n+1)}{n!}.
  \end{equation}
  The constant $C_2 > 0$ is uniform in $t$ on compact intervals.

\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:54:12.501030+00:00","domain":"probability theory","id":"claim_7b1330d9c84d199927494e3a4c8a322dfdc01d29ae400efba5426c8b3de3e69f","kind":"concept","schema_version":1,"statement":"[Lemma lem:invp of arXiv:2604.10020, 'The directed landscape in half-space'] We have
