\item[\namedlabel{W2}{W2}]  \emph{(Uniform Integrability)} 
 \begin{equation}\notag
	\lim_{A\to \infty} \sup_{k,m} {\mathbb {E}} \crt{\left\vert X_k(m)\right\vert \mathbbm{1}_{\left\vert X_k(m)\right\vert>A}} = 0. 
