{"assumptions":[],"created_at":"2026-09-07T12:18:08.279474+00:00","domain":"probability theory","id":"claim_853352cf46ab2326b55958802ef6352ea0c083015c5ea9294b3518fa7547df30","kind":"concept","schema_version":1,"statement":"[Lemma 12 (Lemma 4.6 in \cite{Ledoux_Book}) of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] Let $F: \mathbb{R}^{+}\to \mathbb{R}^{+}$ be a convex non-decreasing function. Assume that $\{\eta_{i}, i\le n\}$ and $\{\xi_{i}, i\le n\}$ are two  sequences of independent symmetric random variables such that for some constant $K\ge 1$
	\begin{align}
		\mathbb{P}\{\vert \eta_{i}\vert>t  \}\le K\mathbb{P}\{\vert\xi_{i}\vert >t \},\quad i\le n,\quad t>0.
	\end{align}
	Then, for any sequence $\{a_{i}, i\le n\}$ in a Banach space $(\mathcal{A}, \Vert\cdot\Vert)$,
	\begin{align}
		\mathbb{E}F\Big( \big\Vert \sum_{i=1}^{n}a_{i}\eta_{i}\big\Vert    \Big)\le \mathbb{E}F\Big(K \big\Vert \sum_{i=1}^{n}a_{i}\xi_{i}\big\Vert   \Big).\nonumber
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:06.329992+00:00","domain":"probability theory","id":"claim_853d41ed05802628bc5d8c8b18c131759eb3957ea8d97d5a5b6cade1fb79d572","kind":"concept","schema_version":1,"statement":"[Theorem 18 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Let $H\in\left(0,1\right)$ and $(\mathbf{x}_t)_{t\geq 0}$ be a solution to \eqref{eq:fast system simplified} in the setting \nameref{S2}. For any $\tau\ge0$, it holds that
\begin{align}
    \begin{split}
    &V_\infty(\tau)\left[ \mathbf{e}_{j_1}^*(\lambda), \mathbf{e}_{j_2}^*(\lambda) \right]\\
    =& \left(-\zeta_{j_1}(\lambda)-\overline{\zeta_{j_2}(\lambda)}\right)^{-1} H \left\langle  \mathbf{e}_{j_2}^*(\lambda), Q \mathbf{e}_{j_1}^*(\lambda)\right\rangle P(\zeta_{j_1}(\lambda),\zeta_{j_2}(\lambda),H,\tau) ,
    \end{split}
\end{align}
with $\zeta_1(\lambda)= A(\lambda) + i B(\lambda)= \overline{\zeta_2(\lambda)}$ and for any $j_1,j_2\in\{1,2\}$. Under the assumption that $\Sigma$ is not null, it follows that
\begin{align}
    |V_\infty(\tau)\left[ \mathbf{v}_1, \mathbf{v}_2 \right]|\asymp& |A(\lambda)|^{-1},
\end{align}
for almost every $\tau\ge0$ and any $\mathbf{v}_1, \mathbf{v}_2 \in \R^2$ such that
\begin{equation} 
    \begin{split}
        &e^{-i B(\lambda^*)\tau} \left\langle  \mathbf{e}_{1}^*(\lambda^*), Q \mathbf{e}_{1}^*(\lambda^*)\right\rangle \overline{\left\langle \mathbf{v}_1, \mathbf{e}_{1}(\lambda^*) \right\rangle} \left\langle \mathbf{v}_2, \mathbf{e}_{1}(\lambda^*) \right\rangle\\
        &+
        e^{i B(\lambda^*)\tau} \left\langle  \mathbf{e}_{2}^*(\lambda^*), Q \mathbf{e}_{2}^*(\lambda^*)\right\rangle \overline{\left\langle \mathbf{v}_1, \mathbf{e}_{2}(\lambda^*) \right\rangle} \left\langle \mathbf{v}_2, \mathbf{e}_{2}(\lambda^*) \right\rangle \neq 0.
    \end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

