{"assumptions":[],"created_at":"2026-10-27T15:12:20.559720+00:00","domain":"probability theory","id":"claim_93c354a8bab3ec5deb33a1c0a1ae0b6cbab01c44aa3457a193f92ed3f439df46","kind":"concept","schema_version":1,"statement":"[Corollary of arXiv:2604.04882, 'On a Problem of M. Kac on Laplace Distributions'] For every $n\in\mathbb N$, $\lambda>0$, and $\theta\in(0,1/2)$, the functions
    \begin{align}
        F_1(z)\coloneqq \left(\frac12+\frac{1}{2\bigl(1+\frac{\theta\lambda}{n}(1-z)\bigr)}\right)^n,
        \qquad
        F_2(z)\coloneqq \left(
        \frac{2+\frac{\theta\lambda}{n}(1-z)}
        {2+\frac{2\lambda}{n}(1-z)+\frac{\theta\lambda^2}{n^2}(1-z)^2}
        \right)^n
    \end{align}
    are pgfs satisfying
    \begin{align*}
        \Phi_n(F_1(z),F_2(z))
        =
        \left(1+\frac{\lambda}{n}(1-z)\right)^{-n},
        \qquad
        \Phi_n(x,y)\coloneqq \bigl(x^{-1/n}+y^{-1/n}-1\bigr)^{-n},
    \end{align*}
    but neither factor belongs to the negative binomial family $\left\{\left(1+\frac{\mu}{n}(1-z)\right)^{-n}:\mu>0\right\}.$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:23:27.788207+00:00","domain":"probability theory","id":"claim_94114c676ebc6001fb5fadd0d3ebd532f133834bb09340264d989fda17363d92","kind":"theorem","schema_version":1,"statement":"[Cor clt:I_n of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] Let $I^{(n)}:=\left(I_1^{(n)},\dots,I_m^{(n)}\right)\overset{d}{=}M(n;1/m,\dots,1/m)$. Then, with $\mu^{(n)}=(n/m,\ldots,n/m)^t$, we have
    \begin{align}
        I^{(n),\ast}:=\frac{I^{(n)}-\mu^{(n)}}{\sqrt{n}}\overset{d}{\longrightarrow} N=(N_1,\ldots,N_m),
    \end{align}
    where $\mathcal{L}(N)=\mathcal{N}(0,\Sigma)$ with 
\begin{equation}
\Sigma = \left( \begin{array}{cccc}
    \frac{m-1}{m^2} &-\frac{1}{m^2}& \cdots & -\frac{1}{m^2} \\
    -\frac{1}{m^2} & \ddots & &\vdots\\
    \vdots &  & \ddots& -\frac{1}{m^2} \\
    -\frac{1}{m^2} & \dots & -\frac{1}{m^2}& \frac{m-1}{m^2}
    \end{array}
    \right).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:38:08.413898+00:00","domain":"probability theory","id":"claim_94405741195849e1b81357e899f7f239802f830914d9bc24c2b2aee1d48cb5af","kind":"theorem","schema_version":1,"statement":"[Proposition prop: existence of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] Let $p\in (1,\infty)$. 
    \begin{itemize}
        \item If $(\lambda,C^2) \in \partial S_2$, then (equation eq:EL pointwise for w of the paper) has exactly one strictly positive solution $w=w_{\lambda,C^2}:\R \to \R$ with $w(0)=\|w\|_{L^\infty}=1$, namely the constant solution $w \equiv1$.
        \item If $(\lambda,C^2) \in S$, then (equation eq:EL pointwise for w of the paper) has exactly one strictly positive solution $w=w_{\lambda,C^2}:\R \to \R$ with $w(0)=\|w\|_{L^\infty}=1$, which is even, smooth and periodic with period $2P=2P(\lambda,C^2) \in (0,\infty)$. 
        \item If $(\lambda,C^2)=(\lambda,0)$ with $\frac{p-1}{2}<\lambda<p-1$, then (equation eq:EL pointwise for w of the paper) has exactly one strictly positive solution $w=w_{\lambda,C^2}:\R \to \R$ with $w(0)=\|w\|_{L^\infty}=1$, which is even, smooth and periodic with period $2P=2P(\lambda,0) \in (0,\infty)$. 
        \item If $(\lambda,C^2)=(\lambda,0)$ with $\lambda<\frac{p-1}{2}$, then there exists $P=P(\lambda,0)$ and a unique nonnegative continuous function $w=w_{\lambda,C^2}:\R \to \R$ satisfying the following properties:
        \begin{itemize}
            \item $w$ is even;
            \item $w$ is periodic with period $2P=2P(\lambda,0) \in (0,\infty)$;
            \item $w(0)=\|w\|_{L^\infty}=1$;
            \item   $w$ is smooth and satisfies (equation eq:EL pointwise for w of the paper) in $\R \setminus \{(2j-1)P:j\in \Z\}$;
            \item $w((2j-1)P)=0$ for every $j\in \Z$.
        \end{itemize}
    \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:26:26.799118+00:00","domain":"probability theory","id":"claim_94585549c70ed3263d8ef8a51192f1d248c057ec287e0ba1842f0c125b66f4e3","kind":"concept","schema_version":1,"statement":"[Lemma lem:conditional-expectations-next-day of arXiv:2608.06159, 'Majority Dynamics on Resampled Sparse Erd\H{o}s--R\'enyi Graphs:\\[0.5ex] Gaussian Winner '] For all \(t \geq 0\), the conditional expectations of the camp sizes on the next day can be expressed as
    \begin{subequations}
    \begin{align}
        \E\left[ |\gB_{t+1}|\,\middle|\, \rvy_{t} \right]
&\, = |\gR_{t}|p_t^{\gR} + |\gB_{t}|q_t^{\gB}, \\
        \E\left[ |\gR_{t+1}|\,\middle|\, \rvy_{t} \right]
&\, = |\gR_{t}|q_t^{\gR} + |\gB_{t}|p_t^{\gB}. 
    \end{align}
    \end{subequations}
    Furthermore, the conditional expectation of the advantage on the next day can be expressed as
    \begin{subequations}
        \begin{align}
            \E\left[\Delta_{t+1} \,\middle|\, \rvy_{t}\right]
            &\, = \Delta_t + 2 \left( |\gR_{t}|p_t^{\gR} - |\gB_{t}|p_t^{\gB} \right). \\
            &\, = N\bigl(p_t^{\gR}-p_t^{\gB}\bigr)
            +
            \Delta_t
            \bigl(1-p_t^{\gR}-p_t^{\gB}\bigr).

        \end{align}
    \end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

