{"assumptions":[],"created_at":"2026-10-27T19:32:28.996303+00:00","domain":"probability theory","id":"claim_94ea92a02a8ab62fbdab3825e4b6f18eef9222f7455ce7f4a1a74f0a6366a10b","kind":"concept","schema_version":1,"statement":"[Lem Kac mom of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] {Kajino_Noda_26_Kac}}]  
