{"assumptions":[],"created_at":"2026-10-27T22:20:15.584062+00:00","domain":"probability theory","id":"claim_9ebad29170ef56e0988370aa14f6bea985f83cc18c6cdeaa9ce184c1a6ae8a67","kind":"concept","schema_version":1,"statement":"[Theorem thmIntroProfile of arXiv:2609.00777, 'Universal murmuration and Hecke augmentation'] There is a single continuous function $G:(0,\infty)\to\mathbb R$ with the following property.
For every fixed integer $k\geq1$, let $X$, $Y$, and the prime $P$ tend to infinity while $P^k/X$ remains in a fixed compact subset of $(0,\infty)$.
For $k\geq2$, assume the short-window and growth conditions of Theorem~(thm:scaled-murmuration of the paper); for $k=1$, assume the conditions of Zubrilina~[Zubrilina2025].
Then, for normalized weight $2$ newforms of squarefree level in $[X,X+Y]$ with trivial nebentypus,
\begin{equation*}
\sqrt X\,
\mathbb E_{X,Y}
\bigl[\varepsilon(f)\lambda_{\operatorname{sym}^k f}(P)\bigr]
=
G\left(\frac{P^k}{X}\right)+o_k(1),
\end{equation*}
locally uniformly in $P^k/X$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:41:19.328840+00:00","domain":"probability theory","id":"claim_9ebc93a427e8d0d6589ed8a8d445faeccfc8c7d3a442e8c1a027e459464815c1","kind":"definition","schema_version":1,"statement":"[Definition def:oriented_cone of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $\mathbb G$ be a Carnot group and let $\mathbb H,\mathbb K$ be two
homogeneous subgroups of $\mathbb G$. We say that $\mathbb H$ and
$\mathbb K$ are \emph{complementary} if
\begin{align*}
\mathbb H\cap\mathbb K=\{e\}, \quad \mbox{and} \quad \mathbb G=\mathbb H\mathbb K.
\end{align*}
Assume moreover that $\mathbb K$ is a one-dimensional horizontal homogeneous
subgroup. Thus
\begin{align*}
\mathbb K=\exp(\mathbb RX)
\end{align*}
for some nonzero $X\in V_1$. Set
\begin{align*}
\mathbb K^+:=\{\exp(tX):t\geqslant0\}.
\end{align*}
For $p\in\mathbb G$ and $\beta,\rho>0$, we define the
\emph{oriented intrinsic cone} associated with the decomposition
$\mathbb G=\mathbb H\mathbb K$ by
\begin{align*}
\mathcal C_p^+(\beta,\rho;\mathbb H,\mathbb K)
:=
p\left\{
hk\in\mathbb H\mathbb K:
k\in\mathbb K^+,\ 
\|h\|\leqslant\beta\|k\|,\ 
\|k\|<\rho
\right\}.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.287715+00:00","domain":"probability theory","id":"claim_9f517d72ad0e636a91df2d37f3dc5a4229204ba0868e95cf85f9a36c1aad8cc9","kind":"lemma","schema_version":1,"statement":"[Lemma conditional hessian of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Fix $\mathbf{m}\in[-1,1]^N$ and set $q:=\|\mathbf{m}\|^2/N\in[0,1]$.
		Assume $q>0$ (the case $q=0$ does not arise in our applications).
		Choose an orthonormal basis
		\[
		e_1=\frac{\mathbf{m}}{\sqrt{Nq}},\qquad e_2,\dots,e_N\in \mathbf{m}^\perp,
		\]
		and decompose the Hessian $\nabla^2 H(\mathbf{m})$ in this basis as
		\[
		\nabla^2 H(\mathbf{m})=
		\begin{pmatrix}
			A & B^{\!\top}\\[1mm]
			B & C
		\end{pmatrix},
		\quad A\in\mathbb{R},\quad B\in\mathbb{R}^{N-1},\quad C\in\mathbb{R}^{(N-1)\times(N-1)}.
		\]
		Condition on $H(\mathbf{m})=Nf$ and $\nabla H(\mathbf{m})=x$.
		Write $x_\parallel:=\langle x,e_1\rangle$ and let
		\[
		x_\perp := \bigl(\langle x,e_2\rangle,\dots,\langle x,e_N\rangle\bigr)\in\mathbb{R}^{N-1}
		\]
		be the coordinate vector of the projection of $x$ onto $\mathbf{m}^\perp$ in the basis $(e_2,\dots,e_N)$.
		The following assertions hold.
		\begin{enumerate}[label=(\roman*)]
			\item \textup{(Tangent block.)}
			The block $C$ is independent of $\bigl(H(\mathbf{m}),\nabla H(\mathbf{m})\bigr)$, and its entries satisfy
			\[
			\mathrm{Cov} (C_{ij},C_{kl})=\frac{\xi''(q)}{N}\bigl(\delta_{ik}\delta_{jl}+\delta_{il}\delta_{jk}\bigr),
			\qquad i,j,k,l\in\{2,\dots,N\}.
			\]
			Equivalently (under the convention that $\mathrm{GOE}_{n}$ has off-diagonal variance $1$ and diagonal variance $2$),
			\[
			C\ \stackrel{d}{=}\ \sqrt{\xi''(q)}\;\frac{\mathrm{GOE}_{N-1}}{\sqrt{N}}.
			\]

			\item \textup{(Mixed block.)}
			Conditionally on $\bigl(H(\mathbf{m}),\nabla H(\mathbf{m})\bigr)$, the vector $B$ is Gaussian and independent of $C$, with
			\begin{equation}
				\mathbb{E}\!\left[B\;\middle|\;H(\mathbf{m})=Nf,\;\nabla H(\mathbf{m})=x\right]
				=\frac{\xi''(q)}{\xi'(q)}\,\sqrt{\frac{q}{N}}\; x_\perp,
			\end{equation}
			\begin{equation}
				\mathrm{Var}\!\left(B\;\middle|\;H(\mathbf{m})=Nf,\;\nabla H(\mathbf{m})=x\right)
				=\frac{1}{N}\!\left(\xi''(q)+q\,\xi^{(3)}(q)-\frac{\xi''(q)^2\,q}{\xi'(q)}\right) I_{N-1}.
			\end{equation}

			\item \textup{(Longitudinal entry.)}
			Assume that $\det\Sigma_X>0$ (this holds whenever $\xi$ is a mixed model).
			Define
			\begin{equation}
				\Sigma_X:=
				\begin{pmatrix}
					N\xi(q) & \xi'(q)\sqrt{Nq}\\[1mm]
					\xi'(q)\sqrt{Nq} & \xi'(q)+q\,\xi''(q)
				\end{pmatrix},
			\end{equation}
			\begin{equation}
				\Sigma_{A,X}:=\Bigl(\;\xi''(q)\,q\;,\;\bigl(\xi^{(3)}(q)\,q+2\,\xi''(q)\bigr)\sqrt{q/N}\;\Bigr),
			\end{equation}
			\begin{equation}
				\mathrm{Var}(A)=\frac{2\,\xi''(q)}{N}+\frac{4\,\xi^{(3)}(q)\,q}{N}+\frac{\xi^{(4)}(q)\,q^2}{N}.
			\end{equation}
			Then, conditionally on $\bigl(H(\mathbf{m}),\nabla H(\mathbf{m})\bigr)$, the entry $A$ is Gaussian and independent of $C$, with
			\begin{equation}
				\mathbb{E}\!\left[A\;\middle|\;H(\mathbf{m})=Nf,\;\nabla H(\mathbf{m})=x\right]
				=\;\Sigma_{A,X}\;\Sigma_X^{-1}\;\binom{Nf}{x_\parallel},
			\end{equation}
			\begin{equation}
				\mathrm{Var}\!\left(A\;\middle|\;H(\mathbf{m})=Nf,\;\nabla H(\mathbf{m})=x\right)
				=\;\mathrm{Var}(A)\;-\;\Sigma_{A,X}\;\Sigma_X^{-1}\;\Sigma_{A,X}^{\!\top}.
			\end{equation}

			\item \textup{(Joint structure.)}
			Conditionally on $\bigl(H(\mathbf{m})=Nf,\nabla H(\mathbf{m})=x\bigr)$, the triple $(A,B,C)$ is jointly Gaussian.
			Moreover, $C$ is independent of $(A,B)$, and $A$ and $B$ are conditionally independent as well (so $(A,B,C)$ are conditionally independent given $(H(\mathbf{m}),\nabla H(\mathbf{m}))$).
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:57:07.298981+00:00","domain":"probability theory","id":"claim_9f67b7e0b62b9e7989b3d18080c65af0872f747f6a9cfc0db488883c347e1931","kind":"concept","schema_version":1,"statement":"[Theorem 8 (Main theorem) of arXiv:2606.23383, 'Near-Lipschitz stability of the Kim--Milman flow map'] Suppose $\mu$ satisfies \eqref{theta} and $\nu \in \cP_2(\R^d)$ with $\mathsf m_2(\mu),\mathsf m_2(\nu) \leq M$. In addition, let $\mathsf C_\mu \geq 0$ be such that for all $0\leq s\leq t$, it holds that
    \begin{align}
        \int_s^t \theta_u \dd u \leq \mathsf C_\mu\,.
    \end{align}
    Then,
    \begin{align*}
        \|\mathsf T^{\mu} - \mathsf T^{\nu}\|_{L^2(\gamma)} \leq
        W_2(\mu,\nu)\exp(3\mathsf C_\mu) \log\Bigl[e^2\max\Bigl\{1,\, \frac{4M^2 + 8d}{W_2^2(\mu,\nu)\exp(6\mathsf C_\mu)}\Bigr\}\Bigr]\,.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:37.363045+00:00","domain":"probability theory","id":"claim_9f706107082de9d8bb51f0a774e5821d6274e3fc149093c6196c771b0daaa9dd","kind":"theorem","schema_version":1,"statement":"[Corollary 7 of arXiv:2606.18047, 'Analysis of the asymmetric shelf shuffle'] Fix $m\geq 1$, $p\in (0, 1)$, and $u\in (0, 1)$.  
\begin{enumerate}
\item Let $N$ be geometrically distributed by
\[
\mathbb{P}(N=n)=(1-u)u^n,
\qquad n\ge 0\;,
\]
and, conditional on $N=n$, let $\pi$ have the law $\nu^{(p)}_{n,m}$. Then, every finite subcollection of $N_1,N_2,\ldots $ is independent and the probability generating function of $N_i$ is
\begin{equation}
G^{(m,p)}_{i,u}(x):=\E_{\pi}[x^{N_i}]=\exp\left\{\sum_{r\ge 1}\frac{x^r-1}{ir}B^{(m,p)}_{i,r}u^{ir}\right\}.

\end{equation}

\item Fix $i\geq 1$, and let $\pi_n\sim \nu^{(p)}_{n,m}$.  Then, for every finite set $I\subseteq\mathbb{N}$, the random variables $\{N_i(\pi_n):i\in I\}$ converge jointly to independent random variables with marginal pgfs $G^{(m,p)}_{i, 1}$. 

\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:52:57.739696+00:00","domain":"probability theory","id":"claim_9f71056ee9a97aa99bd2bf854352ebc186474c73789112e0e6bd93f0ee66f0ba","kind":"concept","schema_version":1,"statement":"[Corollary 46 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Assume \eqref{eq:affine linear}.
Let $\lambda\in\mathbb{R}$ and let $\mathbf{u}^1=(u^1_{\mfl})_{\mfl\in\mfL_+}$, $\mathbf{u}^2=(u^2_{\mfl})_{\mfl\in\mfL_+}$ be the spatially periodic solutions of the systems 
\begin{align*}
   (\partial_t - \mathcal{L}_\mfl)u_\mfl^i = \sum_{\mft \in \mathfrak{L}_- \sqcup \{ \mathbf{0} \}} F_\mfl^\mft (\mathbf{u}^i) \xi_\mft^i+\sum_{\tau\in\mcT_-}c^i(\tau)\Upsilon_{\mfl}[\tau](\mathbf{u}^i), \qquad \mfl \in \mathfrak{L}_+,
\end{align*}
where the following are assumed:
\begin{itemize}
\item The initial conditions $\psi^i_\mfl$ satisfy $\psi^1_\mfl=\psi^2_\mfl$ for $\mfl\in\mfL_+^{\inh}$ and $\lambda\psi^1_\mfl=\psi^2_\mfl$ for $\mfl\in\mfL_+^{\hom}$;
\item The set $\mcT_-$ is finite and the prefactors $c^i:\mcT_-\to\mathbb{R}$ satisfy $c^2(\tau)=\lambda^{[\tau]}c^1(\tau)$;
\item $\xi^i_{\mft}$ are smooth functions that satisfy $\xi^1_{\mft}=\xi^2_\mft$ for $\mft\in\hat\mfL_-^{1}$ and $\lambda \xi^1_{\mft}=\xi^2_\mft$ for $\mft\in\mfL_-^{0}$.
\end{itemize}
Then $u^2_{\mfl}=\lambda u^1_{\mfl}$ for all $\mfl\in\mfL_+^{\hom}$ on their common interval of existence. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:36:31.234083+00:00","domain":"probability theory","id":"claim_9f7641866d297db479ae19726b7365f5c2fb4ca2b870be1fcad11e0d12435454","kind":"theorem","schema_version":1,"statement":"[Proposition 12 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let \(f\colon\mcalY\to\mcalX\) be a \(B\mcalG\)-torsor for a flat affine group scheme \(\mcalG\) over an fpqc stack \(\mcalX\).
  Let \(u\colon V\to\mcalX\) be an fpqc cover such that $V$ is a small disjoint union of affine schemes and
  \[
  \mcalY \times_{\mcalX} V \simeq B_V\mcalG_V
  \]
  over $V$.
  We consider the pullback square
  \begin{equation*}
    \begin{tikzcd}
      \mcalY_V \arrow[r,"v"] \arrow[d,"f_V"'] & \mcalY \arrow[d,"f"] \\
      V \arrow[r,"u"'] & \mcalX.
    \end{tikzcd}
  \end{equation*}
  For $\mcalF \in \mcalD^+_{\qcoh}(\mcalY)$, the base change morphism
    \begin{equation}

      \BC_{f, u}(\mcalF) \colon Lu^*Rf_*\mcalF\to R(f_V)_*Lv^*\mcalF
    \end{equation}
    is an equivalence in \(\mcalD_{\qcoh}(V)\).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:35:19.878033+00:00","domain":"probability theory","id":"claim_9f83575ca985ff02373d0baaaf15cfc9a2e5642b895d46a413b5a04d9811d88a","kind":"theorem","schema_version":1,"statement":"[Prop hil-equi of arXiv:2608.27939, 'Entropy and domination for quasi-Hitchin representations'] Let $\rho_0:\pi_1S\to\mathrm{PSL}_n(\mathbb{R})$ be a Hitchin representation and let
$\psi^H_t$ be its Hilbert flow.  Then $\psi^H_t$ has a unique measure of
maximal entropy, the Bowen-Margulis measure $\widetilde m_H$, with full support, such that 
\begin{equation}
  \frac{1}{\lvert\mathcal S_0(L)\rvert}
  \sum_{\gamma\in\mathcal S_0(L)}
  \widetilde{\mathcal L}_\gamma
  \xrightarrow{\;\ast\;}
  \widetilde m_H
\end{equation}
as $L \to \infty$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:41:19.335081+00:00","domain":"probability theory","id":"claim_9fbbbf6a64a9d14270aab9d3b9be40f4f56b904a740b8d580af7966cf8314965","kind":"concept","schema_version":1,"statement":"[Proposition prop subsequential limit boundary of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] There exists a subsequence of $(\kappa_n)_{n\ge 0}$, again denoted by $(\kappa_n)_{n\ge 0}$, such that jointly with~(equation eq cv subsequence of the paper) and~(equation eq cv Hausdorff balls of the paper), we have the joint convergence in law:
	\begin{equation}
		\begin{pmatrix}[1.3]
			(\SCL^{\kappa_n}(x))_{x \in \BD_\BQ} \\
			({\ka_{\kappa_n}^{-1}}D^{\kappa_n}(\SCL^{\kappa_n}(x), \SCL^{\kappa_n}(y)))_{x,y \in \BD_\BQ} \\
			({\ka_{\kappa_n}^{-1}}D^{\kappa_n}(\alpha, \SCL^{\kappa_n}(y)))_{y \in \BD_\BQ, \alpha \in \SCS'} 
			\\
			((\SCB^{\kappa_n }_{\ka_{\kappa_n} t}(\SCL^{\kappa_n}(x)))_{t \in \BQ_{\ge 0}})_{ x\in \BD_\BQ}
			\\
			((\SCB^{\kappa_n }_{\ka_{\kappa_n} t}(\alpha))_{t \in \BQ_{\ge 0}})_{ \alpha \in \SCS'}
			\\
			(K^{\kappa_n}_{\SCL^{\kappa_n}(x), \SCL^{\kappa_n}(y)})_{x, y \in \BD_\BQ}\\
			{(K^{\kappa_n}_{\alpha, \SCL^{\kappa_n}(x)})_{\alpha \in \SCS', x \in \BD_{\BQ}}} \\
			{(K^{\kappa_n}_{\alpha, \beta})_{\alpha, \beta \in \SCS'}} 
		\end{pmatrix}
		\mathop{\longrightarrow}\limits_{n\to \infty}^{(\mathrm{d})}
		\begin{pmatrix}[1.4]
			(\SCL(x))_{x \in \BD_\BQ} \\
			(D (\SCL(x), \SCL(y)))_{x,y \in \BD_\BQ}
			\\
			(D (\alpha, \SCL(y)))_{y \in \BD_\BQ, \alpha \in \SCS'}
			\\
			((\SCB_{t}(\SCL(x)))_{t \in \BQ_{\ge 0}})_{x\in \BD_\BQ}
			\\
			((\SCB_{t}(\alpha))_{t \in \BQ_{\ge 0}})_{\alpha \in \SCS'}
			\\
			(\widetilde{K}_{\SCL(x), \SCL(y)})_{x, y \in \BD_\BQ }\\
			{(\widetilde{K}_{\alpha, \SCL(x)})_{\alpha \in \SCS', x \in \BD_\BQ}}\\
			{(\widetilde{K}_{\alpha, \beta})_{\alpha, \beta \in \SCS'}}
		\end{pmatrix}
	\end{equation}
	where the loops $(\SCL(x))_{x \in \BD_\BQ} $ are the loops of a $\CLE_4$ $\Gamma$ in $\BD$,  $D$ is a random metric on $\Gamma$, and the $\widetilde{K}_{\SCL(x), \SCL(y)}$'s, $\widetilde{K}_{\alpha, \SCL(x)}$'s, $\widetilde{K}_{\alpha, \beta}$'s, $\SCB_{t}(\SCL(x))$ and $\SCB_t(\alpha)$ are random compact subsets of $\overline{\BD}$. The above convergence holds for the product topology and the compact sets converge in the Hausdorff topology. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:16:46.718977+00:00","domain":"probability theory","id":"claim_9fbeb913f000874d06580ecda9c7f3b0e0cd03e2324e80f01d9f515444fba62c","kind":"concept","schema_version":1,"statement":"[Theorem BRW.lowdim of arXiv:2411.19145, 'On the intersection of critical percolation clusters and other tree-like random graphs'] One has 
\begin{equation*}
\mathbb P(|\mathcal R_c \cap \widetilde {\mathcal R}_c|>t) \asymp     
\left\{
\begin{array}{ll}
t^{-4/d} & \text{if }d\in \{1,2,3\} \\
t^{-1}\cdot (\log t)^{-2} & \text{if }d=4 \\
t^{-\frac 4{8-d}} & \text{if }d\in \{5,6,7\}. 
\end{array}
\right. 
\end{equation*}
Furthermore, if $d=8$, there exist positive constants $c_1$ and $c_2$, such that for any $t>1$, 
\begin{equation}
\exp(-c_1\sqrt t) \le \mathbb P(|\mathcal R_c \cap \widetilde {\mathcal R}_c|>t) 
\le \exp\big(-c_2\cdot t^{1/3}\big). \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:25:44.583695+00:00","domain":"probability theory","id":"claim_9fdee65e5b5371cea274ecfb570ff1d146b31e78da1d1d33c1433b5ad98d4ed2","kind":"concept","schema_version":1,"statement":"[Thm pointstationary of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Let $\mathsf{P}\in \mathcal P_{s,1}(\Gamma)$. Then its Palm measure $\mathsf{P}^0$ is stationary w.r.t.\ the shifts $\theta_{\tau_i}$, $i\in \IZ$, defined  for $\xi\in \Gamma_0$ by 
    \begin{align*}
        \theta_{\tau_i}(\xi):=\theta_{\tau_i(\xi)}\xi,
    \end{align*}
    where $\xi=\{\cdots,\tau_{-1}(\xi),0=\tau_0(\xi),\tau_1(\xi),\cdots\}$ is the  enumeration of $\xi$ defined in (equation eq:numbering of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:52:57.732087+00:00","domain":"probability theory","id":"claim_a0108d1c858f4afcd81f8b41e6622333b7320b67e192f6b906f44bc3e0895778","kind":"lemma","schema_version":1,"statement":"[Lemma 5 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Suppose that $(\Pi, \Gamma)$ is a smooth model, that $|\tau|_\fs < - 2$, that $\Gamma \tau = \tau$ for all $\Gamma \in \mcG$. Suppose that we postulate that $\mcR \mathbf{1}_\pm \tau = \mathbf{1}_\pm \Pi_z \tau \in C^{|\tau|_\fs}$. Then we have that 
	\begin{align*}
		\mathbf{1}_+ \mcP_\gamma \mathbf{1}_+ \tau = \mathbf{1}_+ \mcI \tau +  \mcV_\tau
	\end{align*}
	where $\mcV_\tau \in \mcD^{\gamma, |\tau|_\fs + 2}$ is defined by
	\begin{align*}
		\mcV_\tau = \sum_{|k|_\fs < \gamma} \frac{X^k}{k!} \mathbf{1}_+ \left (  D^k R \ast \mathcal{R} \mathbf{1}_+ \tau -D^k K \ast \mathcal{R} \mathbf{1}_- \tau \right ).
	\end{align*}
	Furthermore, $\mcV_\tau$ depends continuously on $\mathbf{1}_\pm \Pi_z \tau \in C^{|\tau|_\fs}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:19:56.668990+00:00","domain":"probability theory","id":"claim_a02475aac73afd9de0468a7c52d7808f5cc70de3b88afb30ee2da6695c121b2e","kind":"definition","schema_version":1,"statement":"[Definition 7 of arXiv:2608.30875, 'A Decomposition Theorem for Topological Semi-small Maps'] Let $Y = \bigsqcup_{\eta} W_{\eta}$ and $R = \bigsqcup_{\alpha} S_{\alpha}$ be topologically stratified spaces such that $R \subseteq Y$. An inclusion $R \hookrightarrow Y$ is said to be \textbf{locally flat at a point $r \in R$} if the following holds. Suppose $r \in W_{\eta} \cap S_{\alpha}$ and $\dim(W_{\eta}) \leq \dim(S_{\alpha})$. Then there exist distinguished neighborhoods $U \subset R$ and $U^{\prime} \subset Y$ of $r$ such that $U \subset U^{\prime}$ and the topological pair $(U \cap S_{\alpha},\, U^{\prime} \cap W_{\eta})$ is homeomorphic to the topological pair $(\mathbb{R}^{\dim S_{\alpha}},\, \mathbb{R}^{\dim W_{\eta}})$ with the standard inclusion $\mathbb{R}^{\dim W_{\eta}} \hookrightarrow \mathbb{R}^{\dim S_{\alpha}}$. In other words, there exist homeomorphisms $U^{\prime} \cap W_{\eta} \longrightarrow \mathbb{R}^{\dim W_{\eta}}$ and $U \cap S_{\alpha} \longrightarrow \mathbb{R}^{\dim S_{\alpha}} $ making the following diagram commute:
	\begin{align*}		
		\begin{tikzcd}[ampersand replacement=\&]
			U^{\prime} \cap W_{\eta} \arrow[r,  hookrightarrow] \arrow[d] \& U \cap S_{\alpha} \arrow[d]   \\
			\mathbb{R}^{\dim W_{\eta}} \arrow[r, hookrightarrow]  \& \mathbb{R}^{\dim S_{\alpha} }  
		\end{tikzcd}.
	\end{align*}
	The inclusion $R \hookrightarrow Y$ is locally flat if it is locally flat at each point $r \in R$. If $\dim(W_{\eta}) \geq \dim(S_{\alpha})$, we define local flatness similarly.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.286948+00:00","domain":"probability theory","id":"claim_a027358a781ac7b4eb5578d3cfbd1d4b4665f33a57ce9f275d2d1c13baa27644","kind":"lemma","schema_version":1,"statement":"[Lemma martingales of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $X_t$ denote the Auffinger--Chen process (equation eq:AuffingerChen of the paper). Then:
		\begin{enumerate}[label=(\roman*)]
			\item Define
			\begin{equation*}
				Y_t:=\Phi_\zeta(t,X_t)-\Phi_\zeta(0,X_0)-\frac12\int_0^t \xi''(s)\,\zeta([0,s])(\partial_x\Phi_\zeta(s,X_s))^2\,\mathrm{d} s-\int_0^t \partial_x\Phi_\zeta(s,X_s)\sqrt{\xi''(s)}\,\mathrm{d} B_s .
			\end{equation*}
			Then $\mathrm{d} Y_t=0$, i.e.\ $Y_t$ is a.s.\ constant in $t$.

			\item The process $\bigl(\partial_x\Phi_\zeta(t,X_t)\bigr)_{t\in[0,1]}$ is a martingale.

			\item The second derivative along the optimal trajectory satisfies
			\begin{equation*}
				\mathrm{d}\bigl(\partial_{xx}\Phi_\zeta(t,X_t)\bigr)
				=-\zeta([0,t])\,\xi''(t)\bigl(\partial_{xx}\Phi_\zeta(t,X_t)\bigr)^2\,\mathrm{d} t
				+\sqrt{\xi''(t)}\,\partial_{xxx}\Phi_\zeta(t,X_t)\,\mathrm{d} B_t.
			\end{equation*}

			\item Moreover,
			\begin{equation*}
				\mathrm{d}\bigl(\partial_x\Phi_\zeta(t,X_t)\bigr)^2
				=2\sqrt{\xi''(t)}\,\partial_x\Phi_\zeta(t,X_t)\,\partial_{xx}\Phi_\zeta(t,X_t)\,\mathrm{d} B_t
				+\xi''(t)\bigl(\partial_{xx}\Phi_\zeta(t,X_t)\bigr)^2\,\mathrm{d} t .
			\end{equation*}
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:38:04.510141+00:00","domain":"probability theory","id":"claim_a0324d165ce7339b3f1b2925929ed3d271b3e891f57172691203e5a379725dde","kind":"concept","schema_version":1,"statement":"[Lemma lem:wendel of arXiv:2607.17764, 'Non-vanishing uniqueness threshold for\\hyperbolic Poisson-Voronoi percolation\\in dimensi'] Let $X_1,\dots,X_n$ be i.i.d.~from some atom-free, rotationally invariant distribution. Then

