{"assumptions":[],"created_at":"2026-10-27T19:48:47.285375+00:00","domain":"probability theory","id":"claim_a2725cb1276d64eb8f5ce1b4d5baea6acb97a6ede9e0ddfc31b8a46bdb006a63","kind":"concept","schema_version":1,"statement":"[Conjecture conj:annealed of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Define
		\begin{equation}
			\Lambda(\theta)=\theta\inf_{\zeta:\zeta(\{0\})=\theta}\mathcal{P}\mathrm{arisi}(\zeta).
		\end{equation}
		There exists an open subset $D\subset\mathbb{R}$ containing $[\inf_\zeta \mathcal{P}\mathrm{arisi}(\zeta),+\infty)$ such that for every $f\in D$,
		\begin{equation*}
			\lim_{\varepsilon\to 0}\lim_{N\to\infty}
			\frac{1}{N}\log\mathbb{E}\bigl[\mathcal{N}_\varepsilon(f)\bigr]=-\Lambda^*(f)=\inf_\theta \bigl(\Lambda(\theta)-\theta f\bigr).
