\left( \sup_{0 \le t \le T} \|(g_{\text{{\tiny $\delta$}}} (\tilde{v}))(t)\|_{L^2(\Omega)} \right) \right\} \le \delta C_9 R^{\frac{1}{2}}.
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:57:51.766360+00:00","domain":"probability theory","id":"claim_a8de688ad2a1a03cbf025d687545d6275c1b16b0c8acd38701b18c39dee77106","kind":"lemma","schema_version":1,"statement":"[Lemma 25 (Uniform bounded resolvent on large dilations) of arXiv:2608.30211, '2608.30211'] Assume that $\Omega$ is bounded and uniformly $C^{2,\gamma}$, with nonempty
