{"assumptions":[],"created_at":"2026-10-28T00:37:20.362541+00:00","domain":"probability theory","id":"claim_ab65526c47a1ce9b87bfa73f8b09fb61f8074525b09038fd8990c8d5a498f27d","kind":"definition","schema_version":1,"statement":"[Definition D:4P of arXiv:2411.13257, '\titlefont \vspace{-5ex} Inference by Multiple Identical Observers'] {\rm We define the following Principles. 

\smallskip\noindent{\bf Principle of  null sets} (PN). \\
(a)  If $F \in {{\mathcal F}_W}$ and ${\mathbb P}(F)=0$ then ${P_A}(F)=0$. \\
(b) $P_A(S \in {\mathcal X}) =1$. (It follows that $ P_A({\mathcal X} = \emptyset) = 0$.)

 \smallskip\noindent {\bf Principle of Indifference} (PI).  For $x \in K$, $B \subset K$, $B \neq \emptyset$, with 
$P_A( {\mathcal X} = B) >0$,
 \begin{equation}  
   {P_A} ( S=x | \; {\mathcal X}=B ) = |B|^{-1} 1_B(x). 
 \end{equation}

\smallskip\noindent {\bf Principle of Equivalent Information} (PEI). If $F \in {{\mathcal F}_W}$ and $P_A(S=x)>0$ then 
\begin{equation} 
  {P_A} ( F  | S=x ) = {\mathbb P} (F | x \in {\mathcal X} ). 
\end{equation}

\smallskip\noindent{\bf Principal Principle} (PP).  For $F \in {\mathcal F}_W$ we have
 \begin{equation} 
   {P_A}(F) = {\mathbb P}(F| {\mathcal X} \neq \emptyset).
 \end{equation}

}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:01:39.421359+00:00","domain":"probability theory","id":"claim_ab6c09e6641ddefc0be08ba7877151f4b7fc6a31852c14ce4970612a95b6b46c","kind":"definition","schema_version":1,"statement":"[Definition traffic freeness of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] We say that $\mathbf{A}_{N}^{(1)},\cdots,\mathbf{A}_{N}^{(L)}$ are \emph{asymptotically traffic independent} whenever $\mathbf{A}_{N}:=\mathbf{A}_{N}^{(1)}\cup\cdots\cup\mathbf{A}_{N}^{(L)}$ converges in traffic distribution and for any *-test graph $T=(V,E,\gamma,\epsilon)$,
        \begin{equation}
            \tau_{N}\left(T(\mathbf{A}_{1}^{(N)},\cdots,\mathbf{A}_{L}^{(N)})\right)\underset{N\rightarrow\infty}{\longrightarrow}\sum_{\substack{\pi\in\mathcal{P}(V) \\ \mathrm{s.t.}\mathcal{GCC}(T^{\pi}) \\ \text{is a tree}}}\prod_{S\in\mathcal{CC}(T^{\pi})}\lim_{N\rightarrow\infty}\tau_{N}^{0}\left(S(\mathbf{A}_{N}^{(\ell(S))})\right),
        \end{equation}
    where $\ell(S)$ is the index of the family of the labels of the colored component $S$. Since the injective traces in the product can also be written in terms of (non-injective) traces, asymptotic traffic independence entirely characterizes the limiting traffic distribution of $\mathbf{A}_{N}=\mathbf{A}_{N}^{(1)}\cup\cdots\cup\mathbf{A}_{N}^{(L)}$ in terms of the traffic distributions of the $\mathbf{A}_{N}^{(l)}$'s.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:02:08.116577+00:00","domain":"probability theory","id":"claim_ab719bbff76ab96cdd58eb12a272791bc6d9a46c6d3140276ade301116f537f0","kind":"concept","schema_version":1,"statement":"[Proposition 5 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] Assume $k>2$.  For all sufficiently small $\eps>0$, the form $\omega_\eps$ defined by \eqref{gt:eq:approximate-metric} extends to a smooth K\"ahler metric on $\widetilde X$, and
\begin{equation}
  [\omega_\eps]=\pi^*[\omega]-\eps^2[E].
\end{equation}
Moreover:
\begin{enumerate}[label=\textup{(\roman*)}]
\item on the exterior region, \(\omega_\eps=\omega\);
\item on the outer annulus, for every fixed $j\ge0$,
\begin{equation}
  \abs{\nabla^j\left[
  \eps^2\gamma_2\psi_k(\eps^{-2}d^2)
  \right]}
  \le C_j\eps^{2k-2}r_\eps^{4-2k-j};
\end{equation}
\item on the inner annulus, potentials for $\eps^{-2}\omega_\eps$ and $\omega_k$ in the rescaled coordinates are respectively
\begin{align*}
  F&=|Z|^2+|W|^2
      +\eps^{-2}\Phi(\eps Z,\eps W)
      +\psi_k(\eps^{-2}d^2),\\
  F_{\mathrm{prod}}&=|Z|^2+|W|^2+\psi_k(|Z|^2),
\end{align*}
and, on the rescaled coordinate balls specified above,
\begin{equation}
  \abs{\nabla_{Z,W}^j(F-F_{\mathrm{prod}})}
  \le C_j\eps^{j-2}d^{3-j}
  \qquad(2\le j\le6).
\end{equation}
In particular, $\eps^{-2}\omega_\eps$ is uniformly equivalent to $\omega_k$ there;
\item on the blowup region, in the coordinates
\eqref{gt:eq:blowup-coordinates},
\[
  \eps^{-2}\omega_\eps=\omega_k+O(\eps)
\]
in $C^\ell$ on compact subsets of each blowup chart, for every fixed $\ell$.  In particular, $\eps^{-2}\omega_\eps$ converges locally smoothly to $\omega_k$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.340639+00:00","domain":"probability theory","id":"claim_ab7236edd0383819aebe5baed95c562e13d808876b71f7ac4b7cba38e2424c00","kind":"lemma","schema_version":1,"statement":"[Lemma lem:lyap:symLemma of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Let $(\mu,\gamma, \mathbf{X})$ be a solution to the $\kappa$-MLFE{} on $[0, T]$ with potentials $(U, W)$ and initial condition $\lambda \in \mathcal{Q}_{\kappa, d}$. Let $f : \ensuremath{\mathbb{R}}^d \times \ensuremath{\mathbb{R}}^d \rightarrow \ensuremath{\mathbb{R}}^d$ be a measurable function such that for almost every $s \in \ensuremath{\mathbb{R}}_+$ we have
\begin{equation}
    \mathbb E\Big[\big|f\big(X_0(s), X_v(s)\big)\big|^2 + \big|f\big(X_v(s), X_0(s)\big)\big|^2 \Big] < \infty.

\end{equation}
Then the following properties hold:
\begin{enumerate}
    \item For $u \in \{0, \ldots, \kappa\}$, let $\bar{u} = 0$ when $u = 0$ and $\bar{u} = 1$ otherwise. Given any $v \in \{1, \ldots, \kappa\}$ and $u \in \{0, v\}$, for almost every $s \in \ensuremath{\mathbb{R}}_+$ we have 
    \begin{equation}
        \mathbb E\Big[f\big(X_0(s), X_v(s)\big) \nabla_{u} \log \mu_s\big(\mathbf{X}(s)\big)\Big] = \mathbb E\Big[f\big(X_0(s), X_v(s)\big) \nabla_{\bar{u}} \log \bar{\mu}_s\big(X_0(s), X_v(s)\big)\Big].

    \end{equation}
    \item For all $v \in \{1, \ldots, \kappa\}$ and $s \in \ensuremath{\mathbb{R}}_+$ we have
    \begin{equation}
        \mathbb E\Big[f\big(X_0(s), X_v(s)\big) \nabla_{0} \log \bar{\mu}_s\big(X_0(s), X_v(s)\big)\Big] = \mathbb E\Big[f\big(X_v(s), X_0(s)\big) \nabla_{1} \log \bar{\mu}_s\big(X_0(s), X_v(s)\big)\Big].

    \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:09.040030+00:00","domain":"probability theory","id":"claim_ab92c6fb19a51be2923b9ff13f6f8ce79f795e6ded55abdba8d62602126febe2","kind":"theorem","schema_version":1,"statement":"[Theorem 4 of arXiv:2606.26619, 'Ergodicity of stochastic reaction-diffusion equations on unbounded domains driven by space'] Let $u$ be the solution of equation (\ref{3.1}) with initial value $f$. 
