    H^i_{(p)}(X,\Omega^j_{X/W(k)} \otimes L^{-1})=0 & \quad (i+j<\dim X), \\
    H^i(X_{\F_p}, \Omega^j_{X_{\F_p}} \otimes L_{\F_p}^{-1}) = 0 & \quad (i + j < \dim X - 1), \\
