{"assumptions":[],"created_at":"2026-10-27T11:07:35.023501+00:00","domain":"probability theory","id":"claim_b80e3e4b4be67c918c907e4afe4fcc6db8a30b74f75db9042f9f3b4f9fb79101","kind":"definition","schema_version":1,"statement":"[Defn 7 (Cut time function) of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let $\phi\in \text{\rm SCL}(M)$, $H:T^*M\to\R$ be a Tonelli Hamiltonian, and $u$ be the viscosity solution of Cauchy problem \eqref{eq:HJephi pre}. We define the \emph{cut time function} of $\phi$ as (see also \cite{Cannarsa_Cheng_Hong2025})
	\begin{align*}
		\tau_{\phi,H}(x) = \sup\bigl\{\ t\geqslant0: \exists\  \text{a $(u,H)$-calibrated curve}\ \gamma:[0,t]\to M\ \text{with}\ \gamma(0) = x\ \bigr\},\quad x\in M,
	\end{align*}
	 and the sup-level set of $\tau_{\phi,H}$ as
	\begin{align*}
		E(\phi,H,t)=\{x\in M: \tau_{\phi,H}(x)\geqslant t\ \},\qquad t\geqslant0.\ 
	\end{align*}
	We then introduce the sets
	\begin{align*}
		\reg(\phi,H)=\bigl\{\ x\in M:\tau_{\phi,H}(x)>0\ \bigr\}, \quad
		\cut(\phi,H)=\bigl\{\ x\in M:\tau_{\phi,H}(x)=0\ \bigr\},
	\end{align*} 
	which are called the set of \emph{regular points} and \emph{cut points} for the pair $(\phi,H)$, respectively.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.286692+00:00","domain":"probability theory","id":"claim_b80f12a151486d86c82d2e6b1a947b2281d67e3aa780d947b6da27660f30a46c","kind":"concept","schema_version":1,"statement":"[Lemma prob0 replica of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $\varepsilon>0$. Let $\zeta$ be a probability measure on $[0,1]$ with prefix $\{0,q_1,\ldots,q_n\}$ where $0<q_1<\ldots<q_n<1$. Let us emphasize that $\mathrm{supp}(\zeta)\cap (q_n,1]$ can be nonempty. For every $j\in [n-1]$, set $\Delta_j:=-\zeta(\{q_j\})$ and set $\Delta_n=\zeta([0,q_n))=\zeta([0,q_{n-1}])$. Let $f_1,\ldots,f_n\in \mathbb{R}$. For every $\mathbf{m}\in [-1,1]^N$, denote $Z(\mathbf{m}):=(\nabla F_{\mathrm{TAP},\zeta}(\mathbf{m}),F_{\mathrm{TAP},\zeta}(\mathbf{m}))$.


		Let $(\mathbf{m}^{(1)},\ldots,\mathbf{m}^{(n)})\in \mathrm{SUSY}_n(\zeta,\varepsilon)$ where $\mathrm{SUSY}_n(\zeta,\varepsilon)$ is as in Definition (def:susyreplicas of the paper). Moreover, assume that for every $k\in [n-1]$, 
		\begin{multline}
			\sum_{i=1}^N (h_\zeta(q_k,m_i^{(k)})-\partial_m h_\zeta(q_k,m_i^{(k)})m_i^{(k)})+\frac{1}{2}N\int_0^1 t\xi''(t)\zeta([0,t])\mathrm{d} t+\frac{1}{2}N\int_{0}^{q_k} t\xi''(t)\zeta([0,t]) \mathrm{d} t\\=-Nf_k+O(N\varepsilon^{1/2}).
		\end{multline}
		For every $k\in [n]$, let $\mathrm{Skel}_k:=(Z(\mathbf{m}^{(1)}),\ldots,Z(\mathbf{m}^{(k)}))$.



		Then, 
		\begin{align}
			& \log \varphi_{\mathrm{Skel}_n\mid \mathrm{Skel}_{n-1}}(0,Nf_1,\ldots,0,Nf_n\mid 0,Nf_1,\ldots,0,Nf_{n-1})\\ \notag
			&\leq -\frac{1}{2}N\xi''(q_n)\left(\int_{q_n}^1 \zeta([0,t])\mathrm{d} t\right)^2\\ \notag
			&-\frac{1}{2(\xi'(q_n)-\xi'(q_{n-1}))}\left\Vert \partial_m h_\zeta(q_n,\mathbf{m}^{(n)})-\partial_m h_\zeta(q_{n-1},\mathbf{m}^{(n-1)})\right\Vert^2\\ \notag
			& -\Delta_n\sum_{i=1}^N \bigl(h_\zeta(q_n,m_i^{(n)})-\partial_m h_\zeta(q_n,m_i^{(n)})m_i^{(n)}\bigr)\\ \notag
			&\quad +\Delta_n \sum_{i=1}^N \bigl(h_\zeta(q_{n-1},m_i^{(n-1)})- \partial_m h_\zeta(q_{n-1},m_i^{(n-1)})m_i^{(n-1)}\bigr)\\ \notag
			&- N\Delta_n(f_n\!-\!f_{n-1}) -\tfrac{N}{2} \log\bigl(2\pi (\xi'(q_n)\!-\!\xi'(q_{n-1}))\bigr) +O(N\varepsilon^{1/2}).
		\end{align}


		Suppose in addition that 
		\begin{multline}
			\sum_{i=1}^N \bigl(h_\zeta(q_n,m_i^{(n)})-\partial_m h_\zeta(q_n,m_i^{(n)})m_i^{(n)}\bigr)\\
			+\tfrac{1}{2}N\!\int_0^1 t\xi''(t)\zeta([0,t])\mathrm{d} t+\tfrac{1}{2}N \!\int_{0}^{q_n} t\xi''(t)\zeta([0,t]) \mathrm{d} t=-Nf_n+O(N\varepsilon^{1/2}).
		\end{multline}
		Then the inequality (equation eq:prob ineq of the paper) is an equality. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:12:09.057353+00:00","domain":"probability theory","id":"claim_b8326804445de46eba35010f4e4eeb00e98a911d3ee3c46d6ea3587009a9fc5b","kind":"theorem","schema_version":1,"statement":"[Proposition prop:exp-euler-gaussian of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Let $\kappa>1$ and let $h,\gamma>0$. For
$U_\lambda(x)=\lambda x^2/2$ on $\mathbb R$, let $M_\lambda$ be the
matrix in (equation eq:exp-euler-matrix of the paper). If $M_\kappa$ is not Schur
stable, then the left-endpoint exponential integrator for
$U_\kappa$ has no invariant probability law. If $M_\kappa$ is
Schur stable, then $M_\lambda$ is Schur stable for every
$\lambda\in[1,\kappa]$, and
\begin{equation}
 \rho(M_1)\ge1-\frac{64}{\kappa}.
\end{equation}
In this case, the chain for $U_1$ has a unique invariant law
$\pi_1$. Let $P$ denote the transition kernel of the chain for
$U_1$. For every initial state $y\in\mathbb R^2$,
\begin{equation}
 \limsup_{n\to\infty}
 \lVert \delta_yP^n-\pi_1\rVert_{\mathrm{TV}}^{1/n}
 \le\rho(M_1),
\end{equation}
and the limit exists and equals $\rho(M_1)$ for a suitable $y$.
Moreover, there are initial states $y,\widetilde y\in\mathbb R^2$ such
that
\begin{equation}
 \lim_{n\to\infty}
 \norm{\delta_yP^n-\delta_{\widetilde y}P^n}_{\mathrm{TV}}^{1/n}
 =\rho(M_1)\ge1-\frac{64}{\kappa}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:04:07.033879+00:00","domain":"probability theory","id":"claim_b8401dd9868de943eebb96fbce87d97f2e4c7cd5fc261650de6d6a57c7396c6a","kind":"theorem","schema_version":1,"statement":"[Proposition prop:siteperc_dom_ZIM of arXiv:2607.29409, 'The Zombie Infection Model'] Let $G=(V,E)$ be a graph of bounded degree.
