    \item     For $s> 0$ the exponential mixing rate without diffusion is of order $1\land s$, that is, there exists a constant $C>0$ such that
    \begin{equation}
        C^{-1} (1\wedge s) \leq \gamma_s \leq C (1\wedge s), \quad \forall\, s>0.
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:06.330085+00:00","domain":"probability theory","id":"claim_ba8ac0d91e39cfe4d8396c6641305e370bac01f22d9f676611af01911a949e56","kind":"concept","schema_version":1,"statement":"[Lemma 19 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Let $H\in\left(0,1\right)$ and $\left(\psi_t^{(1)}\right)_{t\geq 0}$ be a solution to the first equation in \eqref{eq:fast system simplified hopf 2} with $||\bm{\sigma}_1||^2\neq 0$. Consider $\alpha=\alpha(\lambda)\in\C$ such that $\underset{\lambda\to\lambda^*}{\lim} \alpha(\lambda)=\alpha(\lambda^*)\in i \R\setminus\{0\}$. Then, it holds that
\begin{align}
    \left| \frac{\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t+\tau}^{(1)} \right)}{\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t}^{(1)} \right)} - e^{-i \operatorname{Im}(\alpha(\lambda))\tau} \right| = -\operatorname{Re}(\alpha(\lambda)) \tau \Delta(\tau) + \mathcal{O}\left( \operatorname{Re}(\alpha(\lambda))^2 \right) ,
\end{align}
with $\Delta(\tau)\neq 0$ for almost every $\tau \geq 0$. In particular, for almost every $\tau\ge0$, we have that
\begin{align*}
    &\frac{\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t+\tau}^{(1)} \right)}{\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t}^{(1)} \right)}
    = e^{-i \operatorname{Im}(\alpha(\lambda^*))\tau} 
    + \cO \left(\operatorname{Re}(\alpha(\lambda))\right) + \cO\left( \operatorname{Im}(\alpha(\lambda)-\alpha(\lambda^*))\right) .
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:27:08.852965+00:00","domain":"probability theory","id":"claim_bae04a315b9c087d9ff2e4b45576540779b2ac18b423476eccf236e9183d2641","kind":"concept","schema_version":1,"statement":"[Proposition 19 (Hard-Edge Limit) of arXiv:2511.12623, 'The eigenvector bead process'] We have, almost surely,
