{"assumptions":[],"created_at":"2026-10-26T19:27:08.852120+00:00","domain":"probability theory","id":"claim_be5f1b37d1d2b92e6cfa124e7684a09ecca9c63d813d95d006079a29fb4f994a","kind":"concept","schema_version":1,"statement":"[Theorem 8 (Bulk, real Wishart) of arXiv:2511.12623, 'The eigenvector bead process'] We recall Convention~\ref{conv:inverse-stieltjes-branches}. 
Fix $E \in \bigl((1-\sqrt{q})^2,(1+\sqrt{q})^2\bigr)$ and define the anchor index
\[
i_N(E) \;:=\; \min\bigl\{\,k \in \{1,\dots,N\}\ :\ \lambda^{(N)}_{k} \ge E\,T\,\bigr\}.
\]
We recall the notation for the Marčenko–Pastur density $\rho_{\mathrm{MP}}$ (see Equation~\ref{eq:MP-law}).
Then the overlaps satisfy
\begin{equation}
\Omega^{(N)}_{\,i_N(E)+u,\;i_N(E)+v}
\;\mathrel{\underset{N\to\infty}{\overset{d}{\sim}}}\;
\frac{g_v}{\,S_{\mu,\,g^2}^{-1}(h)_u - \mu_v\,}\,
\sqrt{\bigl(S_{\mu,\,g^2}^{-1}\bigr)'(h)_u},
\qquad 
h
\;=\;
-\,\frac{E + q - 1}{2E}
\cdot
\frac{1}{2\pi\rho_{\mathrm{MP}}(E)}\,.
\end{equation}

\noindent
Here $(\mu_u)_{u \in \mathbb{Z}}$ follows the sine\(_1\) point process, 
and $(g_u)_{u \in \mathbb{Z}}$ are i.i.d.\ real Gaussian random variables 
$g_u \sim \mathcal{N}(0,1)$, independent of $(\mu_u)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:52:08.670604+00:00","domain":"probability theory","id":"claim_be9009145ebd4a07e2cc0da2ba8e30bc4a823416305e2939ab85bd1579ef19c2","kind":"concept","schema_version":1,"statement":"[Proposition 24 (Positive-time smoothing and regular restart) of arXiv:2608.30027, 'Under Ricci flow, a 3-torus goes flat'] Fix \(K_0<\infty\).  There are constants
\[
        \beta_{\mathrm{reg}}>0,\qquad C_{\mathrm{reg}}<\infty,
        \qquad \Lambda_{\mathrm{reg}}<\infty,
\]
depending only on \(K_0,N,\sigma\), with the following property.

\medskip
\noindent\textbf{Hypotheses.}
Let \(r(\tau)\), \(1\leq\tau\leq100\), be an invariant Ricci flow satisfying
\begin{equation}
        |\sec_{r(\tau)}|\leq K_0/\tau.
\end{equation}
Let \(q(\tau)\) be a Ricci--DeTurck flow relative to \(r(\tau)\) and assume
\begin{equation}
        \|q-r\|_{X_r^N[1,100]}\leq\beta_{\mathrm{reg}}.
\end{equation}

\medskip
\noindent\textbf{Rescale and average.}
Put
\[
        q^+(1)=100^{-1}q(100),\qquad
        \rho^+=100^{-1}r(100),\qquad
        r^+(1)=\overline{q^+(1)}.
\]

\medskip
\noindent\textbf{Conclusion.}
Then \(r^+(1)\) is Riemannian,
\[
        \BG_N(\rho^+;\Lambda_{\mathrm{reg}}),\qquad
        \BG_N(r^+(1);\Lambda_{\mathrm{reg}}),
\]
and
\begin{equation}
\begin{split}
 &\|q^+(1)-\rho^+\|_{C^{N+5,\sigma}(M,\rho^+)}
 +\|r^+(1)-\rho^+\|_{C^{N+5,\sigma}(M,\rho^+)}\\
 &\qquad\leq C_{\mathrm{reg}}
 \|q-r\|_{C^0(M\times[1,100],r)}.
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

