{"assumptions":[],"created_at":"2026-10-27T21:54:18.302065+00:00","domain":"probability theory","id":"claim_c3e168f0fdd0931167110e566276787178bd8b1a6f8807e50e7c9356a03b8482","kind":"theorem","schema_version":1,"statement":"[Prop strongly-convex-coordinate-gradients of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $ m, d, M \in {\mathbb N} $, $ \mu, B, R \in (0,\infty) $, and let
$\mathcal V\subseteq{\mathbb R}^d$. Let $U$ be an ${\mathbb R}^m$-valued random variable with a
Lebesgue density $g$ satisfying
\bas{
  \|g\|_{L^\infty}\le B,
  \qquad
  \text{and}
  \qquad
  {\mathbb P}\bigl( | U | < R \bigr) = 1 .
}
Let $U_1,\dots,U_M$ be independent copies of $U$, and set
$\mathbf U=(U_1,\dots,U_M)$. Let
$\ell:{\mathbb R}^d\times{\mathbb R}^m\to{\mathbb R}$ be differentiable in its first argument. For
every $ \theta \in \mathcal V $, $ i \in \{ 1, \dots, d \} $, define
\bas{
  \varphi_{\theta,i} \colon {\mathbb R}^m \to {\mathbb R},
\qquad
  \varphi_{\theta,i}( u )
  =
  \frac{\partial\ell}{\partial\theta_i}(\theta,u),
}
and assume that $\varphi_{\theta,i}$ is $\mu$-strongly convex.
For every $ \theta \in \mathcal V $, $ i \in \{ 1, \dots, d \} $, define
\bas{
X_M^{(i)}(\theta,\mathbf U)
=-\frac1M\sum_{r=1}^M
\frac{\partial\ell}{\partial\theta_i}(\theta,U_r).
}
Let $\omega_m$ denote the Lebesgue volume of the Euclidean unit ball in
${\mathbb R}^m$, and set
\bas{
C_m=1+m3^{m-1}
}
and
\bas{
s_0
=\mu\min\left\{
\frac{R^2}{4},
\frac{1}{
16B^2\omega_m^2C_m^2R^{2m-2}}
\right\}.
}
Then the minibatch innovation $(X_M,\mathbf U)$ is $(c_M,q)$-regular on
$\mathcal V$ with
\bas{
c_M=\frac{(1-e^{-1})s_0^2}{2M^2}
\qquad
  \text{and}
\qquad
q=\frac{1-e^{-1}}2.
}
If, in addition, the coordinate derivatives of $\ell$ are uniformly bounded
on $ \mathcal V \times \{ u \in {\mathbb R}^m \colon | u | < R \} $,
then assumption~(equation eq:combined-main-boundedness of the paper) in
(thm:combined-early-late-numerical-time of the paper) is satisfied for $X_M$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:10:05.652207+00:00","domain":"probability theory","id":"claim_c3e3d5ef85b314db4d6768bd6677f9bd276807e8f7b1ece263c706eea36c97a0","kind":"concept","schema_version":1,"statement":"[Theorem 1 (Absorption probability for a random walk) of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] Let $d\geq 1$ and $n\geq d+1$. Let $\xi_1,\dots,\xi_n$ be (possibly dependent) random $d$-dimensional vectors with partial sums
$$
S_i = \xi_1 + \dots + \xi_i,\quad  1\leq i\leq n,\quad  S_0=0.
$$
We impose the following conditions on the joint distribution of the tuple $(\xi_1,\dots, \xi_n)$:
\begin{itemize}
\item [(i)] \emph{Symmetric exchangeability:} For every permutation $\sigma$ of $\{1,\dots,n\}$ and every choice of
signs $\eps_1,\dots,\eps_n\in\{+1,-1\}$, we have the equality in
distribution
    $$
    (\xi_1,\dots,\xi_n) \stackrel{d}{=}(\eps_1 \xi_{\sigma(1)}, \dots, \eps_n \xi_{\sigma(n)}).
    $$
\item[(ii)] \emph{General position of partial sums:}
For every $1\leq i_1 < \dots < i_d\leq n$, the probability that the vectors $S_{i_1}, \dots,S_{i_d}$ are linearly dependent is $0$.
\end{itemize}

Then
\begin{align}
    \pwalk{n}{d}
    &:=
    \pr\big(0 \in \Conv(S_1, S_2, \dots, S_n)\big)
    =
    \frac{2}{2^{n}n!}
    \sum_{r\geq 0}
    \stirlingb{n}{d+1+2r},

    \\
        \qwalk{n}{d}
    &:=
    \pr\big(0 \notin \Conv(S_1, S_2, \dots, S_n)\big)
    =
    \frac{2}{2^{n}n!}
    \sum_{r\geq 0}
    \stirlingb{n}{d-1-2r}.

\end{align}
Here, the numbers $\stirlingb{n}{k}$ with $n\in \{1,2,\dots\}$ and $k\in \mathbb Z$ are the $B$-Stirling numbers of the first kind defined by the generating function
\begin{align*}
    (t+1)(t+3) \cdots (t+2n-1)
    = \sum_{k\in \mathbb Z} \stirlingb{n}{k}\, t^k.
\end{align*}
In particular, $\stirlingb{n}{k}= 0$ for $n\in \{1,2,\dots\}$ and $k\notin\{0,\dots,n\}$, so that the sums appearing above terminate after finitely many nonzero terms. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

