        \end{enumerate}
If $Y$ is reflexive, then the converses of both implications also hold. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:01:01.832740+00:00","domain":"probability theory","id":"claim_c7b8c149f8e56f9e6b2d3160afce88cdc1708d230c8da809933d3bfff6431d10","kind":"lemma","schema_version":1,"statement":"[Lemma lem:t0-asymptotics of arXiv:2609.00556, 'Higgs--Demailly System and Positivity of Higgs Bundles'] Fix $\lambda_*>0$.  Uniformly for all $\lambda\geq\lambda_*$ and all
admissible solutions $(f,g)$ at $t=0$, with $u=\log g$, one has
\begin{equation}
 \lambda\|f\|_{C^0}=O(\alpha^{-1}),
 \qquad \|u\|_{C^0}\leq C,
 \qquad
 \frac{\|\Delta_\omega^{\mathbb C} f\|_{C^0}}{\alpha}=o(1)
 \quad (\alpha\to\infty).
\end{equation}
More precisely,
\[
 \sup_{\lambda\geq\lambda_*}
 \sup_{(f,g)\in\mathcal S_{\alpha,\lambda}}
 \frac{\|\Delta_\omega^{\mathbb C}f\|_{C^0}}{\alpha}
 \longrightarrow0
 \qquad\text{as }\alpha\to\infty,
\]
where \(\mathcal S_{\alpha,\lambda}\) denotes the set of admissible
solutions at \(t=0\).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:36:12.194178+00:00","domain":"probability theory","id":"claim_c7cd5469a4cbd35622c3bb42bc41240f71bc6eccd53415ac702c86ebbff353d2","kind":"concept","schema_version":1,"statement":"[Proposition 18 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W$ be an $N\times N$ Wigner matrix satisfying Assumption~\ref{ass:momass}. For any fixed $p, n,S\in \N$ with $p\ge 3$ it holds that
\begin{align}
\Xi_t^{(p)}(n,S)\lesssim & \left(\frac{N^{(n-p)/2}}{N^{(p-2)/2}} + \frac{(N\eta_t)^{n-p}}{(N\eta_t)^{p-2}}\right)\frac{N^\xi}{\eta_t^S},\\
\Theta_t^{(p)}(n,S)\lesssim & N^{(n-2p+2)/2+\xi},

\end{align}
for any fixed $\xi>0$, uniformly in $t\in [0,T]$ and $z=z_T\in\mathcal{D}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:09:49.849425+00:00","domain":"probability theory","id":"claim_c7e3986eb32bba89d59a28542e7020b662ebe49f63062864a639c21a95180fb1","kind":"concept","schema_version":1,"statement":"[Proposition 61 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] $F$ is $r$-$\sigma$-semicontinuous if and only if the common $\sigma$-order and $\mathrm{u\sigma o}$ closure of $\Ba_{F}$ is contained in $r\Ba_{F}$. Moreover, the following conditions are equivalent:
\item[(i)] $F$ is topologically $\sigma$-semicontinuous;
\item[(ii)] The norm topology is $\sigma$-semicontinuous;
\item[(iii)] The common $\sigma$-order and $\mathrm{u\sigma o}$ closure of $\Ba_{F}$ is norm bounded;
\item[(iv)] $\sigma$-order closure preserves norm bounded sets;
\item[(iv')] $\mathrm{u\sigma o}$ closure preserves norm bounded sets. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:51:26.645168+00:00","domain":"probability theory","id":"claim_c7f1c9013f877ff66b12f24644e4c4f6ba412460e315fabe13c7792daed97510","kind":"lemma","schema_version":1,"statement":"[Lemma L:MomentBounds of arXiv:2606.03079, 'Mean Field Limits for Stochastic, Underdamped Reactive Langevin Dynamics Models'] Let Assumptions (A:AssumptionRho of the paper) as well as Assumption (A:AssumptionMomentFinitenessGeneral of the paper) hold.
Then there exists a finite constant $C<\infty$ (not depending on $\zeta$) such that the following moment bound holds
\begin{align*}
\sup_{t\in[0,T]}\sum_{j=1}^{J} \theta^{\zeta,j,2p}_{t}&=\sup_{t\in[0,T]}\sum_{j=1}^{J}\mathbb{E}\left \langle |x|^{2p} +|v|^{2p},\mu^{\zeta,j}_{t}(dx,dv)\right\rangle \leq C<\infty,
\end{align*}
where the $p$ used above corresponds to the one from Assumption (A:AssumptionRho of the paper) and Assumption (A:AssumptionMomentFinitenessGeneral of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:55:42.215899+00:00","domain":"probability theory","id":"claim_c7f36df34c05bfa8b6fbb7c296e73f2d0a78eb02015205f7694cd19de65046fa","kind":"concept","schema_version":1,"statement":"[Thm potential-infty of arXiv:2411.16376, 'Higher order approximations in arcsine laws for subordinators'] Let $X=(X_t)_{t\geq0}$ be a killed subordinator which is not identically zero. Let $N\in\ensuremath{\mathbb{N}}$ be fixed. Assume that the Laplace exponent $\Phi(z)$ satisfies the following two conditions:
\begin{enumerate}[label={\upshape (\Alph*)}]
\item There exist constants $n\in\ensuremath{\mathbb{N}}\cup\{0\}$, $c_0\in(0,+\infty)$, $c_1,\dots,c_n\in\ensuremath{\mathbb{R}}\setminus\{0\}$ and  $ \alpha_0>\alpha_1>\dots>\alpha_n>-N+1$ with $\alpha_0\in[0,1]$, and a locally integrable function $R:(0,+\infty)\to(0,+\infty)$ such that $R(t)$ is non-increasing on $(0, r)$ for some $r>0$,  $R(t)=o(t^{-N-\alpha_n})$, as $t\to0+$, and
\begin{align}
    \bigg(\frac{d}{dz}\bigg)^{N}
     \bigg(
    \frac{1}{\Phi(z)}
    -
    \sum_{k=0}^n\frac{1}{c_k z^{\alpha_k}}
    \bigg)
    =
    O(R(|z|)),
    \quad
    \text{as $z\to0$ in $\{z\in\ensuremath{\mathbb{C}}\mid {\rm Re}\,z>0\}$}.	
\end{align} 

\item  For any $r>0$, 
\begin{align}
   \sup_{\lambda>0} \int_{\ensuremath{\mathbb{R}}\setminus(-r,r)} 
   \bigg|
   \bigg(\bigg(\frac{d}{dz}\bigg)^N
   \frac{1}{\Phi}\bigg)(\lambda+i\theta)\bigg|\,d\theta<+\infty.	
\end{align}
\end{enumerate}
Then, the potential measure $U|_{(0,+\infty)}(dx)$ restricted over $(0,+\infty)$ admits a continuous density $u(x)$ $(0<x<+\infty)$ which can be estimated as
\begin{align}
   u(x)
   =
   \sum_{k=0}^n\frac{x^{-1+\alpha_k}}{c_k\Gamma(\alpha_k)}+O(\varepsilon_1(x)),
   \quad\text{as $x\to+\infty$},
\end{align}
where 
\begin{align}
   \varepsilon_1(x)=x^{-N-1}R(x^{-1})+x^{-N}\int_{x^{-1}}^{1} R(t)\,dt.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:48:35.820311+00:00","domain":"probability theory","id":"claim_c82c66011f5232eb62b121bf013c913aeb92fc5520acc07023b6bf565d8a5f91","kind":"definition","schema_version":1,"statement":"[Definition def-frac-Gaus-field of arXiv:2411.09614, 'Moment estimates for the stochastic heat equation on Cartan-Hadamard manifolds'] Consider  $\alpha>0$ and the following Hilbert space of space-time functions:
\begin{align}
\mathcal{H}_\alpha=L^2(\mathbb{R}_+, \mathcal{W}^{-\alpha}(M)),  
\end{align}
    where $\mathcal{W}^{-\alpha}(M)$ is the Sobolev space introduced in Definition (sobo_def of the paper). On a complete probability space $(\Omega, \mathcal{G},\mathbf{P})$ we define a centered Gaussian family $\{W(\phi); \phi\in \mathcal{H}_\alpha\}$, whose covariance is given by 
\begin{align}
\mathbf E\left[ W(\varphi) W(\psi)\right]
=&
\int_{\mathbb{R}_+}\ \left\langle \varphi (t,\cdot) , \psi (t,\cdot)\right\rangle_{\mathcal{W}^{-\alpha}(M)}  dt \notag\\
=&
\int_{\mathbb{R}_+} \int_{M^2} \varphi (t,x)  \psi (t,y)G_{2\alpha}(x,y)dxdy dt
\, ,
\end{align}
for $\varphi$, $\psi$ in $\mathcal{H}_\alpha$. This family is called the fractional Gaussian fields on $M$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.360627+00:00","domain":"probability theory","id":"claim_c83d7dc8517aa86ee3af360dbcb3a201648afb51b6db8aa30d08f612a508d771","kind":"lemma","schema_version":1,"statement":"[Lemma lem:entropy:symmetry of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $\nu \in \mathcal{M}_{2, d}$ is absolutely continuous with respect to Lebesgue measure. Let $\psi_\nu^n$ be defined as in (equation eq:entropy:2reconstruction of the paper). Then $\psi_\nu^n$ is a 2-MRF on $(\ensuremath{\mathbb{R}}^d)^{V_n}$, and can be formulated equivalently in the following ways:
\begin{equation}
       \psi_\nu^n\big(\mathbf{x}^{(n)}\big) =
\begin{dcases}
    \nu(x_{-1}, x_{0}, x_{1}) \prod_{v =1} ^{n-1} \nu(x_{v+1} | x_v, x_{v-1})\nu(x_{-v-1}|x_{-v}, x_{-v+1}) , & \\
    \nu(x_{n-2}, x_{n-1}, x_{n}) \prod_{v = -n}^{n-3} \nu(x_v|x_{v+1}, x_{v+2}),  & \\
    \nu(x_{-n}, x_{-n+1}, x_{-n+2}) \prod_{v = -n+3}^{n} \nu(x_{v}|x_{v-1}, x_{v-2}). &
\end{dcases}

\end{equation}
Moreover, we have
        \begin{equation}
        \int_{(\ensuremath{\mathbb{R}}^d)^{ \mathbb{T}_2^n}}  f(x_{v-1}, x_v, x_{v+1}) \psi_\nu^{n}(\mathbf{x}^{(n)})d\mathbf{x}^{(n)} = \int_{(\ensuremath{\mathbb{R}}^d)^3} f(\mathbf{x}) \nu(\mathbf{x}) d\mathbf{x}. 

    \end{equation}
    for all $f \in L^1(\nu)$ and $v \in \{-n+1, \ldots, n-1\}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:53:31.974416+00:00","domain":"probability theory","id":"claim_c844b6831578c318b54a9ba918ea3d7aa3d3faf05d37eaf5e4751cea0b251257","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2606.11142, 'Strong invariance principles for diffusions, Markov chains and their perturbations.'] In the degenerate case where A1, A2, AD3 hold, there exists a probability space supporting versions of the processes $V_{t_k} = (\tilde{X}_{t_k}, \tilde{Y}_{t_k})$ and $V^\epsilon_{t_k} = (\tilde{X}^{(\epsilon)}_{t_k}, \tilde{Y}^{(\epsilon)}_{t_k})$ and a positive constant $C$ such that the probability of their paths coinciding on the entire grid satisfies:
\begin{equation*}
\mathbb{P} \left( V^\epsilon_{t_k} = V_{t_k} \text{ for all } k = 1, \dots, m \right) \ge 1 - C m \bar{\Delta}_{\epsilon,\gamma,q}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:37:25.906193+00:00","domain":"probability theory","id":"claim_c852e5f2f8c8162cfe71871f0d19b55dfdfb478c13f03b484639bdc48c2caf12","kind":"theorem","schema_version":1,"statement":"[Proposition 10 (Newton inversion) of arXiv:2608.29585, '2608.29585'] Every sequence $f_r\in L$ has a unique expansion
\eqref{eq:abstract-newton-expansion}.  Its coefficients satisfy
\begin{equation}
 h_k=
 \frac{f_k-\sum_{j=0}^{k-1}p_j(x_k)h_j}{p_k(x_k)}
\end{equation}
and
\begin{equation}
 h_k=\sum_{j=0}^{k}\frac{f_j}{D_{k,j}},
 \qquad
 D_{k,j}=\prod_{\substack{0\le i\le k\\i\ne j}}(x_j-x_i).
\end{equation}
For $k\ge1$, put
\begin{equation}
 \Delta_k(f)=\det
 \begin{pmatrix}
 1&x_0&\cdots&x_0^{k-1}&f_0\\
 1&x_1&\cdots&x_1^{k-1}&f_1\\
 \vdots&\vdots&&\vdots&\vdots\\
 1&x_k&\cdots&x_k^{k-1}&f_k
 \end{pmatrix},
 \qquad \Delta_0(f)=f_0,
\end{equation}
and
\begin{equation}
 V_k=\prod_{0\le i<j\le k}(x_j-x_i),
 \qquad V_0=1.
\end{equation}
Then
\begin{equation}
 h_k=\frac{\Delta_k(f)}{V_k}.
\end{equation}","status":"unverified"}

