{"assumptions":[],"created_at":"2026-10-27T14:25:44.589534+00:00","domain":"probability theory","id":"claim_d7dd84a2f096d3de070cd61c0c84f09551f8a7164a5ad9437296a9e60efab9d2","kind":"concept","schema_version":1,"statement":"[Thm Theorem 1 of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Let $\mathsf{P}_i\in \mathcal P_{s,1}(\Gamma)$ with $\mathcal F^{elec}_{\beta}(\mathsf{P}_i)<\infty$, $i=0,1$. Then there exists a coupling $ \mathsf{Q}\in  \mathsf{Cpl}_{s,m}(\mathsf{P}_0,\mathsf{P}_1)$ such that for $0\leq t\leq 1$ \begin{align}
        \mathcal F^{elec}_{\beta}(\mathsf{P}_{t})&\leq  (1-t) \mathcal F^{elec}_{\beta}(\mathsf{P}_{0})+t\mathcal F^{elec}_{\beta}(\mathsf{P}_{1})\\
        &-\frac{(\mathbbm{1}_0(s)+s(s+1))(1-t)t\beta}{4}\int \sum_{(0,0)\neq (x,y)\in \bar\xi} (x-y)^2\inf_{z\in [x,y]}\left\lvertz\right\rvert^{-s-2} \mathsf{Q}^0(d\bar\xi),\nonumber
    \end{align}
    where  $\mathsf U:=\iota( \mathsf{Q})$ and  $\mathsf{P}_t:= \mathsf{gap}^{-1}\left((T_t)_{\#}\mathsf U\right)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:09:59.191057+00:00","domain":"probability theory","id":"claim_d7ee2e4f0fa6557aeb2c273a4ba5600c54a4d64b44ef762c0964cb2fc9d137e5","kind":"definition","schema_version":1,"statement":"[Defn leftconv of arXiv:2608.06500, 'Free energy of Ising models under a spectral condition'] Let $G=(\text{\boldmath $A$},\text{\boldmath $h$}_1,\ldots,\text{\boldmath $h$}_k)$ be a weighted graph on vertex set
    $[N]$ and $X=(\text{\boldmath $W$},\text{\boldmath $d$}_1,\ldots,\text{\boldmath $d$}_k)$ be a test graph on vertex
    set $[n]$. We define the \emph{weighted homomorphism density}
    $t(X,G)$ as the quantity

    \begin{align}
    t(X,G):=\frac1{N^{c(X)}} \sum_{f:[n]\rightarrow[N]} \left(
    \prod_{i\in[n]} \prod_{\ell=1}^k h_{\ell,f(i)}^{d_{\ell,i}}
    \right) \left( \prod_{i\le j\in[n]} a_{f(i)f(j)}^{w_{ij}}
    \right)\, .
    \end{align}

    We say that a sequence $G_1,G_2,\ldots$ of weighted graphs is
    \emph{left-convergent} if for all test graphs $X$, the sequence
    $t(X,G_1),t(X,G_2),\ldots$ converges to a finite value.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:51:11.954628+00:00","domain":"probability theory","id":"claim_d7f33f30bc399f3ab16e08f5a94a1b5008b4d65fa99757d3952b1d4ed68f23be","kind":"theorem","schema_version":1,"statement":"[Proposition 21 (Spike-profile bounded analytic LSS input) of arXiv:2608.07820, 'Linear Spectral Statistics for Entrywise-Transformed Spiked Wigner Matrices under Shifted '] Assume W3--W5 and the spike assumption \eqref{eq:spike-package}.  Let
\(H_N=H_N^{(4)}\) be the centered atomic array
\eqref{eq:R3-centered-array}, put
\(S_{ij}:=\E H_N(i,j)^2\), and let \(S_N^0\) be
\eqref{eq:R3-flat-S}.  Then
\begin{align}
 |\sqrt N H_N(i,j)|&\le C,\\
 \max_{i\ne j}|NS_{ij}-1|&\to0,\\
 \max_i\left|\sum_jS_{ij}-1\right|&=o(N^{-1/2}),
 \\
 \max_i\sum_j|S_{ij}-S_{ij}^0|&\to0,\\
 \norm{S_N-S_N^0}_{\HS}&\to0.
\end{align}
Let \(m_{i,N}(z)\) be the vector Dyson-equation solution
\begin{equation}
 -\frac1{m_{i,N}(z)}
 =z+\sum_jS_{ij}m_{j,N}(z),
 \qquad
 \overline m_N(z):=\frac1N\sum_i m_{i,N}(z),
\end{equation}
and let \(\overline m_N^0\) denote the corresponding scalar solution for
\(S_N^0\).  Moreover,
\begin{equation}
 \max_{i<j}\left|
 \cum_4(\sqrt N H_N(i,j))-\kappa_4^{f,\nu}
 \right|\to0.
\end{equation}
For a function \(\varphi\) analytic near \(\Gamma\), define the
zero-diagonal Dyson-density correction
\begin{equation}
 d_{\varphi,\Gamma,N}^{0,\rm Dyson}
 :=-\frac{N}{2\pi\ii}\oint_\Gamma
 \varphi(z)\bigl(\overline m_N^0(z)-m(z)\bigr)\,\dd z.
\end{equation}
Then, for every finite family of such functions, there are deterministic
bounded-endpoint biases \(m_{\varphi,\Gamma,N}^{\rm fluc}\) such that
\begin{equation}
 \left(
 \Tr\varphi_\ell(H_N)
 +\frac{N}{2\pi\ii}\oint_\Gamma
       \varphi_\ell(z)\overline m_N(z)\,\dd z
 -m_{\varphi_\ell,\Gamma,N}^{\rm fluc}
 \right)_\ell
 \Longrightarrow (G_{\varphi_\ell})_\ell .
\end{equation}
The bias not contained in the exact Dyson density satisfies
\begin{equation}
 m_{\varphi,\Gamma,N}^{\rm fluc}
 +d_{\varphi,\Gamma,N}^{0,\rm Dyson}
 \longrightarrow m_{\varphi,\Gamma}^{\rm base}(\kappa_4^{f,\nu}),
\end{equation}
and the limiting covariance is
\(\mathcal V_{\kappa_4^{f,\nu}}^\Gamma\).  No convergence or homogeneity of
the edgewise third cumulants is assumed.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:36:12.193531+00:00","domain":"probability theory","id":"claim_d83406a64cdcc88ff7610a2c5553b19918ce3fe1736ebce54ec65e2bfc37eed0","kind":"concept","schema_version":1,"statement":"[Lemma 13 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W$ be an $N\times N$ GOE/GUE matrix. For any fixed $D\in\N$, $n_1,n_2\in\N\cup\{0\}$ and multi-indices $\bm{k}\in \N^{n_1},\bm{l}\in\N^{n_2}$, it holds that
\begin{equation}
\E\left(\bm{k},\bm{l}\right) = \sum_{d=0}^{D-1} \frac{1}{(N\eta)^d}\Phi_d\left(\bm{k},\bm{l}\right) + \mathcal{O}\left(\frac{1}{(N\eta)^D}+\eta\right),

\end{equation}
where the implicit constant in $\mathcal{O}(\cdot)$ is uniform in $z\in\mathcal{D}$. For $d\in \N\cup\{0\}$, the coefficients $\Phi_d$ depend only on $\Re z$, $\bm{k}$, $\bm{l}$ and $\beta$, and satisfy the following recurrence relations for $\bm{k}\neq\emptyset$:
\begin{equation}
\begin{split}
\Phi_d(\bm{k},\bm{l})=&\frac{2\ma_0}{\beta}\Im m_0 \sum_{j=1}^{n_2} \frac{\ii^{k_1-l_j-1}}{2^{k_1+l_j-1}} l_j\binom{k_1+l_j-1}{k_1-1} \Phi_d\left(\bm{k}^{[1]},\bm{l}^{[j]}\right)+\bm{1}_{\beta=1}\ma_0 k_1\Phi_{d-1}\left(\big(k_1+1,\bm{k}^{[1]}\big),\bm{l}\right)\\
+& \ma_0 \sum_{u=1}^{k_1} \Phi_{d-1}\left(\big(u,k_1+1-u,\bm{k}^{[1]}\big),\bm{l}\right)+\frac{2\ma_0}{\beta} \sum_{i=2}^{n_1} k_i \Phi_{d-1}\left(\big(k_1+k_i+1,\bm{k}^{[1,i]}\big),\bm{l}\right)\\

+&\frac{2\ma_0}{\beta} \sum_{j=1}^{n_2} \sum_{u=1}^{k_1} l_j \frac{(-1)^{k_1-u}}{(2\ii)^{k_1+l_j+1-u}} \binom{k_1+l_j-u}{l_j}\Phi_{d-1}\left( \big(u, \bm{k}^{[1]}\big), \bm{l}^{[j]}\right)\\
+&\frac{2\ma_0}{\beta} \sum_{j=1}^{n_2} \sum_{v=1}^{l_j+1} l_j\frac{(-1)^{k_1}}{(2\ii)^{k_1+l_j+1-v}}\binom{k_1+l_j-v}{k_1-1}\Phi_{d-1}\left(\bm{k}^{[1]},\big(v,\bm{l}^{[j]}\big)\right).
\end{split}

\end{equation}
Here we additionally set $\Phi_{d'}:=0$ for $d'<0$ and $\Phi_0(\emptyset,\emptyset):=1$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.287901+00:00","domain":"probability theory","id":"claim_d8419e48118af6a2cef446e961146805bc749d1d19f19506ab099a3394c53a86","kind":"lemma","schema_version":1,"statement":"[Lemma Hopf Lax of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $\mu$ be a probability measure on $\mathbb{R}$ with support bounded from below and let $t>0$.
		\begin{enumerate}
			\item Let $x\in\mathbb{R}$ and set $\omega := \omega_{\mu,t}(x)\in\mathbb{C}^+\cup\mathbb{R}$. Define the characteristic path $(z_s)_{s\in [0,t]}$ by
			\begin{equation}
				z_s = \omega + s\, G_\mu(\omega).
			\end{equation}
			If $x\leq \ell(\mu\boxplus\sigma_t)$, then for every $s\in [0,t]$,
			\begin{equation}
				x \leq z_s \leq \ell(\mu\boxplus\sigma_s).
			\end{equation}
			If instead $x$ lies in the interior of $\mathrm{supp}(\mu\boxplus\sigma_t)$, then for every $s\in [0,t)$,
			\begin{equation*}
				\Im\bigl(\omega + s\,G_\mu(\omega)\bigr) > 0.
			\end{equation*}

			\item For every $x\leq \ell(\mu\boxplus\sigma_t)$,
			\begin{multline}
				\int \log|\lambda-x|\,\mathrm{d} (\mu\boxplus \sigma_t)(\lambda) = \int \log |\lambda-\omega_{\mu,t}(x)|\,\mathrm{d} \mu(\lambda) + \frac{\Re\bigl(\omega_{\mu,t}(x)-x\bigr)^2 - \Im\bigl(\omega_{\mu,t}(x)\bigr)^2}{2t}\\
				= \inf_{u\leq \ell(\mu)}\;\sup_{\substack{v\geq 0 \\ u+iv\in \overline{\Omega_{\mu,t}}}} \Bigl(\int \log |\lambda-(u+iv)|\,\mathrm{d} \mu(\lambda) + \frac{(x-u)^2-v^2}{2t}\Bigr).
			\end{multline}
			Moreover, the infimum in (equation eq:ch of the paper) is uniquely attained at $(u,v)=\bigl(\Re(\omega_{\mu,t}(x)),\,\Im(\omega_{\mu,t}(x))\bigr)$.
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:13:18.537464+00:00","domain":"probability theory","id":"claim_d87b44a7376a8a66d48838aafbd6cac81bacc83fab41f90a1a48717ceb9a2397","kind":"concept","schema_version":1,"statement":"[Lemma 23 (Second overshoot lemma) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] We assume that there is \(\delta >  d\) such that
