{"assumptions":[],"created_at":"2026-10-26T19:36:04.990437+00:00","domain":"probability theory","id":"claim_d9a4173c878b401b28a3f0dc0741e0c0ac616110fda03ac331480c211c3cd5f4","kind":"theorem","schema_version":1,"statement":"[Theorem 14 of arXiv:2604.00882, 'On some extensions of generalized counting processes'] Let $\mathcal N_\Lambda(\mathcal{L}^\mu(t))$ be the time-changed Poisson process with the rate $\Lambda$, where $\mathcal{L}^\nu(t)$ is the inverse process defined in 
	\eqref{genLnu} with parameters $\mu_j\ge0$, $j=1,\dots,N$ such that the following holds:
	\begin{equation} 
		\sum_{j=1}^N \mu_j x^j + \Lambda = \prod_{j=1}^M (x-\eta_j)^{m_j}, \quad \eta_j \in \mathbb{R}, \quad \sum_{j=1}^M m_j=N,
	\end{equation}
	and $\nu_j$ are of the form $\nu_j = j\nu$, $j=1,\dots,N$, for some $\nu \leq \frac{1}{N}$.

	Then $p_k^\nu(t)$ which solve equation 
	\eqref{gen(3.1)-(3.2)} can be represented as follows:
	\begin{equation} 
		p_k^\nu(t) = \Lambda^k \sum_{j=1}^N \mu_j t^{\delta_j - 1} E_{\nu, \delta_j}^{\gamma_1, \dots, \gamma_M} (\eta_1 t^\nu, \dots, \eta_M t^\nu),
	\end{equation}
	where $\gamma_j = m_j(k+1)$, $\delta_j = \nu(N(k+1)-j)+1$, $E_{\nu, \delta_j}^{\gamma_1, \dots, \gamma_M}$ is the multivariate Mittag-Leffler function defined by \eqref{multML}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:11:09.268796+00:00","domain":"probability theory","id":"claim_d9aa8adc22690d3ecdb6a5a9ebe04064d8c83e94937b714f59db81a15f5e6e5f","kind":"definition","schema_version":1,"statement":"[Definition def: solution of arXiv:2411.05924, 'Non-negative Martingale Solutions to the Stochastic Porous Medium Equation with Sticky Beh'] A tuple $((\Omega, \mathcal F, \mathbb F, \mathbb P), u, W)$, where $(\Omega, \mathcal F, \mathbb F, \mathbb P)$ is a stochastic basis supporting a $U$-valued $\mathbb F$-adapted $Q$--Wiener process $W$ and an $\mathbb F$-adapted process $u$, is called a \emph{non-negative martingale solution to the stochastic porous medium equation} (equation eq: intro1 of the paper)--(equation eq: intro3 of the paper) if
    \begin{enumerate}[label=(\roman*)]
        \item $u \in \bigcap_{\delta\in(0,1)} \Xi_{\mathfrak u}^\delta$;
        \item $u(t,x) \geq 0$ $\mathbb P \otimes \mathrm d t \otimes \mathrm d x$-a.s.;
        \item for all $\varphi \in C^3_c([0,1],\mathbb R)$, $\mathbb P \otimes \mathrm d t$-a.s.~we have that 
        \begin{align}
            \nonumber
            &\langle \varphi, u(t) \rangle = \left\langle \varphi, u_0 \right\rangle + \int_0^t \left\langle \partial_x^2 \varphi, u^\alpha(r) \right\rangle \mathrm d r \\

            &\qquad+ \int_0^t \langle \varphi, \1_{u(r)>0} B(u(r)) \mathrm d W(r) \rangle + \int_0^t \langle \varphi, \1_{u(r)=0} R(u(r)) \rangle \mathrm d r.
        \end{align}
    \end{enumerate}
    Furthermore, let $\mathcal S: L^2(\mathcal Q_T) \rightarrow \mathbb R$ be a functional given by
    \begin{equation}

        \mathcal S(u) := \iint_{\mathcal Q_T} \1_{u(t,x)=0} \mathrm d t \mathrm d x.
    \end{equation}
    We say that the system (equation eq: intro1 of the paper)--(equation eq: intro3 of the paper) exhibits \textit{sticky behavior} if
    \begin{equation}

        \mathbb P\left( \mathcal S( u) > 0 \right) > 0.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:06.329145+00:00","domain":"probability theory","id":"claim_d9d65b8d28ecaca67e4cecedf9ff96fa2685bfaaf32bb7028deb4cc8a3550f9b","kind":"concept","schema_version":1,"statement":"[Lemma 9 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Set $\bm{\sigma}_1,\bm{\sigma}_2\in\C^2$. Assume $\left(\mathbf{W}_t^{H}\right)_{t\geq 0}\subset \C^2$ to be an fBm with Hurst index $H\in\left(0,1\right)$. Let $\left(\psi_t^{(1)}\right)_{t\geq 0}$ and $\left(\psi_t^{(2)}\right)_{t\geq 0}$ be scalar solutions to the system
\begin{align}
    \begin{split}
        \txtd \psi_t^{(1)} = \alpha\psi_t^{(1)}~\txtd t + \left\langle \txtd \mathbf{W}_t^{H} , \bm{\sigma}_1 \right\rangle,\\
        \txtd \psi_t^{(2)} = \beta \psi_t^{(2)}~\txtd t + \left\langle \txtd \mathbf{W}_t^{H} , \bm{\sigma}_2 \right\rangle,
    \end{split}
\end{align}
each initial conditions at $t=0$ in $\C$. Lastly, consider $\alpha,\beta\in\C$ with negative real part. Then, for all $\tau\ge0$, we obtain that
\begin{align}
    &\underset{t\to\infty}{\lim}\text{Cov}\left(\psi_t^{(1)}, \psi_{t+\tau}^{(2)} \right)
    = H \underbrace{\left\langle \bm{\sigma}_2, \bm{\sigma}_1 \right\rangle}_{\text{masking}} \underbrace{P(\alpha,\beta,H,\tau)}_{\text{memory}} \underbrace{\left( -\alpha - \overline{\beta} \right)^{-1}}_{\text{mitigation}},
\end{align}
with $P$ introduced in \eqref{eq:function_P}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

