	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:57:59.854126+00:00","domain":"probability theory","id":"claim_f7f7db4e676a8848121d4d078242c8ef617430a7771e9e1e129bffa7b950c05b","kind":"definition","schema_version":1,"statement":"[Definition def:hoelder_sets_def of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] For $n \in \mathbb{N}$, let
    \begin{equation*}
        \mathrm{HC}_n \coloneqq \Big\{ \psi \in C_0[0,1] \,\Big|\, \forall \, x,y \in [0,1]: \; | \psi(x)-\psi(y) | \leq n\, |x-y|^{1/n} \Big\},
    \end{equation*}
    and let $\mathrm{HC} \coloneqq \bigcup_{n>0} \mathrm{HC}_n$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:27:08.852417+00:00","domain":"probability theory","id":"claim_f81cb429da3af066abdb38b86ac005d01d14d51fbdb08415b7670b530ca87608","kind":"concept","schema_version":1,"statement":"[Lemma 12 (Ratio identities and diagonal normalization) of arXiv:2511.12623, 'The eigenvector bead process'] For $g_i,g_j\neq0$ and any $k$,
\begin{equation}
\frac{\Omega^{(N)}_{k,j}}{\Omega^{(N)}_{k,i}}
=\frac{\Delta_{k,i}^{(N)}}{\Delta_{k,j}^{(N)}}\cdot \frac{g_j^{(N)}}{g_i^{(N)}},
\qquad
\frac{\Omega^{(N)}_{k,N+1}}{\Omega^{(N)}_{k,i}}
=\frac{\Delta_{k,i}^{(N)}}{g_i^{(N)}}.
\end{equation}
In addition, for $k=i$,
\begin{equation}
\bigl(\Omega^{(N)}_{i,i}\bigr)^2
=
\left[
\left(\frac{\Delta_{i,i}^{(N)}}{|g_i^{(N)}|}\right)^{\!2}
\left(1+\sum_{j=1}^N \left(\frac{|g_j^{(N)}|}{\Delta_{i,j}^{(N)}}\right)^{\!2}\right)
\right]^{-1}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

