      &\phantom{=}\times m_{\ell}\left(\bm{y},\bm{v'}|\bm{x},\bm{v}\right)d\bm{y}d\bm{v'}\biggr)\lambda^{(\ell)}[\xi_{s}](d\bm{x}, d\bm{v}) ds.\notag
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:41:19.436812+00:00","domain":"probability theory","id":"claim_fe043280d542329116106ea496f3b14aa64d495cdbbbf84b2281e3856dcffe90","kind":"lemma","schema_version":1,"statement":"[Lemma lem:independence-across-disjoint-balls of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] For each $M>0$, $p,q \in (0,1)$, and $s>0$, there exists $n_* = n_*(M,p,q,s) \in \BN$ such that the following is true. Let $x_1,\ldots,x_n \in \partial \BD$ with $n \geq n_*$. Let $r>0$. Suppose that $|x_j - x_k| \geq 2(s+1) r$ for all distinct $j,k \in [1,n]_{\BZ}$. Let also $\Psi$ be a GFF on $\BD$ with boundary conditions given by a measurable function bounded by $M$. Let $E_1,\ldots,E_n$ be a family of events such that each $E_j$ is measurable with respect to the $\sigma$-algebra generated by $\Psi|_{B_r(x_j) \cap \BD}$. Suppose that $\BP[E_j] \geq p$ for all $j \in [1,n]_{\BZ}$. Then
	\begin{equation*}
		\BP\!\left\lbrack\bigcup_{j = 1}^n E_j\right\rbrack \ge q. 
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:09:59.300412+00:00","domain":"probability theory","id":"claim_fe07a998f99313534ea87a5bf14fe3125c13ca1c3b824e640bb9e0d1d235b335","kind":"concept","schema_version":1,"statement":"[Prop discretize of arXiv:2608.06500, 'Free energy of Ising models under a spectral condition'] Given a strong solution $t\mapsto \text{\boldmath $x$}^{(t)}\in\mathbb{R}^N$ to the SDE

    \begin{align*}
{\rm d}\text{\boldmath $x$}^{(t)}=\text{\boldmath $a$}(\text{\boldmath $x$}^{(t)}){\rm d} t+\sigma{\rm d}\text{\boldmath $w$}^{(t)}
\end{align*}

    on $\mathbb{R}^N$ for some function $\text{\boldmath $a$}:\mathbb{R}^N\rightarrow\mathbb{R}^N$ and constant diffusion coefficient $\sigma$, along with a step
    size $\delta\in(0,1)$, consider the Euler-Maruyama scheme
    $\text{\boldmath $y$}^{(0)},\text{\boldmath $y$}^{(1)},\text{\boldmath $y$}^{(2)},\ldots$ defined recursively by
    $\text{\boldmath $y$}^{(0)}=\text{\boldmath $x$}^{(0)}$ and

    \begin{align*}
\text{\boldmath $y$}^{(n+1)}=\text{\boldmath $y$}^{(n)}+\delta
\text{\boldmath $a$}(\text{\boldmath $y$}^{(n)})+\sigma(\text{\boldmath $w$}^{(\delta(n+1))}-\text{\boldmath $w$}^{(\delta n)}).
\end{align*}

    Suppose that, for some positive constants $K_1,K_2,K_3$, we have that
    $\mathbb{E}[\|\text{\boldmath $x$}^{(0)}\|^2]\le K_1N$, $\| \text{\boldmath $a$}({\boldsymbol 0})\|^2\le K_2N$, and
    $\| \text{\boldmath $a$}(\text{\boldmath $u$})-\text{\boldmath $a$}(\text{\boldmath $v$})\|\le K_3\|\text{\boldmath $u$}-\text{\boldmath $v$}\|$ for all $\text{\boldmath $u$},\text{\boldmath $v$}\in\mathbb{R}^N$,
    i.e. the initial condition is bounded in $L^2$ and the drift
    coefficient is Lipschitz and bounded at the origin. Then there
    exists a constant $L$ depending only on $K_1,K_2,K_3$ such that
    for all $\delta>0$ and $T\in\delta\mathbb{N}$, we have that

    \begin{align*}
\mathbb{E}[\|\text{\boldmath $x$}^{(T)}-\text{\boldmath $y$}^{(T/\delta)}\|^2]\le Le^{LT}\delta N.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:25:44.582578+00:00","domain":"probability theory","id":"claim_fe3441d17104e251769b9fa43bbc84b1a716172bb0a8ba664447bc8063e31744","kind":"concept","schema_version":1,"statement":"[Cor of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Assume that $D(\mathcal F_{\beta})\cap X^{a}_{p}\neq \emptyset$ and  let $\mathsf{P}_\beta\in X^{a}_{p}$ be the unique minimizer of $\mathcal F_{\beta}$ on $X^{a}_{p}$. Put $\Pi_\beta:= \mathsf{gap}(\mathsf{P}_\beta)$.
   Then for any $\mathsf{P}\in X^{a}_{p}\cap D(\mathcal F_{\beta})$
   \begin{align*}
       \frac{\beta }{2a^{\frac{2-p}{p}}} \mathscr W_{gap,p}^2( \mathsf{gap}(\mathsf{P}),\Pi_\beta)\leq \mathcal F_{\beta}(\mathsf{P})-\mathcal F_{\beta}(\mathsf{P}_\beta)\leq \frac{a^{\frac{2-p}{p}}}{2\beta } \abs{\partial \mathcal F_{\beta}}^2(\mathsf{P}).
    \end{align*}
    Moreover, any curve of maximal slope $(\mathsf{P}_t)_{t>0}$ w.r.t. $\abs{\partial \mathcal F_{\beta}}$ in $X^{a}_{p}$ satisfies for every $t\geq t_0>0$
    \begin{align*}
        \frac{\beta }{2a^{\frac{2-p}{p}}}\mathscr W_{gap,p}^2( \mathsf{gap}(\mathsf{P}_t),\Pi_\beta)\leq \mathcal F_{\beta}(\mathsf{P}_t)-\mathcal F_{\beta}(\mathsf{P}_\beta)\leq (\mathcal F_{\beta}(\mathsf{P}_{t_0})-\mathcal F_{\beta}(\mathsf{P}_\beta))e^{-2\beta a^{\frac{p-2}{p}}(t-t_0)}.
    \end{align*}
Moreover, for $0<\beta<\beta'$ 
\begin{align*}
       \mathscr W_{gap,p}^2(\Pi_{\beta},\Pi_{\beta'})\leq \frac{2(\beta'-\beta)}{\beta}\max\left(\int f( \mathsf{s}_0)^{\frac{p}{p-2}}\Pi_\beta(d \mathsf{s}) ,\int f( \mathsf{s}_0)^{\frac{p}{p-2}}\Pi_{\beta'}(d \mathsf{s}) \right)^{\frac{2-p}{p}}\mathcal W^{int}(\mathsf{P}_{\beta})
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:28:49.113916+00:00","domain":"probability theory","id":"claim_fe362fdb3328570e55b014e44241076806fb7c5a2c6f2bd8a1e4cd1f9ea9c326","kind":"concept","schema_version":1,"statement":"[Theorem HKUB of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Given a metric measure space $(M, d, \mu)$ such that there exist some $c>0, \alpha>0$ such that  $c^{-1}r^\alpha \le \mu(B(x,r))\le cr^\alpha$ for all $x\in M$ and $r>0$. Let $X$ be a stochastically complete diffusion on $M$ such that the heat kernel of $X$ is continuous and satisfies the on-diagonal estimate
$$
p(t,x,x)\le C t^{-\alpha/\beta}, \quad \text{for all }x\in M, \, t>0.
$$
Let $B(x, r)$ denote a metric ball of radius $r$ centered at $x \in M$. The following three conditions are equivalent:
\begin{enumerate}[(a)]
\item The off-diagonal sub-Gaussian-type heat kernel estimate
\begin{equation}
p(t,x,y)\le \frac{C}{t^{\alpha/\beta}}\exp\left\{-C\left(\frac{d(x,y)}{t^{1/\beta}}\right)^{\beta /(\beta -1)}\right\},\quad \text{for all }t>0, \, x\in M;
\end{equation}
\item 
$$
{\mathbb{E}}^x\left[\tau_{B(x,r)}\right]\simeq r^\alpha, \quad \text{for all }x\in M,\, r>0;
$$
\item The tail estimate of the exit time:
\begin{equation}
{\mathbb{P}}^x\left[\tau_{B(x,r)}\le t\right] \le C\exp\left\{-C\left(\frac{r}{t^{1/\beta}}\right)^{\beta /(\beta -1)}\right\},\quad \text{for all }t>0, \,r>0
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:10:05.652087+00:00","domain":"probability theory","id":"claim_fe6c8836869e553e358573e5a6ac54f0664d3332bddf162483e2194541d73800","kind":"lemma","schema_version":1,"statement":"[Lemma 13 (Robust separated batch) of arXiv:2608.16701, 'Order-Sensitive Fast-Synapse Limits in Sparse Excitatory--Inhibitory Threshold--Reset Netw'] Suppose that for some $\eta>0$,
\begin{equation}
 \min\{\theta-x,\ x+a-\theta,\ \theta-(x+a-b)\}\ge\eta.

\end{equation}
Use the separated supports above, but let the actual initial left voltage
and aggregate input magnitudes be $x'$, $A\ge0$, and $B\ge0$.  Suppose that
under both orderings the continuous drift rate before a first hit has
magnitude at most $L_{\rm dr}$ and that
\begin{equation}
 |x'-x|+|A-a|+|B-b|+4L_{\rm dr}\varepsilon<\eta,
 \qquad 4\varepsilon<\rho.

\end{equation}
Then the target fires exactly once in the excitatory-first system and does
not fire in the inhibitory-first system on $[0,4\varepsilon]$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:37:25.935252+00:00","domain":"probability theory","id":"claim_fe70905549f58505942846523db4e13b7e41c92fd84168671ca6c989c1986b4c","kind":"theorem","schema_version":1,"statement":"[Proposition 46 (Local interpolation polynomial) of arXiv:2608.29585, '2608.29585'] Fix $d\ge1$ and $k\ge0$.  The unique polynomial
